        Verse(book = "Nonm", chapter = 2, verseNumber = 32, text = "Men kantite gason yo te jwenn nan pèp Izrayèl la dapre branch fanmi zansèt yo. Dapre resansman yo te fè a, divizyon pa divizyon, te gen sisantwamil senksansenkant (603.550) gason antou.", bookId = 4),
        Verse(book = "Nonm", chapter = 2, verseNumber = 33, text = "Men yo pa t' konte moun branch fanmi Levi yo ansanm ak rès moun pèp Izrayèl yo, dapre lòd Seyè a te bay Moyiz la.", bookId = 4),
        Verse(book = "Nonm", chapter = 2, verseNumber = 34, text = "Moun pèp Izrayèl yo te fè tou sa Seyè a te bay Moyiz lòd fè a. Se konsa yo moute kan yo, chak divizyon apa, anba làbanyè pa yo. Lè y'ap deplase, yo mache pa divizyon, chak moun ansanm ak branch fanmi zansèt yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 3, verseNumber = 1, text = "Lè nou remoute nan tan Seyè a te pale ak Moyiz sou mòn Sinayi a, men moun ki te nan fanmi Arawon ak Moyiz.", bookId = 4),
