        Verse(book = "Nonm", chapter = 3, verseNumber = 7, text = "Y'a travay nan kay Bondye a, y'a fè tout kalite sèvis ki gen pou fèt pou Arawon ak pou pèp la devan Tant Randevou a.", bookId = 4),
        Verse(book = "Nonm", chapter = 3, verseNumber = 8, text = "Yo va reskonsab tout bagay ki anndan Tant Randevou a. Y'a fè tout travay moun Izrayèl yo ta gen pou yo fè nan Tant Randevou a.", bookId = 4),
        Verse(book = "Nonm", chapter = 3, verseNumber = 9, text = "W'a mete yo sou kont Arawon ak pitit gason l' yo. Wi, nan tout moun pèp Izrayèl yo, w'a pran moun fanmi Levi yo, w'a mete yo sou kont prèt yo pou toutan.", bookId = 4),
        Verse(book = "Nonm", chapter = 3, verseNumber = 10, text = "Men, w'a bay Arawon ak pitit gason l' yo reskonsablite tout travay prèt yo. Si yon lòt moun ki pa prèt ta konprann pou li fè travay prèt yo, se pou yo touye l'.", bookId = 4),
        Verse(book = "Nonm", chapter = 3, verseNumber = 11, text = "Seyè a pale ak Moyiz, li di l' ankò:", bookId = 4),
        Verse(book = "Nonm", chapter = 3, verseNumber = 12, text = "-Gade non! Nan tout moun pèp Izrayèl yo, mwen chwazi moun fanmi Levi yo. Mwen pran yo nan plas premye pitit gason moun pèp Izrayèl yo. Se pou mwen yo ye.", bookId = 4),
        Verse(book = "Nonm", chapter = 3, verseNumber = 13, text = "Paske, tout premye pitit gason yo se pou mwen yo ye. Depi jou mwen te touye tout premye pitit gason moun peyi Lejip yo, mwen te mete tout premye pitit gason moun pèp Izrayèl yo apa pou mwen, ansanm ak tout premye ti mal bèt yo fè. Se pou mwen menm yo tout ye. Se mwen menm ki Seyè a.", bookId = 4),
        Verse(book = "Nonm", chapter = 3, verseNumber = 14, text = "Seyè a pale ak Moyiz nan dezè Sinayi a, li di l' konsa:", bookId = 4),
        Verse(book = "Nonm", chapter = 3, verseNumber = 15, text = "-Ou pral fè resansman tout moun Levi yo, dapre fanmi yo, dapre branch fanmi zansèt yo. W'a konte tout gason depi sa ki gen yon mwa depi yo fèt jouk sa ki pi gran yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 3, verseNumber = 16, text = "Moyiz fè resansman an dapre lòd Seyè a te ba l' a. Li konte yo jan Seyè a te di l' fè l' la.", bookId = 4),
        Verse(book = "Nonm", chapter = 3, verseNumber = 17, text = "Men non twa pitit gason Levi yo: Se te Gèchon, Keyat ak Merari.", bookId = 4),
        Verse(book = "Nonm", chapter = 3, verseNumber = 18, text = "Men non pitit Gèchon yo ak tout fanmi yo: Se te Libni ak Chimèyi.", bookId = 4),
        Verse(book = "Nonm", chapter = 3, verseNumber = 19, text = "Men non pitit Keyat yo ak tout fanmi yo: Se te Amram, Jizeya, Ebwon ak Ouzyèl.", bookId = 4),
        Verse(book = "Nonm", chapter = 3, verseNumber = 20, text = "Men non pitit gason Merari yo ak tout fanmi yo: Se te Makli ak Mouchi. Men non fanmi moun Levi yo, dapre non zansèt yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 3, verseNumber = 21, text = "Te gen de fanmi nan branch Gèchon an: Se te pitit Libni yo ak pitit Chimeyi yo. Se tout fanmi Gèchon yo sa.", bookId = 4),
        Verse(book = "Nonm", chapter = 3, verseNumber = 22, text = "Lè yo konte gason yo, depi sa ki te gen yon mwa depi yo fèt jouk sa ki pi gran yo, yo jwenn sètmil senksan (7.500) gason.", bookId = 4),
        Verse(book = "Nonm", chapter = 3, verseNumber = 23, text = "Fanmi sa yo te rete dèyè kay Bondye a, sou bò solèy kouche.", bookId = 4),
        Verse(book = "Nonm", chapter = 3, verseNumber = 24, text = "Se Elyasaf, pitit gason Layèl la, ki te chèf fanmi Gèchon yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 3, verseNumber = 25, text = "Se yo ki te reskonsab kay Bondye a, ak de tant ki kouvri l' yo, rido ki nan pòt devan Tant Randevou a,", bookId = 4),
        Verse(book = "Nonm", chapter = 3, verseNumber = 26, text = "rido pou galeri ki fè wonn Tant Randevou a ak lotèl la, rido ki nan pòt devan galeri a ak tout kòd yo bezwen pou sèvi nan kay Bondye a.", bookId = 4),
        Verse(book = "Nonm", chapter = 3, verseNumber = 27, text = "Te gen kat fanmi nan branch Keyat la: Se te pitit Amram yo, pitit Jizeya yo, pitit Ebwon yo ak pitit Ouzyèl yo. Se tout fanmi Keyat yo sa.", bookId = 4),
        Verse(book = "Nonm", chapter = 3, verseNumber = 28, text = "Lè yo konte tout gason yo, depi sa ki gen yon mwa depi yo fèt jouk sa ki pi gran yo, yo jwenn witmil sisan (8.600) gason. Se yo ki te reskonsab kote ki apa nèt pou Seyè a nan kay Bondye a.", bookId = 4),
        Verse(book = "Nonm", chapter = 3, verseNumber = 29, text = "Fanmi sa yo te moute kan yo sou bò sid kay Bondye a.", bookId = 4),
        Verse(book = "Nonm", chapter = 3, verseNumber = 30, text = "Se Elizafan, pitit gason Ouzyèl la, ki te chèf fanmi Keyat yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 3, verseNumber = 31, text = "Se yo ki te reskonsab Bwat Kontra a, tab la, gwo lanp sèt branch lan, lotèl yo ak tout bagay ki sèvi nan kote ki apa nèt pou Bondye a, rido yo ansanm ak tout bagay ki mache avèk rido yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 3, verseNumber = 32, text = "Se Eleaza, pitit gason Arawon, prèt la, ki te chèf tout chèf fanmi Levi yo. Se li ki te kontwole travay moun ki te reskonsab kote ki apa nèt pou Seyè a.", bookId = 4),
        Verse(book = "Nonm", chapter = 3, verseNumber = 33, text = "Te gen de fanmi nan branch fanmi Merari a: se te pitit Makli yo ak pitit Mouchi yo. Se tout fanmi Merari yo sa.", bookId = 4),
        Verse(book = "Nonm", chapter = 3, verseNumber = 34, text = "Lè yo konte tout gason yo, depi sa ki gen yon mwa depi yo fèt jouk sa ki pi gran yo, yo jwenn simil desan (6.200) gason.", bookId = 4),
        Verse(book = "Nonm", chapter = 3, verseNumber = 35, text = "Se Zouryèl, pitit gason Abikayil la, ki te chèf fanmi Merari yo. Yo te moute kan yo sou bò nò kay Bondye a.", bookId = 4),
        Verse(book = "Nonm", chapter = 3, verseNumber = 36, text = "Se yo ki te reskonsab ankadreman pou soutni kay Bondye a, travès yo, poto yo, sipò yo ak tout rido yo ansanm ak tout bagay ki sèvi ak yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 3, verseNumber = 37, text = "Yo te reskonsab poto, sipò, pikèt ak kòd pou soutni galeri yo tou.", bookId = 4),
        Verse(book = "Nonm", chapter = 3, verseNumber = 38, text = "Moyiz, Arawon ak pitit gason l' yo te moute kay pa yo devan Tant Randevou a, sou bò lès. Se yo ki te reskonsab pou fè sèvis nan kote ki apa nèt pou Bondye a pou pèp Izrayèl la. Tout lòt moun ki ta konprann pou yo fè travay prèt yo, se pou yo touye yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 3, verseNumber = 39, text = "Lè Moyiz ak Arawon te fè resansman moun fanmi Levi yo, chak fanmi apa, dapre lòd Seyè a te bay yo a, yo jwenn antou venndemil (22.000) gason, depi sa ki te gen yon mwa depi yo te fèt jouk sa ki pi gran yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 3, verseNumber = 40, text = "Seyè a di Moyiz konsa: -Pran non tout premye pitit gason moun pèp Izrayèl yo, depi sa ki gen yon mwa depi yo fèt jouk sa ki pi gran yo. W'a konte konbe ki genyen.", bookId = 4),
        Verse(book = "Nonm", chapter = 3, verseNumber = 41, text = "Se mwen menm ki Seyè a. W'a pran moun fanmi Levi yo, w'a mete yo apa pou mwen nan plas tout premye pitit gason moun pèp Izrayèl yo. Konsa tou, w'a pran tout bèt ki pou moun fanmi Levi yo, w'a mete yo apa pou mwen nan plas premye ti mal bèt moun Izrayèl yo va fè.", bookId = 4),
        Verse(book = "Nonm", chapter = 3, verseNumber = 42, text = "Moyiz pran non tout premye pitit gason moun pèp Izrayèl yo, dapre lòd Seyè a te ba l' a.", bookId = 4),
        Verse(book = "Nonm", chapter = 3, verseNumber = 43, text = "Li konte tout premye pitit gason yo, depi sa ki te gen yon mwa jouk sa ki pi gran yo. Li jwenn venndemil desanswasanntrèz (22.273).", bookId = 4),
        Verse(book = "Nonm", chapter = 3, verseNumber = 44, text = "Apre sa, Seyè a pale ak Moyiz, li di l' konsa:", bookId = 4),
        Verse(book = "Nonm", chapter = 3, verseNumber = 45, text = "-Pran moun fanmi Levi yo, mete yo apa pou mwen nan plas premye pitit gason moun pèp Izrayèl yo. Epi w'a mete bèt moun Levi yo apa pou mwen tou nan plas premye ti mal bèt moun pèp Izrayèl yo va fè. Konsa, tout moun Levi yo va pou mwen. Se mwen menm ki Seyè a.", bookId = 4),
        Verse(book = "Nonm", chapter = 3, verseNumber = 46, text = "Ou te jwenn te gen plis premye pitit gason nan pèp Izrayèl la pase te gen moun Levi. Te gen desanswasanntrèz (273) an plis. Men sa pou yo peye pou sove lavi desansousanntrèz premye pitit gason sa yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 3, verseNumber = 47, text = "Pou yo chak, y'a bay senk pyès ajan, dapre sistèm lajan yo sèvi nan kay Bondye a: vin gara pou yon pyès ajan.", bookId = 4),
        Verse(book = "Nonm", chapter = 3, verseNumber = 48, text = "W'a pran lajan yo peye pou sove lavi sa ki an plis yo, w'a bay Arawon ak pitit gason l' yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 3, verseNumber = 49, text = "Se konsa, Moyiz pran lajan yo te peye pou sove lavi premye pitit gason ki te an plis sou kantite moun Levi yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 3, verseNumber = 50, text = "Li pran mil twasanswasannsenk (1.365) pyès lajan nan men premye pitit moun Izrayèl yo, dapre sistèm lajan yo sèvi nan kote ki apa pou Bondye a.", bookId = 4),
        Verse(book = "Nonm", chapter = 3, verseNumber = 51, text = "Apre sa, Moyiz pran tout lajan yo te peye pou sove lavi rès premye pitit gason yo, dapre lòd Seyè a te bay la, li bay Arawon ak pitit gason l' yo, jan Seyè a te ba li lòd la.", bookId = 4),
        Verse(book = "Nonm", chapter = 4, verseNumber = 1, text = "Seyè a pale ak Moyiz ansanm ak Arawon, li di yo konsa:", bookId = 4),
        Verse(book = "Nonm", chapter = 4, verseNumber = 2, text = "-Fè resansman tout pitit gason moun Keyat yo, nan branch fanmi Levi a, dapre fanmi yo, dapre branch fanmi zansèt yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 4, verseNumber = 3, text = "Pran non tout gason, depi sa ki gen trantan jouk sa ki gen senkantan, tou sa ki gen laj pou fè travay ki gen pou fèt nan Tant Randevou a.", bookId = 4),
        Verse(book = "Nonm", chapter = 4, verseNumber = 4, text = "Men travay pitit gason Keyat yo va fè nan Tant Randevou a, kote yo mete apa nèt pou Seyè a.", bookId = 4),
        Verse(book = "Nonm", chapter = 4, verseNumber = 5, text = "Lè lè a rive pou pèp la ranmase zafè yo pou yo deplase, Arawon ak pitit gason l' yo va antre nan kay Bondye a, y'a desann rido ki devan Bwat Kontra a, y'a kouvri bwat la ak li.", bookId = 4),
        Verse(book = "Nonm", chapter = 4, verseNumber = 6, text = "Y'a mete yon premye gwo nap an po bazann sou li, epi y'a kouvri l' ak yon dezyèm nap an twal ble. Apre sa, y'a pase manch pou pote bwat la nan gwo bag yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 4, verseNumber = 7, text = "Y'a kouvri tab pou pen yo ofri bay Bondye a ak yon dra ble. Y'a mete asyèt, tas, kafetyè ak bòl yo sèvi nan sèvis pou mwen yo sou li. Pen yo ofri bay Seyè a va toujou rete sou li tou.", bookId = 4),
        Verse(book = "Nonm", chapter = 4, verseNumber = 8, text = "Y'a voye yon dra wouj sou li, y'a kouvri tout ak yon nap fèt ak po bazann, epi y'a pase manch pou pote tab la nan gwo bag yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 4, verseNumber = 9, text = "Y'a pran yon dra tou ble, y'a kouvri gwo lanp sèt branch lan ak tout ti lanp li yo, pensèt li yo, plat li yo ak veso pou lwil yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 4, verseNumber = 10, text = "Y'a vlope yo ansanm nan yon nap an po bazann, epi y'a mete l' sou yon branka pou pote l'.", bookId = 4),
        Verse(book = "Nonm", chapter = 4, verseNumber = 11, text = "Apre sa, y'a mete yon dra ble sou lotèl an lò a, y'a kouvri l' nèt ak yon nap an po bazann, epi y'a pase manch pou pote lotèl la nan bag yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 4, verseNumber = 12, text = "Y'a pran tout bagay yo sèvi nan kote ki apa nèt pou Seyè a, y'a mete yo nan yon dra ble, y'a vlope yo nan yon nap an po bazann, epi y'a mete yo sou yon branka pou pote yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 4, verseNumber = 13, text = "Y'a wete sann ki sou lotèl la, epi y'a kouvri lotèl la ak yon dra wouj.", bookId = 4),
        Verse(book = "Nonm", chapter = 4, verseNumber = 14, text = "Y'a pran tout bagay ki mache ak lotèl la: recho, pèl, fouchèt, plat pou resevwa sann, y'a mete yo sou lotèl la. Apre sa, y'a kouvri l' ak yon nap an po bazann, epi y'a pase manch pou pote lotèl la.", bookId = 4),
        Verse(book = "Nonm", chapter = 4, verseNumber = 15, text = "Lè lè a va rive pou pèp la leve lamach, lè Arawon ak pitit gason l' yo va fin kouvri tout mèb ki nan kote ki apa nèt pou Seyè a, ansanm ak tout bagay ki mache ak yo a, se lè sa a gason moun Keyat yo va vin pran mèb yo pou pote yo. Moun Keyat yo pa gen dwa manyen bagay yo mete apa nèt pou Seyè a. Si yo fè sa, y'ap mouri. Se tout reskonsablite moun Keyat yo sa, lè y'ap deplase Tant Randevou a.", bookId = 4),
        Verse(book = "Nonm", chapter = 4, verseNumber = 16, text = "Eleaza, pitit gason Arawon, prèt la, va reskonsab kontwole lwil lanp yo, lansan santi bon an, pen yo toujou ofri bay Seyè a ak lwil pou mete moun apa a. Wi, l'a kontwole tout kay Bondye a nèt ak tou sa ki ladan l', menm kote ki apa nèt pou Seyè a ak bagay ki ladan l' yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 4, verseNumber = 17, text = "Seyè a pale ak Moyiz ansanm ak Arawon, li di yo konsa:", bookId = 4),
        Verse(book = "Nonm", chapter = 4, verseNumber = 18, text = "-Pa kite anyen rive moun fanmi Keyat yo ki pou ta fè yo disparèt nan mitan moun Levi yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 4, verseNumber = 19, text = "Men sa pou nou fè pou yo pa mouri, pou yo ka viv, lè y'ap pwoche bò bagay ki apa nèt pou Seyè a. Arawon ak pitit gason l' yo va antre anvan epi y'a bay chak moun travay pa yo, y'a di yo sa pou yo pote.", bookId = 4),
        Verse(book = "Nonm", chapter = 4, verseNumber = 20, text = "Men, moun Keyat yo pa janm gen dwa antre al gade lè y'ap vlope bagay ki apa nèt pou Seyè a. Si yo fè sa, y'ap mouri.", bookId = 4),
        Verse(book = "Nonm", chapter = 4, verseNumber = 21, text = "Seyè a pale ak Moyiz, li di l' konsa:", bookId = 4),
        Verse(book = "Nonm", chapter = 4, verseNumber = 22, text = "-Fè resansman tout pitit gason moun Gèchon yo tou, dapre fanmi yo, dapre branch fanmi zansèt yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 4, verseNumber = 23, text = "Pran non tout gason, depi sa ki gen trantan jouk sa ki gen senkantan, tou sa ki gen laj pou fè travay ki gen pou fèt nan Tant Randevou a.", bookId = 4),
        Verse(book = "Nonm", chapter = 4, verseNumber = 24, text = "Men travay moun Gèchon yo, men sa pou yo pote:", bookId = 4),
        Verse(book = "Nonm", chapter = 4, verseNumber = 25, text = "lèz twal ki sèvi pou moute kay Bondye a ansanm ak gwo tant ki kouvri kay Bondye a, kouvèti fèt ak po bazann ki anwo tant lan, seri rido ki fèmen pòt Tant Randevou a,", bookId = 4),
        Verse(book = "Nonm", chapter = 4, verseNumber = 26, text = "rido galeri ki kouvri tant lan ak lotèl la nèt, rido ki fèmen galeri a, kòd yo ak tout lòt bagay ki mache ak bagay sa yo. Se yo ki pou fè tout travay ki gen rapò ak bagay sa yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 4, verseNumber = 27, text = "Moun Gèchon yo va travay sou lòd Arawon ak pitit gason l' yo. Y'a fè tout travay yo, y'a pote tou sa yo gen pou yo pote. Y'a reskonsab tou sa y'ap pote a.", bookId = 4),
        Verse(book = "Nonm", chapter = 4, verseNumber = 28, text = "Sa se tout reskonsablite moun Gèchon yo nan travay ki gen pou fèt nan Tant Randevou a. Se Itama, pitit gason Arawon, prèt la, ki va kontwole tou sa y'ap fè.", bookId = 4),
        Verse(book = "Nonm", chapter = 4, verseNumber = 29, text = "Seyè a di Moyiz ankò: -W'a fè resansman tout pitit gason moun Merari yo, dapre fanmi yo, dapre branch fanmi zansèt yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 4, verseNumber = 30, text = "W'a pran non tout gason, depi sa ki gen trantan jouk sa ki gen senkantan, tou sa ki gen laj pou fè travay ki gen pou fèt nan Tant Randevou a.", bookId = 4),
        Verse(book = "Nonm", chapter = 4, verseNumber = 31, text = "Se yo menm k'ap reskonsab pote ankadreman, travès, poto ak sipò kay Bondye yo,", bookId = 4),
        Verse(book = "Nonm", chapter = 4, verseNumber = 32, text = "poto, sipò, pikèt ak kòd pou galeri ki fè wonn tant lan, avèk tout bagay ki sèvi ak yo, ansanm ak tout zouti y'ap bezwen pou fè travay yo. Y'a bay chak moun non bagay la reskonsab pou l' pote a.", bookId = 4),
        Verse(book = "Nonm", chapter = 4, verseNumber = 33, text = "Se tout reskonsablite moun Merari yo sa nan travay yo gen pou fè nan Tant Randevou a. Se Itama, pitit Arawon, prèt la, ki va ba yo sa pou yo fè.", bookId = 4),
        Verse(book = "Nonm", chapter = 4, verseNumber = 34, text = "Dapre lòd Seyè a te bay la, Moyiz, Arawon ak chèf pèp Izrayèl yo te fè resansman gason nan fanmi Keyat yo, dapre fanmi yo ak dapre branch fanmi zansèt yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 4, verseNumber = 35, text = "Yo pran non tout gason, depi sa ki gen trantan jouk sa ki gen senkantan, tou sa ki gen laj pou fè pati gwoup moun k'ap travay nan Tant Randevou a.", bookId = 4),
        Verse(book = "Nonm", chapter = 4, verseNumber = 36, text = "Yo jwenn demil sètsansenkant (2.750) gason antou nan", bookId = 4),
        Verse(book = "Nonm", chapter = 4, verseNumber = 37, text = "tout fanmi Keyat yo. Se moun sa yo ki te la pou fè travay ki gen pou fèt nan Tant Randevou a. Se yo menm Moyiz ak Arawon te konte dapre lòd Seyè a te bay Moyiz la.", bookId = 4),
        Verse(book = "Nonm", chapter = 4, verseNumber = 38, text = "Apre sa, yo fè resansman gason nan fanmi Gèchon yo, dapre fanmi yo ak dapre branch fanmi zansèt yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 4, verseNumber = 39, text = "Yo pran non tout gason, depi sa ki gen trantan jouk sa ki gen senkantan, tou sa ki gen laj pou fè pati gwoup moun k'ap travay nan Tant Randevou a.", bookId = 4),
        Verse(book = "Nonm", chapter = 4, verseNumber = 40, text = "Yo jwenn demil sisantran (2.630) gason", bookId = 4),
        Verse(book = "Nonm", chapter = 4, verseNumber = 41, text = "nan tout fanmi Gèchon yo. Se moun sa yo ki te la pou fè travay ki gen pou fèt nan Tant Randevou a. Se yo menm Moyiz ak Arawon te konte dapre lòd Seyè a te bay Moyiz la.", bookId = 4),
        Verse(book = "Nonm", chapter = 4, verseNumber = 42, text = "Apre sa, yo fè resansman gason nan fanmi Merari yo, dapre fanmi yo ak dapre branch fanmi zansèt yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 4, verseNumber = 43, text = "Yo pran non tout gason, depi sa ki gen trantan jouk sa ki gen senkantan, tou sa ki gen laj pou fè pati gwoup moun k'ap travay nan Tant Randevou a.", bookId = 4),
        Verse(book = "Nonm", chapter = 4, verseNumber = 44, text = "Yo jwenn twamil desan (3.200) gason", bookId = 4),
        Verse(book = "Nonm", chapter = 4, verseNumber = 45, text = "nan tout fanmi Merari yo. Se moun sa yo ki te la pou fè travay ki gen pou fèt nan Tant Randevou a. Se yo menm Moyiz ak Arawon te konte dapre lòd Seyè a te bay Moyiz la.", bookId = 4),
        Verse(book = "Nonm", chapter = 4, verseNumber = 46, text = "Se konsa Moyiz ak Arawon ak chèf pèp Izrayèl yo te fè resansman branch fanmi Levi yo, dapre fanmi yo ak dapre branch fanmi zansèt yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 4, verseNumber = 47, text = "Yo te pran non tout gason, depi sa ki gen trantan jouk sa ki gen senkantan, tou sa ki gen laj pou fè pati gwoup moun k'ap travay nan Tant Randevou a, osinon k'ap pote l' lè y'ap deplase.", bookId = 4),
        Verse(book = "Nonm", chapter = 4, verseNumber = 48, text = "Yo jwenn antou witmil senksankatreven (8.580) gason.", bookId = 4),
        Verse(book = "Nonm", chapter = 4, verseNumber = 49, text = "Se konsa, dapre lòd Seyè a te bay Moyiz pou pèp la, yo pran non chak gason moun Levi yo ak travay pou yo fè ak sa pou yo pote. Se Seyè a menm ki te bay Moyiz lòd fè resansman sa a.", bookId = 4),
        Verse(book = "Nonm", chapter = 5, verseNumber = 1, text = "Seyè a pale ak Moyiz, li di l' konsa:", bookId = 4),
        Verse(book = "Nonm", chapter = 5, verseNumber = 2, text = "-Bay moun pèp Izrayèl yo lòd pou yo mete deyò nan kan kote yo rete a tout moun ki gen move maladi po, moun ki gen ekoulman, osinon moun ki pa nan kondisyon pou sèvi Bondye paske yo manyen kadav moun mouri.", bookId = 4),
        Verse(book = "Nonm", chapter = 5, verseNumber = 3, text = "Wi, se pou nou mete tout moun ki pa nan kondisyon pou sèvi m' yo deyò nan kan an, fanm kou gason, pou yo pa mete kan kote m'ap viv nan mitan pèp mwen an nan kondisyon li pa ka sèvi m'.", bookId = 4),
        Verse(book = "Nonm", chapter = 5, verseNumber = 4, text = "Se konsa, moun pèp Izrayèl yo fè sa Seyè a te di Moyiz la. Yo mete tout moun sa yo deyò nan kan kote yo rete a.", bookId = 4),
        Verse(book = "Nonm", chapter = 5, verseNumber = 5, text = "Seyè a pale ak Moyiz, li di l' konsa:", bookId = 4),
        Verse(book = "Nonm", chapter = 5, verseNumber = 6, text = "-Pale ak moun pèp Izrayèl yo. Lè yon gason osinon yon fanm pa kenbe pawòl l' ak Seyè a, l' al fè yon bagay mal kont yon moun, l' antò.", bookId = 4),
        Verse(book = "Nonm", chapter = 5, verseNumber = 7, text = "Moun ki antò a va rekonèt devan tout moun li te fè yon bagay mal, epi li va renmèt tout sa l' te pran an bay moun li te fè tò a plis vin pou san (20%) lavalè.", bookId = 4),
        Verse(book = "Nonm", chapter = 5, verseNumber = 8, text = "Men, si moun li te fè tò a mouri san li pa kite yon fanmi pre ki pou resevwa sa y'ap renmèt l' a, y'a pran sa l'ap renmèt la, y'a ofri l' bay Seyè a pou prèt yo. Apre sa, moun lan ap toujou gen pou l' ofri bay Bondye yon belye mouton pou repare sa l' te fè ki mal la.", bookId = 4),
        Verse(book = "Nonm", chapter = 5, verseNumber = 9, text = "Tout ofrann moun Izrayèl yo mete apa pou Seyè a va rete pou prèt y' al jwenn pou fè ofrann lan.", bookId = 4),
        Verse(book = "Nonm", chapter = 5, verseNumber = 10, text = "Tout ofrann yon moun pote bay prèt la va rete pou prèt la. Tou sa yon moun pote renmèt va rete pou prèt la tou.", bookId = 4),
        Verse(book = "Nonm", chapter = 5, verseNumber = 11, text = "Seyè a pale ak Moyiz, li di l' konsa:", bookId = 4),
        Verse(book = "Nonm", chapter = 5, verseNumber = 12, text = "-Pale ak moun pèp Izrayèl yo. W'a di yo pou mwen: Sipoze madanm yon nonm lage kò l' nan dezòd, epi l'ap twonpe mari l',", bookId = 4),
        Verse(book = "Nonm", chapter = 5, verseNumber = 13, text = "si li kouche ak yon lòt gason san mari l' pa konn sa, si li te kache kò l' pandan li t'ap fè bagay ki mete l' nan kondisyon pou li pa ka fè sèvis pou Bondye a, kifè pa gen temwen ki pou pale kont li, ni yo pa t' kenbe l' nan men,", bookId = 4),
        Verse(book = "Nonm", chapter = 5, verseNumber = 14, text = "osinon si yon mari vin sispèk madanm li nan dezòd, kifè madanm lan pa nan kondisyon pou l' fè sèvis pou Bondye, kit madanm lan fè l' vre, kit li pa fè l',", bookId = 4),
        Verse(book = "Nonm", chapter = 5, verseNumber = 15, text = "nonm lan va mennen madanm lan bay prèt la, epi l'a pote ofrann madanm lan gen pou fè nan ka sa a: se va de liv farin lòj. Li p'ap bezwen vide lwil sou li, ni li p'ap bezwen mete lansan sou li, paske se yon ofrann l'ap fè paske li sispèk kichòy, se yon ofrann l'ap fè pou l' ka konn verite a.", bookId = 4),
        Verse(book = "Nonm", chapter = 5, verseNumber = 16, text = "Apre sa, prèt la va fè madanm lan pwoche vin kanpe devan lotèl Seyè a.", bookId = 4),
        Verse(book = "Nonm", chapter = 5, verseNumber = 17, text = "Prèt la va pran ti gout dlo nan kivèt la, l'a mete l' nan yon veso fèt an fè, l'a pran yon priz pousyè tè nan Tant Randevou a, l'a mete l' nan dlo a.", bookId = 4),
        Verse(book = "Nonm", chapter = 5, verseNumber = 18, text = "Lèfini, l'a fè madanm lan kanpe devan lotèl Seyè a, l'a wete twal ki sou tèt madanm lan, epi l'a mete ofrann farin lan nan de pla men l' yo. Prèt la menm va kenbe nan men l' veso ki gen dlo anmè a, dlo ki bay madichon an.", bookId = 4),
        Verse(book = "Nonm", chapter = 5, verseNumber = 19, text = "Prèt la va mande madanm lan pou li sèmante. L'a di l' konsa: Si ou pa kouche avèk okenn lòt gason pase avèk mari ou, si ou pa lage kò ou nan dezòd ki pou ta mete ou nan kondisyon pou ou pa ka fè sèvis pou Bondye, ou mèt bwè dlo anmè sa a, dlo ki bay madichon an, anyen p'ap rive ou.", bookId = 4),
        Verse(book = "Nonm", chapter = 5, verseNumber = 20, text = "Men, si ou te lage kò ou nan dezòd vre, si ou pa nan kondisyon pou ou fè sèvis pou Bondye, paske ou te kouche ak yon gason ki pa mari ou,", bookId = 4),
        Verse(book = "Nonm", chapter = 5, verseNumber = 21, text = "se pou Seyè a fè tout moun pran non ou pou bay madichon. Se pou l' fè ou pa ka janm fè pitit. Se pou vant ou anfle.", bookId = 4),
        Verse(book = "Nonm", chapter = 5, verseNumber = 22, text = "Se pou dlo anmè ki bay madichon an antre nan vant ou pou fè l' anfle, pou l' fè ou pa ka janm fè pitit. Madanm lan va reponn: -Mwen dakò. Se pou Seyè a fè m' sa vre, si m' antò!", bookId = 4),
        Verse(book = "Nonm", chapter = 5, verseNumber = 23, text = "Lè sa a, prèt la va ekri sèman an yon kote, epi l'a lave kote li te ekri a ak dlo anmè a pou efase sa l' te ekri a.", bookId = 4),
        Verse(book = "Nonm", chapter = 5, verseNumber = 24, text = "Apre sa, l'a fè madanm lan bwè dlo anmè ki bay madichon an, pou dlo a pase nan kò l' ba li gwo doulè nan vant.", bookId = 4),
        Verse(book = "Nonm", chapter = 5, verseNumber = 25, text = "Prèt la va pran ofrann farin lan nan men madanm lan, l'a balanse l' devan Seyè a tankou yon ofrann, epi l'a mete l' sou lotèl la.", bookId = 4),
        Verse(book = "Nonm", chapter = 5, verseNumber = 26, text = "Apre sa, l'a pran yon ponyen nan farin lan, l'a ofri l' bay Bondye, l'a boule l' sou lotèl la. Se konsa l'a mete tout farin lan nèt apa pou Seyè a. Apre sa, l'a fè fanm lan bwè dlo a.", bookId = 4),
        Verse(book = "Nonm", chapter = 5, verseNumber = 27, text = "Si fanm lan te antò vre, si li te twonpe mari l', dlo a va desann nan kò l', l'a ba li gwo doulè. Vant li va anfle, li p'ap janm ka fè pitit ankò, epi non l' va sèvi pou bay madichon.", bookId = 4),
        Verse(book = "Nonm", chapter = 5, verseNumber = 28, text = "Men, si fanm lan inonsan, si li te nan kondisyon pou fè sèvis Bondye, anyen p'ap rive l', l'ap toujou ka fè pitit.", bookId = 4),
        Verse(book = "Nonm", chapter = 5, verseNumber = 29, text = "Se regleman sa a pou yo swiv lè yon fanm pran gason sou mari l', lè li lage kò l' nan dezòd pou l' fè sa li pa t' dwe fè,", bookId = 4),
        Verse(book = "Nonm", chapter = 5, verseNumber = 30, text = "osinon lè yon nonm sispèk madanm l' ap twonpe l'. L'a mennen madanm lan devan lotèl Seyè a, epi prèt la va fè sèvis sa a pou madanm lan.", bookId = 4),
        Verse(book = "Nonm", chapter = 5, verseNumber = 31, text = "Mari a p'ap reskonsab anyen ki ka rive madanm lan. Men madanm lan, si l' antò, va pote chay peche l' la.", bookId = 4),
        Verse(book = "Nonm", chapter = 6, verseNumber = 1, text = "Seyè a pale ak Moyiz, li di l' konsa:", bookId = 4),
        Verse(book = "Nonm", chapter = 6, verseNumber = 2, text = "-Pale ak moun pèp Izrayèl yo, w'a di yo: Lè yon gason osinon yon fanm fè yon ve espesyal, ve nazareyen yo, pou li viv apa nèt pou Seyè a,", bookId = 4),
        Verse(book = "Nonm", chapter = 6, verseNumber = 3, text = "se pou l' rete san li pa bwè diven ni okenn bweson ki gen alkòl ladan l'. Ni li p'ap bwè vinèg ki fèt ak diven ni okenn lòt bweson fèmante, ni li p'ap bwè ji rezen. Ata rezen fre osinon rezen chèch li p'ap ka manje.", bookId = 4),
        Verse(book = "Nonm", chapter = 6, verseNumber = 4, text = "Pandan tout tan l'ap viv apa pou Bondye tankou yon nazareyen an, li pa gen dwa manje anyen ki soti nan pye rezen, pa menm grenn rezen an ak po a.", bookId = 4),
        Verse(book = "Nonm", chapter = 6, verseNumber = 5, text = "Pandan tout tan li fè ve pou l' viv apa pou Bondye tankou yon nazareyen an, li pa gen dwa koupe cheve nan tèt li, ni fè labab. Se pou l' kenbe ve a pandan tout tan l'ap viv apa nèt pou Bondye a, jouk lè tan ve a bout. Se pou l' kite cheve nan tèt li pouse byen long san li pa janm koupe yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 6, verseNumber = 6, text = "Pandan tout tan l'ap viv apa pou Bondye a, piga li janm pwoche bò yon kadav moun mouri,", bookId = 4),
        Verse(book = "Nonm", chapter = 6, verseNumber = 7, text = "pa menm kadav papa l', osinon kadav manman l', kadav frè l', osinon kadav sè li. Li pa fèt pou li pwoche bò kadav moun mouri pou li pa mete tèt li nan kondisyon pou l' pa ka sèvi Bondye, paske avèk cheve ki nan tèt l' a, sa vle di l'ap viv apa nèt pou Bondye.", bookId = 4),
        Verse(book = "Nonm", chapter = 6, verseNumber = 8, text = "Pandan tout tan l'ap viv apa pou Bondye a, se pou l' rete apa nèt pou Bondye.", bookId = 4),
        Verse(book = "Nonm", chapter = 6, verseNumber = 9, text = "Si yon moun rete konsa, li tonbe li mouri devan yon nazareyen, devan yon moun ki t'ap viv apa nèt pou Seyè a san koupe cheve nan tèt li, nazareyen an ap twouve l' nan kondisyon pou l' pa ka sèvi Bondye ankò. Se pou l' tann sèt jou anvan l'a nan kondisyon pou l' ka fè sèvis Bondye ankò. Jou sa a, l'a koupe tout cheve nan tèt li.", bookId = 4),
        Verse(book = "Nonm", chapter = 6, verseNumber = 10, text = "Sou wityèm jou a, l'a pran de toutrèl osinon de pijon, l'a pote yo bay prèt la devan pòt Tant Randevou a.", bookId = 4),
        Verse(book = "Nonm", chapter = 6, verseNumber = 11, text = "Prèt la va ofri yo bay Seyè a, yonn pou repare sa li te fè ki mal la, lòt la pou yo boule sou lotèl la. Se konsa l'a ofri bèt pou yo touye pou peche moun lan fè a akòz kontak li te gen avèk kadav moun mouri a.", bookId = 4),
        Verse(book = "Nonm", chapter = 6, verseNumber = 12, text = "Nonm lan va refè ve li te fè pou l' viv apa nèt pou Bondye a. Tou sa li te fè anvan an pa vo anyen ankò, paske ve li te fè a gate. Epi l'a pote yon ti mouton ki poko gen ennan pou yo ofri pou repare sa li te fè ki mal la.", bookId = 4),
        Verse(book = "Nonm", chapter = 6, verseNumber = 13, text = "Men sèvis yon nazareyen va fè lè tan pou l' kenbe ve l' te fè a bout. Y'a mennen l' devan pòt Tant Randevou a.", bookId = 4),
        Verse(book = "Nonm", chapter = 6, verseNumber = 14, text = "L'a ofri twa bèt ki san okenn enfimite bay Seyè a: yon ti belye mouton ki poko gen ennan, yon ti fenmèl mouton ki poko gen ennan ak yon gwo belye mouton. Ti belye mouton an va sèvi ofrann pou boule nèt pou Seyè a, ti fenmèl mouton va sèvi ofrann pou wete peche, ak gwo belye mouton an va sèvi ofrann pou di Bondye mèsi.", bookId = 4),
        Verse(book = "Nonm", chapter = 6, verseNumber = 15, text = "L'a ofri tou yon panyen pen san ledven: pen gwo mit fèt avèk farin frans melanje ak lwil oliv ak ti pen plat ak lwil pase sou yo, ansanm ak ofrann grenn jaden ak ofrann diven ki mache ak yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 6, verseNumber = 16, text = "Prèt la va ofri yo pou li devan lotèl Seyè a. L'a fè sèvis pou repare sa moun lan te fè ki mal la, epi l'a boule ofrann l' a nan dife.", bookId = 4),
        Verse(book = "Nonm", chapter = 6, verseNumber = 17, text = "L'a touye belye mouton an, l'a ofri l' pou di Bondye mèsi ansanm ak panyen pen san ledven an. Lèfini, l'a fè ofrann grenn jaden ak ofrann diven ki mache ak yo a.", bookId = 4),
        Verse(book = "Nonm", chapter = 6, verseNumber = 18, text = "Lè sa a, nazareyen an va koupe tout cheve nan tèt li devan pòt Tant Randevou a, l'a pran cheve yo, l'a mete yo nan dife kote ofrann pou di Bondye mèsi a ap boule.", bookId = 4),
        Verse(book = "Nonm", chapter = 6, verseNumber = 19, text = "Apre nazareyen an fin fè sa, prèt la va pran jigo mouton yo te kwit la, yon pen gwo mit ak yon ti pen plat nan panyen an, l'a mete tou sa nan pla men nazareyen an.", bookId = 4),
        Verse(book = "Nonm", chapter = 6, verseNumber = 20, text = "Lèfini, prèt la va balanse yo tankou yon ofrann devan Seyè a: pòsyon sa yo va yon bagay yo mete apa pou Bondye, y'a rete pou prèt la anplis vyann pwatrin lan ak jigo ki te pou li deja a. Apre sa, nazareyen an gen dwa bwè diven.", bookId = 4),
        Verse(book = "Nonm", chapter = 6, verseNumber = 21, text = "Se tout regleman yo sa pou moun ki fè ve nazareyen yo swiv. Y'a fè ofrann yo bay Seyè a dapre ve yo te fè pou yo viv apa nèt pou Seyè a. Men, si yon moun pwomèt pou li ofri lòt bagay anplis sa yo mande l' la a, se pou l' fè tou sa li te pwomèt pou l' fè a.", bookId = 4),
        Verse(book = "Nonm", chapter = 6, verseNumber = 22, text = "Seyè a di Moyiz konsa:", bookId = 4),
        Verse(book = "Nonm", chapter = 6, verseNumber = 23, text = "-Pale ak Arawon ansanm ak pitit gason l' yo. W'a di yo men sa pou nou di lè n'ap beni pèp Izrayèl la:", bookId = 4),
        Verse(book = "Nonm", chapter = 6, verseNumber = 24, text = "Se pou Seyè a beni nou, se pou l' pran swen nou.", bookId = 4),
        Verse(book = "Nonm", chapter = 6, verseNumber = 25, text = "Se pou Seyè a fè nou santi li la avèk nou, se pou l' gen pitye pou nou.", bookId = 4),
        Verse(book = "Nonm", chapter = 6, verseNumber = 26, text = "Se pou Seyè a fè nou wè jan li renmen nou, se pou l' ban nou kè poze.", bookId = 4),
        Verse(book = "Nonm", chapter = 6, verseNumber = 27, text = "Se konsa y'a nonmen non m', y'a lapriyè nan pye m' pou pèp Izrayèl la, epi m'a beni yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 7, verseNumber = 1, text = "Jou Moyiz te fin moute kay Bondye a, li vide lwil sou li pou mete l' apa pou Bondye, li fè sèvis pou mete l' apa pou Bondye ansanm ak tout bagay ki mache avè l' nan tant lan, lotèl la ak tout bagay ki sèvi sou lotèl la.", bookId = 4),
        Verse(book = "Nonm", chapter = 7, verseNumber = 2, text = "Apre sa, chèf fanmi moun Izrayèl yo, chèf douz branch fanmi pèp Izrayèl la, vin pote ofrann yo. Se chèf sa yo ki te reskonsab fè resansman an.", bookId = 4),
        Verse(book = "Nonm", chapter = 7, verseNumber = 3, text = "Men sa yo te ofri bay Seyè a: sis kabwa ak douz towo bèf, ki vle di yon kabwa pou chak de chèf ak yon bèf pou chak chèf. Yo mennen yo devan kay Bondye a epi yo ofri yo bay Bondye.", bookId = 4),
        Verse(book = "Nonm", chapter = 7, verseNumber = 4, text = "Lè sa a, Seyè a di Moyiz konsa:", bookId = 4),
        Verse(book = "Nonm", chapter = 7, verseNumber = 5, text = "-Ou mèt asepte kado sa yo nan men yo. W'a sèvi ak yo nan travay ki gen pou fèt nan Tant Randevou a. W'a bay moun fanmi Levi yo kabwa yo, dapre travay ki sou kont yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 7, verseNumber = 6, text = "Se konsa, Moyiz pran kabwa yo ak bèf yo, li bay moun Levi yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 7, verseNumber = 7, text = "Li bay moun fanmi Gèchon yo de kabwa ak kat bèf, dapre travay li konnen ki sou kont yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 7, verseNumber = 8, text = "Li bay moun fanmi Merari yo kat kabwa ak wit bèf, dapre travay li konnen ki sou kont yo, travay pou yo fè sou lòd Itama, pitit Arawon, prèt la.", bookId = 4),
        Verse(book = "Nonm", chapter = 7, verseNumber = 9, text = "Men li pa bay noun Keyat yo anyen, paske se sou zepòl yo pou yo pote tout bagay ki nan kote ki apa nèt pou Bondye a.", bookId = 4),
        Verse(book = "Nonm", chapter = 7, verseNumber = 10, text = "Chèf yo te fè lòt ofrann pou lotèl la, jou yo t'ap vide lwil sou li pou mete l' apa pou sèvis Bondye a. Yo mete ofrann yo devan lotèl la.", bookId = 4),
        Verse(book = "Nonm", chapter = 7, verseNumber = 11, text = "Seyè a di Moyiz konsa: -Chèf yo va pote ofrann yo pou sèvis y'ap fè pou mete lotèl la apa pou mwen. Y'a vini yonn apre lòt, yonn chak jou.", bookId = 4),
        Verse(book = "Nonm", chapter = 7, verseNumber = 12, text = "Chèf yo vini vre, yo fè ofrann yo yonn apre lòt. Premye jou a, se te tou pa Nakchon, pitit gason Aminadab la, chèf branch fanmi Jida a.", bookId = 4),
        Verse(book = "Nonm", chapter = 7, verseNumber = 13, text = "Men sa li te ofri: yon bòl an ajan ki peze twa liv enka, yon plat an ajan ki peze yon liv twaka, dapre sistèm yo sèvi nan tanp lan. Ni bòl la ni plat la te plen farin frans melanje ak lwil ki te sèvi pou ofrann grenn jaden yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 7, verseNumber = 14, text = "Li te ofri tou yon kiyè an lò, ki peze yon ka liv, plen lansan,", bookId = 4),
        Verse(book = "Nonm", chapter = 7, verseNumber = 15, text = "yon jenn ti towo bèf, yon belye mouton ak yon ti mouton ki poko gen ennan, tou sa pou yo boule nèt pou Seyè a.", bookId = 4),
        Verse(book = "Nonm", chapter = 7, verseNumber = 16, text = "Li te ofri ankò yon bouk pou yo touye pou repare sa yo fè ki mal,", bookId = 4),
        Verse(book = "Nonm", chapter = 7, verseNumber = 17, text = "de towo, senk belye, senk bouk, senk ti mouton ki poko gen ennan pou ofrann pou di Bondye mèsi. Se ofrann sa a Nakchon, pitit gason Anminadab la, te ofri bay Seyè a.", bookId = 4),
        Verse(book = "Nonm", chapter = 7, verseNumber = 18, text = "Dezyèm jou a, se te tou pa Netanèl, pitit gason Zwa a, chèf branch fanmi Isaka a.", bookId = 4),
        Verse(book = "Nonm", chapter = 7, verseNumber = 19, text = "Li ofri menm bagay ak Nakchon.", bookId = 4),
        Verse(book = "Nonm", chapter = 7, verseNumber = 20, text = "Li ofri menm bagay ak Nakchon.", bookId = 4),
        Verse(book = "Nonm", chapter = 7, verseNumber = 21, text = "Li ofri menm bagay ak Nakchon.", bookId = 4),
        Verse(book = "Nonm", chapter = 7, verseNumber = 22, text = "Li ofri menm bagay ak Nakchon.", bookId = 4),
        Verse(book = "Nonm", chapter = 7, verseNumber = 23, text = "Li ofri menm bagay ak Nakchon.", bookId = 4),
        Verse(book = "Nonm", chapter = 7, verseNumber = 24, text = "Twazyèm jou a, se te tou pa Eliyab, pitit gason Elon an, chèf branch fanmi Zabilon an.", bookId = 4),
        Verse(book = "Nonm", chapter = 7, verseNumber = 25, text = "Li ofri menm bagay ak Nakchon.", bookId = 4),
        Verse(book = "Nonm", chapter = 7, verseNumber = 26, text = "Li ofri menm bagay ak Nakchon.", bookId = 4),
        Verse(book = "Nonm", chapter = 7, verseNumber = 27, text = "Li ofri menm bagay ak Nakchon.", bookId = 4),
        Verse(book = "Nonm", chapter = 7, verseNumber = 28, text = "Li ofri menm bagay ak Nakchon.", bookId = 4),
        Verse(book = "Nonm", chapter = 7, verseNumber = 29, text = "Li ofri menm bagay ak Nakchon.", bookId = 4),
        Verse(book = "Nonm", chapter = 7, verseNumber = 30, text = "Katriyèm jou a, se te pou pa Elizou, pitit gason Chedeyou a, chèf branch fanmi Woubenn lan.", bookId = 4),
        Verse(book = "Nonm", chapter = 7, verseNumber = 31, text = "Li ofri menm bagay ak Nakchon.", bookId = 4),
        Verse(book = "Nonm", chapter = 7, verseNumber = 32, text = "Li ofri menm bagay ak Nakchon.", bookId = 4),
        Verse(book = "Nonm", chapter = 7, verseNumber = 33, text = "Li ofri menm bagay ak Nakchon.", bookId = 4),
        Verse(book = "Nonm", chapter = 7, verseNumber = 34, text = "Li ofri menm bagay ak Nakchon.", bookId = 4),
        Verse(book = "Nonm", chapter = 7, verseNumber = 35, text = "Li ofri menm bagay ak Nakchon.", bookId = 4),
        Verse(book = "Nonm", chapter = 7, verseNumber = 36, text = "Senkyèm jou a, se te tou pa Cheloumyèl, pitit gason Sourichadayi a, chèf branch fanmi Simeyon an.", bookId = 4),
        Verse(book = "Nonm", chapter = 7, verseNumber = 37, text = "Li ofri menm bagay ak Nakchon.", bookId = 4),
        Verse(book = "Nonm", chapter = 7, verseNumber = 38, text = "Li ofri menm bagay ak Nakchon.", bookId = 4),
        Verse(book = "Nonm", chapter = 7, verseNumber = 39, text = "Li ofri menm bagay ak Nakchon.", bookId = 4),
        Verse(book = "Nonm", chapter = 7, verseNumber = 40, text = "Li ofri menm bagay ak Nakchon.", bookId = 4),
        Verse(book = "Nonm", chapter = 7, verseNumber = 41, text = "Li ofri menm bagay ak Nakchon.", bookId = 4),
        Verse(book = "Nonm", chapter = 7, verseNumber = 42, text = "Sizyèm jou a, se te tou pa Elyasaf, pitit gason Dewèl la, chèf branch fanmi Gad la.", bookId = 4),
        Verse(book = "Nonm", chapter = 7, verseNumber = 43, text = "Li ofri menm bagay ak Nakchon.", bookId = 4),
        Verse(book = "Nonm", chapter = 7, verseNumber = 44, text = "Li ofri menm bagay ak Nakchon.", bookId = 4),
        Verse(book = "Nonm", chapter = 7, verseNumber = 45, text = "Li ofri menm bagay ak Nakchon.", bookId = 4),
        Verse(book = "Nonm", chapter = 7, verseNumber = 46, text = "Li ofri menm bagay ak Nakchon.", bookId = 4),
        Verse(book = "Nonm", chapter = 7, verseNumber = 47, text = "Li ofri menm bagay ak Nakchon.", bookId = 4),
        Verse(book = "Nonm", chapter = 7, verseNumber = 48, text = "Setyèm jou a, se te tou pa Elichama, pitit gason Amiyoud la, chèf branch fanmi Efrayim lan.", bookId = 4),
        Verse(book = "Nonm", chapter = 7, verseNumber = 49, text = "Li ofri menm bagay ak Nakchon.", bookId = 4),
        Verse(book = "Nonm", chapter = 7, verseNumber = 50, text = "Li ofri menm bagay ak Nakchon.", bookId = 4),
        Verse(book = "Nonm", chapter = 7, verseNumber = 51, text = "Li ofri menm bagay ak Nakchon.", bookId = 4),
        Verse(book = "Nonm", chapter = 7, verseNumber = 52, text = "Li ofri menm bagay ak Nakchon.", bookId = 4),
        Verse(book = "Nonm", chapter = 7, verseNumber = 53, text = "Li ofri menm bagay ak Nakchon.", bookId = 4),
        Verse(book = "Nonm", chapter = 7, verseNumber = 54, text = "Uityèm jou a, se te tou pa Gamliyèl, pitit gason Pedachou a, chèf branch fanmi Manase a.", bookId = 4),
        Verse(book = "Nonm", chapter = 7, verseNumber = 55, text = "Li ofri menm bagay ak Nakchon.", bookId = 4),
        Verse(book = "Nonm", chapter = 7, verseNumber = 56, text = "Li ofri menm bagay ak Nakchon.", bookId = 4),
        Verse(book = "Nonm", chapter = 7, verseNumber = 57, text = "Li ofri menm bagay ak Nakchon.", bookId = 4),
        Verse(book = "Nonm", chapter = 7, verseNumber = 58, text = "Li ofri menm bagay ak Nakchon.", bookId = 4),
        Verse(book = "Nonm", chapter = 7, verseNumber = 59, text = "Li ofri menm bagay ak Nakchon.", bookId = 4),
        Verse(book = "Nonm", chapter = 7, verseNumber = 60, text = "Nevyèm jou a, se te tou pa Abidan, pitit gason Gideyoni an, chèf branch fanmi Benjamen an.", bookId = 4),
        Verse(book = "Nonm", chapter = 7, verseNumber = 61, text = "Li ofri menm bagay ak Nakchon.", bookId = 4),
        Verse(book = "Nonm", chapter = 7, verseNumber = 62, text = "Li ofri menm bagay ak Nakchon.", bookId = 4),
        Verse(book = "Nonm", chapter = 7, verseNumber = 63, text = "Li ofri menm bagay ak Nakchon.", bookId = 4),
        Verse(book = "Nonm", chapter = 7, verseNumber = 64, text = "Li ofri menm bagay ak Nakchon.", bookId = 4),
        Verse(book = "Nonm", chapter = 7, verseNumber = 65, text = "Li ofri menm bagay ak Nakchon.", bookId = 4),
        Verse(book = "Nonm", chapter = 7, verseNumber = 66, text = "Dizyèm jou a, se te tou pa Ayezè, pitit gason Amichadayi a, chèf branch fanmi Dann lan.", bookId = 4),
        Verse(book = "Nonm", chapter = 7, verseNumber = 67, text = "Li ofri menm bagay ak Nakchon.", bookId = 4),
        Verse(book = "Nonm", chapter = 7, verseNumber = 68, text = "Li ofri menm bagay ak Nakchon.", bookId = 4),
        Verse(book = "Nonm", chapter = 7, verseNumber = 69, text = "Li ofri menm bagay ak Nakchon.", bookId = 4),
        Verse(book = "Nonm", chapter = 7, verseNumber = 70, text = "Li ofri menm bagay ak Nakchon.", bookId = 4),
        Verse(book = "Nonm", chapter = 7, verseNumber = 71, text = "Li ofri menm bagay ak Nakchon.", bookId = 4),
        Verse(book = "Nonm", chapter = 7, verseNumber = 72, text = "Onzyèm jou a, se te tou pa Pagiyèl, pitit gason Okran an, chèf branch fanmi Asè a.", bookId = 4),
        Verse(book = "Nonm", chapter = 7, verseNumber = 73, text = "Li ofri menm bagay ak Nakchon.", bookId = 4),
        Verse(book = "Nonm", chapter = 7, verseNumber = 74, text = "Li ofri menm bagay ak Nakchon.", bookId = 4),
        Verse(book = "Nonm", chapter = 7, verseNumber = 75, text = "Li ofri menm bagay ak Nakchon.", bookId = 4),
        Verse(book = "Nonm", chapter = 7, verseNumber = 76, text = "Li ofri menm bagay ak Nakchon.", bookId = 4),
        Verse(book = "Nonm", chapter = 7, verseNumber = 77, text = "Li ofri menm bagay ak Nakchon.", bookId = 4),
        Verse(book = "Nonm", chapter = 7, verseNumber = 78, text = "Douzyèm jou a, se te tou pa Ayira, pitit gason Enan an, chèf branch fanmi Neftali a.", bookId = 4),
        Verse(book = "Nonm", chapter = 7, verseNumber = 79, text = "Li ofri menm bagay ak Nakchon.", bookId = 4),
