        Verse(book = "Nonm", chapter = 7, verseNumber = 82, text = "Li ofri menm bagay ak Nakchon.", bookId = 4),
        Verse(book = "Nonm", chapter = 7, verseNumber = 83, text = "Li ofri menm bagay ak Nakchon.", bookId = 4),
        Verse(book = "Nonm", chapter = 7, verseNumber = 84, text = "Men ofrann tout chèf yo te pote pou lotèl la, jou yo t'ap vide lwil sou li pou mete l' apa pou sèvis Bondye a: douz bòl an ajan, douz plat an ajan, douz kiyè an lò.", bookId = 4),
        Verse(book = "Nonm", chapter = 7, verseNumber = 85, text = "Chak bòl an ajan te peze twa liv enka, chak plat an ajan te peze yon liv twaka. Sa te fè antou swasant liv ajan, dapre sistèm yo sèvi nan tanp lan.", bookId = 4),
        Verse(book = "Nonm", chapter = 7, verseNumber = 86, text = "Chak kiyè an lò pou lansan an te peze yon ka liv, dapre sistèm pèz yo sèvi nan kay Bondye a. Sa te fè antou pou douz kiyè yo twa liv lò.", bookId = 4),
        Verse(book = "Nonm", chapter = 7, verseNumber = 87, text = "Men kantite bèt yo te ofri antou pou boule nèt pou Seyè a ansanm ak ofrann grenn jaden ki mache ak yo: douz towo, douz belye, douz ti mouton ki poko gen ennan. Yo te bay douz bouk tou pou yo touye pou repare sa yo fè ki mal.", bookId = 4),
        Verse(book = "Nonm", chapter = 7, verseNumber = 88, text = "Men kantite bèt yo te ofri an total pou di Bondye mèsi: vennkat jenn ti towo, swasant belye, swasant bouk ak swasant ti mouton ki poko gen ennan. Se ofrann sa a yo te fè pou mete lotèl la apa nèt pou sèvis Seyè a, apre yo te fin vide lwil sou li.", bookId = 4),
        Verse(book = "Nonm", chapter = 7, verseNumber = 89, text = "Chak fwa Moyiz te antre nan Tant Randevou a pou l' pale ak Seyè a, li te tande vwa Seyè a ki t'ap pale avè l' anwo kouvèti espesyal ki sou Bwat Kontra a, nan mitan de zanj cheriben yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 8, verseNumber = 1, text = "Seyè a pale ak Moyiz, li di l' konsa:", bookId = 4),
        Verse(book = "Nonm", chapter = 8, verseNumber = 2, text = "-Pale ak Arawon. W'a di l' konsa: Lè l'ap fè moute sèt ti lanp yo sou pye gwo lanp sèt branch lan, ranje yo yon jan pou yo klere sou devan gwo lanp sèt branch lan.", bookId = 4),
        Verse(book = "Nonm", chapter = 8, verseNumber = 3, text = "Arawon swiv lòd Seyè a te bay Moyiz la: li fè moute ti lanp yo pou yo ka klere sou devan gwo lanp sèt branch lan.", bookId = 4),
        Verse(book = "Nonm", chapter = 8, verseNumber = 4, text = "Men ki jan gwo lanp lan te fèt: tout kò a nèt te fèt ak pi bon lò ki genyen. Yo te fè depi pye gwo lanp lan jouk flè yo nan yon sèl gwo moso lò, dapre modèl Seyè a te fè Moyiz wè nan vizyon an.", bookId = 4),
        Verse(book = "Nonm", chapter = 8, verseNumber = 5, text = "Seyè a pale ak Mwiz, li di l' konsa:", bookId = 4),
        Verse(book = "Nonm", chapter = 8, verseNumber = 6, text = "-Wete moun Levi yo nan mitan rès pèp Izrayèl la. Mete yo nan kondisyon pou yo ka fè sèvis pou mwen.", bookId = 4),
        Verse(book = "Nonm", chapter = 8, verseNumber = 7, text = "Men ki jan w'a fè l': W'a pran nan dlo pou wete peche a, w'a voye l' sou yo. Apre sa, y'a koupe cheve ak pwal sou tout kò yo nèt, epi y'a lave rad ki sou yo. Se konsa y'a nan kondisyon pou fè sèvis pou mwen.", bookId = 4),
        Verse(book = "Nonm", chapter = 8, verseNumber = 8, text = "Apre sa, moun Levi yo va pran yon jenn ti towo ansanm ak ofrann grenn jaden ki pou mache avè l' la, ki vle di ti gout farin frans melanje ak lwil. Ou menm, w'a pran yon dezyèm ti towo tou jenn pou ou touye pou repare sa yo fè ki mal.", bookId = 4),
        Verse(book = "Nonm", chapter = 8, verseNumber = 9, text = "Apre sa, w'a fè moun Levi yo pwoche dèvan pòt Tant Randevou a, epi w'a fè tout moun pèp Izrayèl yo sanble.", bookId = 4),
        Verse(book = "Nonm", chapter = 8, verseNumber = 10, text = "Y'a poze men yo sou tèt moun Levi yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 8, verseNumber = 11, text = "Lèfini, Arawon va pran moun Levi yo, l'a vire yo adwat, l'a vire yo agoch devan mwen menm, Seyè a, tankou yon ofrann espesyal moun pèp Izrayèl yo ap fè m' pou moun Levi yo ka fè sèvis mwen.", bookId = 4),
        Verse(book = "Nonm", chapter = 8, verseNumber = 12, text = "Apre sa, moun Levi yo va poze men yo sou tèt ti towo bèf yo, w'a ofri yonn pou mande padon pou peche yo, w'a ofri lòt la pou yo boule nèt pou mwen. Se konsa y'a fè sèvis pou mande m' gras pou moun Levi yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 8, verseNumber = 13, text = "Mete moun Levi yo apa tankou yon kado espesyal moun yo fè m'. Mete yo sou zòd Arawon ak pitit gason l' yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 8, verseNumber = 14, text = "W'a wete moun Levi yo nan mitan rès pèp Izrayèl la, konsa moun Levi yo va pou mwen nèt ale.", bookId = 4),
        Verse(book = "Nonm", chapter = 8, verseNumber = 15, text = "Lè w'a fin mete moun Levi yo nan kondisyon pou fè sèvis pou mwen, lè w'a fin vire yo adwat agoch devan m', tankou yon kado espesyal moun yo fè m', y'a gen dwa pwoche vin fè travay yo nan Tant Randevou a.", bookId = 4),
        Verse(book = "Nonm", chapter = 8, verseNumber = 16, text = "N'a wete yo nan mitan rès pèp Izrayèl la, n'a fè m' kado yo nèt. Mwen va pran yo pou mwen nan plas tout premye pitit gason moun pèp Izrayèl yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 8, verseNumber = 17, text = "Paske, tout premye pitit gason moun pèp Izrayèl yo ak tout premye ti mal bèt yo fè se pou mwen yo ye. Depi jou mwen te touye tout premye pitit moun peyi Lejip yo, wi depi jou sa a mwen mete premye pitit nou yo apa pou mwen.", bookId = 4),
        Verse(book = "Nonm", chapter = 8, verseNumber = 18, text = "Koulye a, mwen pran moun Levi yo nan plas premye pitit moun pèp Izrayèl yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 8, verseNumber = 19, text = "Mwen pran moun Levi yo tankou yon kado moun yo fè m', mwen renmèt yo nan men Arawon ak pitit gason l' yo pou yo fè travay moun Izrayèl yo gen pou yo fè nan Tant Randevou a, pou mande Bondye gras pou pèp la. Konsa, okenn malè p'ap rive tonbe sou pèp la paske yo p'ap janm bezwen pwoche twò pre kote ki apa nèt pou mwen nan tanp lan.", bookId = 4),
        Verse(book = "Nonm", chapter = 8, verseNumber = 20, text = "Se konsa, Moyiz, Arawon ak tout pèp Izrayèl la mete moun Levi yo apa nèt pou Seyè a, jan li te bay Moyiz lòd la. Wi, yo te fè tou sa pou yo te fè pou moun Levi yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 8, verseNumber = 21, text = "Moun Levi yo fè sèvis pou peye pou tou sa yo te fè ki mal, yo lave rad ki sou yo. Arawon mete yo apa devan Seyè a, li vire yo adwat agoch devan Seyè a tankou yon kado espesyal pou Bondye, epi li fè sèvis pou mande gras pou yo te ka nan kondisyon sèvi Bondye.", bookId = 4),
        Verse(book = "Nonm", chapter = 8, verseNumber = 22, text = "Apre sa, moun Levi yo antre al fè travay yo nan Tant Randevou a sou lòd Arawon ak pitit gason l' yo. Se konsa pèp la te fè pou moun Levi yo tou sa Seyè a te bay Moyiz lòd fè a.", bookId = 4),
        Verse(book = "Nonm", chapter = 8, verseNumber = 23, text = "Seyè a pale ak Moyiz ankò, li di l' konsa:", bookId = 4),
        Verse(book = "Nonm", chapter = 8, verseNumber = 24, text = "-Sa mwen pral di ou la a, se pou moun Levi yo: Depi yo rive laj vennsenkan y'a fè pati gwoup moun k'ap travay nan Tant Randevou a.", bookId = 4),
        Verse(book = "Nonm", chapter = 8, verseNumber = 25, text = "Lè y'a gen senkantan, y'a pran retrèt yo, yo p'ap reskonsab okenn travay ankò nan tant lan.", bookId = 4),
        Verse(book = "Nonm", chapter = 8, verseNumber = 26, text = "Men, y'a gen dwa ede moun Levi parèy yo nan nenpòt travay y'ap fè nan Tant Randevou a. Men yo menm poutèt pa yo, yo p'ap reskonsab okenn travay ankò. Se konsa w'a bay moun Levi yo travay pou yo fè.", bookId = 4),
        Verse(book = "Nonm", chapter = 9, verseNumber = 1, text = "Nan premye mwa dezyèm lanne apre yo te soti kite peyi Lejip la, Seyè a pale ak Moyiz nan dezè Sinayi a, li di l' konsa:", bookId = 4),
        Verse(book = "Nonm", chapter = 9, verseNumber = 2, text = "-Se pou tout moun pèp Izrayèl yo fete fèt delivrans lan dat mwen te di yo fete l' la.", bookId = 4),
        Verse(book = "Nonm", chapter = 9, verseNumber = 3, text = "Katòzyèm jou premye mwa a, lè solèy fin kouche, n'a fete fèt la dapre tout lòd ak regleman mwen te ban nou pou sa.", bookId = 4),
        Verse(book = "Nonm", chapter = 9, verseNumber = 4, text = "Moyiz di pèp Izrayèl la pou yo fete fèt delivrans lan.", bookId = 4),
        Verse(book = "Nonm", chapter = 9, verseNumber = 5, text = "Epi yo fete fèt la nan aswè katòzyèm jou premye mwa a, nan dezè Sinayi a. Pèp la fè tout bagay jan Seyè a te bay Moyiz lòd fè a.", bookId = 4),
        Verse(book = "Nonm", chapter = 9, verseNumber = 6, text = "Men, vwala te gen kèk moun ki pa t' nan kondisyon pou fè sèvis pou Bondye, paske yo te manyen kadav yon moun mouri. Yo pa t' kapab fete fèt delivrans lan jou sa a. Yo leve, y' al jwenn Moyiz ak Arawon.", bookId = 4),
        Verse(book = "Nonm", chapter = 9, verseNumber = 7, text = "Yo di yo: -Nou pa nan kondisyon pou nou fè sèvis pou Bondye, paske nou te manyen yon kadav moun mouri. Men, poukisa nou pa ta ka pote ofrann nou yo bay Seyè a jou sa a, ansanm ak tout moun pèp Izrayèl yo?", bookId = 4),
        Verse(book = "Nonm", chapter = 9, verseNumber = 8, text = "Moyiz reponn yo: -Rete tann jouk Seyè a va ban m' lòd sa pou m' di nou.", bookId = 4),
        Verse(book = "Nonm", chapter = 9, verseNumber = 9, text = "Seyè a pale ak Moyiz, li di l' konsa:", bookId = 4),
        Verse(book = "Nonm", chapter = 9, verseNumber = 10, text = "-Pale ak moun pèp Izrayèl yo, w'a di yo pou mwen: Lè yonn nan nou, osinon yonn nan pitit pitit nou yo, twouve li pa ta nan kondisyon pou fè sèvis pou Bondye, paske li te manyen kadav yon moun mouri, ou ankò si li ta nan vwayaj byen lwen, l'a toujou ka fete fèt Delivrans lan pou Bondye.", bookId = 4),
        Verse(book = "Nonm", chapter = 9, verseNumber = 11, text = "Y'a tann katòzyèm jou dizyèm mwa a, lè sòlèy fin kouche, pou yo fè l'. Y'a manje manje Delivrans lan avèk pen san ledven yo epi ak fèy lanman.", bookId = 4),
        Verse(book = "Nonm", chapter = 9, verseNumber = 12, text = "Yo p'ap gen dwa kite anyen pou denmen maten, ni yo pa fèt pou yo kraze okenn zo bèt yo touye a. Y'a fè tout bagay dapre regleman mwen bay pou fete fèt Delivrans lan.", bookId = 4),
        Verse(book = "Nonm", chapter = 9, verseNumber = 13, text = "Men, si yon moun ki nan kondisyon pou fè sèvis pou mwen epi ki pa nan vwayaj ta rive pa fete fèt Delivrans lan, se pou yo mete l' deyò nèt nan mitan fanmi l' yo, paske li pa t' ofri ofrann li bay Seyè a dat pou l' te fè l' la. Se pou l' peye pou sa l' fè a.", bookId = 4),
        Verse(book = "Nonm", chapter = 9, verseNumber = 14, text = "Si gen moun lòt nasyon k'ap viv nan mitan nou, li menm tou se pou l' fete fèt Delivrans Seyè a, dapre lòd ak regleman fèt la. Va gen yon sèl regleman pou tout moun, ni pou moun natif natal peyi a, ni pou moun lòt nasyon yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 9, verseNumber = 15, text = "Jou yo t'ap moute Tant Randevou a, yon nwaj vini epi li kouvri tant kote Bwat Kontra a ye a. Lè aswè rive, ou ta di yon gwo dife ki te parèt anwo tant lan jouk nan maten.", bookId = 4),
        Verse(book = "Nonm", chapter = 9, verseNumber = 16, text = "Se konsa sa te toujou ye: lajounen nwaj la te kouvri l', lannwit li te klere tankou yon dife.", bookId = 4),
        Verse(book = "Nonm", chapter = 9, verseNumber = 17, text = "Chak fwa nwaj la fè yon leve anwo tant lan, la menm moun pèp Izrayèl yo leve, epi yo pati. Lè li desann poze sou tant lan, yo rete, yo moute tant yo la.", bookId = 4),
        Verse(book = "Nonm", chapter = 9, verseNumber = 18, text = "Konsa, se sou kòmandman Seyè a yo te leve pati, e se sou kòmandman li tou yo te rete moute tant yo. Toutotan nwaj la te rete anwo tant lan, yo menm tou, yo te rete kote yo te ye a.", bookId = 4),
        Verse(book = "Nonm", chapter = 9, verseNumber = 19, text = "Si nwaj la te rete anpil jou anwo tant lan san deplase, moun pèp Izrayèl yo te swiv lòd Seyè a, yo menm tou yo pa t' deplase.", bookId = 4),
        Verse(book = "Nonm", chapter = 9, verseNumber = 20, text = "Gen de fwa nwaj la pa t' rete lontan anwo tant lan san deplase. Men, se te toujou konsa: se sou kòmandman Seyè a yo te leve pati, se sou kòmandman li tou yo te rete moute tant yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 9, verseNumber = 21, text = "Gen de lè nwaj la rete sèlman pou yon nwit anwo tant lan, depi aswè jouk nan denmen maten. Leve nwaj la leve nan maten, yo menm tou yo leve, yo pati. Gen de fwa tou, li te rete yon jou yon nwit. Leve nwaj la leve, yo menm tou yo leve, yo pati.", bookId = 4),
        Verse(book = "Nonm", chapter = 9, verseNumber = 22, text = "Toutotan nwaj la te rete la anwo tant lan san deplase, li te mèt de jou, yon mwa, yon lanne, yo menm tou, yo pa t' deplase. Men, leve nwaj la leve, yo leve, yo pati.", bookId = 4),
        Verse(book = "Nonm", chapter = 9, verseNumber = 23, text = "Konsa, yo moute tant yo sou lòd Seyè a, yo leve yo pati sou lòd Seyè a: Yo te fè tou sa Seyè a te di Moyiz di yo fè.", bookId = 4),
        Verse(book = "Nonm", chapter = 10, verseNumber = 1, text = "Seyè a pale ak Moyiz, li di l' konsa:", bookId = 4),
        Verse(book = "Nonm", chapter = 10, verseNumber = 2, text = "-Fè yo fè de twonpèt an ajan pou ou. Y'a pran yon gwo moso ajan, y'a bat l' ak mato pou fè chak twonpèt yo. W'a sèvi ak yo pou avèti moun yo lè pou yo reyini ak lè lè a rive pou yo leve pati.", bookId = 4),
        Verse(book = "Nonm", chapter = 10, verseNumber = 3, text = "Depi yo kònen twonpèt yo ansanm, se pou tout moun kouri reyini bò kote ou devan pòt Tant Randevou a.", bookId = 4),
        Verse(book = "Nonm", chapter = 10, verseNumber = 4, text = "Si se yon sèl twonpèt yo kònen, se tout chèf branch fanmi yo ase ki va reyini bò kote ou.", bookId = 4),
        Verse(book = "Nonm", chapter = 10, verseNumber = 5, text = "Lè y'a tande twonpèt yo kònen yon premye fwa ansanm ak bri moun k'ap rele, se va siyal pou branch fanmi ki rete bò solèy leve a leve pati.", bookId = 4),
        Verse(book = "Nonm", chapter = 10, verseNumber = 6, text = "Lè y'a tande twonpèt yo kònen yon dezyèm fwa ansanm ak bri moun k'ap rele yo, se va siyal pou branch fanmi ki rete bò sid la leve pati.", bookId = 4),
        Verse(book = "Nonm", chapter = 10, verseNumber = 7, text = "Men lè y'ap reyini tout moun yo, y'a kònen twonpèt yo sèlman, san pesonn pa bezwen rele.", bookId = 4),
        Verse(book = "Nonm", chapter = 10, verseNumber = 8, text = "Se prèt yo, pitit gason Arawon yo, ki pou kònen twonpèt yo. Men regleman pou nou swiv tout tan tout tan, de pitit an pitit.", bookId = 4),
        Verse(book = "Nonm", chapter = 10, verseNumber = 9, text = "Lè nan peyi a, nou pral fè lagè kont lènmi ki vin atake nou, n'a kònen twonpèt yo epi n'a pouse rèl pou bay siyal batay la. Mwen menm Seyè a, Bondye nou an, m'a vin ede nou, m'a sove nou anba men lènmi nou yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 10, verseNumber = 10, text = "Konsa tou, lè kè nou kontan, lè n'ap fete fèt yo, lè premye jou chak mwa rive avèk lalin nouvèl lan, n'a kònen twonpèt yo tou pandan n'ap fè ofrann pou boule nèt pou Seyè a ak ofrann pou di Bondye mèsi. Lè sa a m'a vin ede nou. Se mwen menm ki Seyè a, Bondye nou an.", bookId = 4),
        Verse(book = "Nonm", chapter = 10, verseNumber = 11, text = "Ventyèm jou, dezyèm mwa nan dezyèm lanne depi pèp la te soti kite peyi Lejip, nwaj la rete, li leve anwo Tant Randevou a.", bookId = 4),
        Verse(book = "Nonm", chapter = 10, verseNumber = 12, text = "Epi moun pèp Izrayèl yo leve, yo pati, chak fanmi nan pozisyon yo te ba yo a. Yo kite dezè Sinayi a. Apre yon tan, nwaj la rete nan dezè Paran an.", bookId = 4),
        Verse(book = "Nonm", chapter = 10, verseNumber = 13, text = "Se konsa yo konmanse vwayaje ankò sou kòmandman Seyè a, jan li te di Moyiz di yo sa pou l' a.", bookId = 4),
        Verse(book = "Nonm", chapter = 10, verseNumber = 14, text = "Premye moun ki pati se moun k'ap mache dèyè làbanyè fanmi Jida a, chak divizyon apa. Alatèt divizyon branch fanmi Jida yo, se te Nakchon, pitit gason Aminadab la.", bookId = 4),
        Verse(book = "Nonm", chapter = 10, verseNumber = 15, text = "Se Netanèl, pitit gason Swa a, ki te alatèt divizyon branch fanmi Isaka a.", bookId = 4),
        Verse(book = "Nonm", chapter = 10, verseNumber = 16, text = "Epi se Eliyab, pitit gason Elon an, ki te alatèt divizyon branch fanmi Zabilon an.", bookId = 4),
        Verse(book = "Nonm", chapter = 10, verseNumber = 17, text = "Apre sa, yo demoute tant lan, epi moun Gèchon yo ak moun Merari yo ki la pou pote tant lan pati.", bookId = 4),
        Verse(book = "Nonm", chapter = 10, verseNumber = 18, text = "Apre yo, moun k'ap mache dèyè làbanyè fanmi Woubenn lan vini, chak divizyon apa. Alatèt divizyon branch fanmi Woubenn lan, se te Elizou, pitit gason Chedeyou a.", bookId = 4),
        Verse(book = "Nonm", chapter = 10, verseNumber = 19, text = "Se Cheloumyèl, pitit gason Sourichadayi a, ki te alatèt divizyon branch fanmi Simeyon an.", bookId = 4),
        Verse(book = "Nonm", chapter = 10, verseNumber = 20, text = "Epi se Elyasaf, pitit gason Dewèl la, ki te alatèt branch fanmi Gad la.", bookId = 4),
        Verse(book = "Nonm", chapter = 10, verseNumber = 21, text = "Apre yo, se te moun Keyat yo ki reskonsab pou pote tout bagay ki apa nèt pou Bondye yo. Tan pou yo rive kote yo pral rete a, tant lan va gen tan moute ankò ap tann yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 10, verseNumber = 22, text = "Apre yo, moun k'ap mache dèyè làbanyè fanmi Efrayim lan vini, chak divizyon apa. Alatèt divizyon branch fanmi Efrayim lan, se Elichama, pitit gason Amiyou a, ki t'ap mache.", bookId = 4),
        Verse(book = "Nonm", chapter = 10, verseNumber = 23, text = "Se Gamaliyèl, pitit gason Pedachou a, ki te alatèt divizyon branch fanmi Manase a.", bookId = 4),
        Verse(book = "Nonm", chapter = 10, verseNumber = 24, text = "Epi se Abidan, pitit gason Gideyoni an, ki te alatèt divizyon branch fanmi Benjamen an.", bookId = 4),
        Verse(book = "Nonm", chapter = 10, verseNumber = 25, text = "Apre yo, moun k'ap mache dèyè làbanyè fanmi Dann lan vini, chak divizyon apa. Se yo k'ap pwoteje tout pèp la pa dèyè nèt. Alatèt divizyon branch fanmi Dann lan se Ayezè, pitit gason Amichadayi a, ki t'ap mache.", bookId = 4),
        Verse(book = "Nonm", chapter = 10, verseNumber = 26, text = "Se Pagiyèl, pitit gason Okran an, ki te alatèt divizyon branch fanmi Asè a.", bookId = 4),
        Verse(book = "Nonm", chapter = 10, verseNumber = 27, text = "Epi se Ayira, pitit gason Enan an, ki te alatèt divizyon branch fanmi Neftali a.", bookId = 4),
        Verse(book = "Nonm", chapter = 10, verseNumber = 28, text = "Men nan ki lòd moun pèp Izrayèl yo t'ap mache, chak divizyon nan pozisyon yo, lè yo leve pou yo pati.", bookId = 4),
        Verse(book = "Nonm", chapter = 10, verseNumber = 29, text = "Moyiz rele bòfrè l' a, Obab, pitit gason Ragèl, moun peyi Madyan an, li di l' konsa: -Nou pral pati la a pou n' ale nan peyi Seyè a te di l'ap ban nou an. Seyè a te pwomèt li t'ap fè anpil byen pou nou. Vini avèk nou non! N'a pataje tout byen nou yo avè ou.", bookId = 4),
        Verse(book = "Nonm", chapter = 10, verseNumber = 30, text = "Obab reponn li: -Non. M'ap tounen nan peyi m' al jwenn fanmi m'.", bookId = 4),
        Verse(book = "Nonm", chapter = 10, verseNumber = 31, text = "Moyiz di l' konsa: -Tanpri, pa kite nou pou kont nou. Se ou ki konnen dènye kote nou ka moute tant nou yo nan dezè a. W'a sèvi nou gid.", bookId = 4),
        Verse(book = "Nonm", chapter = 10, verseNumber = 32, text = "Si ou vini ak nou, w'a gen pa ou nan tout byen Seyè a ap ban nou.", bookId = 4),
        Verse(book = "Nonm", chapter = 10, verseNumber = 33, text = "Se konsa, pèp la leve li pati, li kite mòn Sinayi a, mòn Seyè a, yo mache twa jou. Epi Bwat Kontra Seyè a pran devan yo tout pou chache yon kote pou yo moute tant yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 10, verseNumber = 34, text = "Chak fwa y'ap kite yon kote pou yo ale yon lòt kote, nwaj Seyè a te rete anlè tèt yo nan syèl la tout lajounen.", bookId = 4),
        Verse(book = "Nonm", chapter = 10, verseNumber = 35, text = "Chak fwa Bwat Kontra a pati, Moyiz di: -Leve non, Seyè! Gaye lènmi ou yo! Fè tout moun ki rayi ou yo kouri lè ou parèt!", bookId = 4),
        Verse(book = "Nonm", chapter = 10, verseNumber = 36, text = "Lè Bwat Kontra a kanpe, Moyiz di: -Tounen non, Seyè! Vin rete nan mitan tout lame moun pèp Izrayèl yo!", bookId = 4),
        Verse(book = "Nonm", chapter = 11, verseNumber = 1, text = "Pèp la te konmanse ap plenyen nan zòrèy Seyè a jan zafè yo pa t' bon. Lè Seyè a tande sa, li fè yon sèl kòlè, li voye dife sou pèp la. Dife a pran nan mitan yo, li boule yon bò nan kan an nèt.", bookId = 4),
        Verse(book = "Nonm", chapter = 11, verseNumber = 2, text = "Pèp la rele Moyiz vin delivre yo. Moyiz lapriyè Seyè a pou yo epi dife a sispann.", bookId = 4),
        Verse(book = "Nonm", chapter = 11, verseNumber = 3, text = "Se konsa yo rele kote yo te ye a Tabera, paske se la dife Seyè a te pran nan mitan yo a.", bookId = 4),
        Verse(book = "Nonm", chapter = 11, verseNumber = 4, text = "Bann moun lòt nasyon ki te la nan mitan pèp Izrayèl la te anvi manje vyann. Pèp la menm te pran plenyen ankò, yo t'ap di: -Ki moun k'ap fè nou jwenn vyann pou nou manje koulye a?", bookId = 4),
        Verse(book = "Nonm", chapter = 11, verseNumber = 5, text = "Jan nou te konn manje pwason pou gremesi nan peyi Lejip! Nou chonje kalite bon ti konkonm, melon dlo, powo, zonyon, ak lay nou te konn manje!", bookId = 4),
        Verse(book = "Nonm", chapter = 11, verseNumber = 6, text = "Men koulye a, se deperi n'ap deperi. Nou pa gen anyen pou nou manje, anyen menm pase laman lan ki devan je nou tout tan!", bookId = 4),
        Verse(book = "Nonm", chapter = 11, verseNumber = 7, text = "Laman lan te gen fòm grenn pitimi, li te blan epi ou ta di se gonm arabik.", bookId = 4),
        Verse(book = "Nonm", chapter = 11, verseNumber = 8, text = "Pèp la ale toupatou, li ranmase yo. Apre sa, oubyen li te pase yo nan moulen wòch, oubyen li te pile yo nan pilon pou fè farin. Lèfini, yo kwit li nan chodyè, yo fè gato plat avè l'. Li te gen menm gou avèk pen ki fèt ak lwil oliv.", bookId = 4),
        Verse(book = "Nonm", chapter = 11, verseNumber = 9, text = "Se lannwit laman lan te konn tonbe nan kan an, menm lè ak lawouze.", bookId = 4),
        Verse(book = "Nonm", chapter = 11, verseNumber = 10, text = "Moyiz te tande jan pèp la t'ap plenyen, chak moun ak fanmi yo devan papòt tant yo. Seyè a te fache anpil sou moun yo. Sa te fè Moyiz lapenn.", bookId = 4),
        Verse(book = "Nonm", chapter = 11, verseNumber = 11, text = "Lè sa a, Moyiz di Seyè a konsa: -Poukisa ou aji mal avè m' konsa? Kisa m' fè ki pa fè ou plezi? Poukisa ou mete tout pèp sa a sou kont mwen?", bookId = 4),
        Verse(book = "Nonm", chapter = 11, verseNumber = 12, text = "Eske se mwen ki papa yo? Eske se mwen ki manman yo? Poukisa w'ap mande m' pou mwen pote yo sou lestonmak mwen tankou nouris k'ap bay timoun tete, jouk yo rive nan peyi ou te pwomèt zansèt yo ou t'ap ba yo a?", bookId = 4),
        Verse(book = "Nonm", chapter = 11, verseNumber = 13, text = "Kote pou m' jwenn vyann pou m' bay tout moun sa yo? Y'ap plede plenyen nan zòrèy mwen, y'ap mande m' pou m' ba yo vyann pou yo manje.", bookId = 4),
        Verse(book = "Nonm", chapter = 11, verseNumber = 14, text = "Mwen pa kapab reskonsab tout pèp sa a pou kont mwen. Chay la twò lou pou mwen.", bookId = 4),
        Verse(book = "Nonm", chapter = 11, verseNumber = 15, text = "Si se konsa w'ap aji avè m', tanpri, fè m' favè sa a: pito ou tou touye m' fin ak sa, pou m' pa wè m'ap pase tout malè sa a.", bookId = 4),
        Verse(book = "Nonm", chapter = 11, verseNumber = 16, text = "Seyè a di Moyiz konsa: -Sanble swasanndis nan chèf fanmi pèp Izrayèl la, moun ou konnen ki gen otorite sou pèp la, ki konn bout yo. Mennen yo nan Tant Randevou a. Fè yo rete kanpe la avèk ou.", bookId = 4),
        Verse(book = "Nonm", chapter = 11, verseNumber = 17, text = "M'ap desann epi m'a pale avè ou. M'a pran ti gout nan lespri mwen te ba ou a, m'a ba yo. Konsa, y'a ede ou pote reskonsablite pèp la, ou p'ap pote chay la pou kont ou ankò.", bookId = 4),
        Verse(book = "Nonm", chapter = 11, verseNumber = 18, text = "W'a di pèp la menm: Pran nwit la pou nou pare kò nou pou nou ka fè sèvis pou mwen denmen maten. Epi n'a jwenn vyann pou nou manje. Seyè a te tande jan nou t'ap plenyen nan zòrèy li, jan nou t'ap di nou ta renmen jwenn vyann pou nou manje. Nou te pi bon lè nou te nan peyi Lejip. Koulye a, Seyè a pral ban nou vyann. Se pou nou manje l' ban mwen.", bookId = 4),
        Verse(book = "Nonm", chapter = 11, verseNumber = 19, text = "Se pa sèlman yon jou, ni de jou, ni senk jou, ni dis jou, ni vin jou n'a jwenn vyann sa a pou nou manje.", bookId = 4),
        Verse(book = "Nonm", chapter = 11, verseNumber = 20, text = "Se va pandan tout yon mwa. N'a gen pou nou manje l' jouk l'a soti nan twou nen nou, jouk n'a rebite l', paske nou te vire do bay Bondye ki te la nan mitan nou an, nou t'ap plenyen nan zòrèy li, nou t'ap di nou pa t' dwe janm soti kite peyi Lejip.", bookId = 4),
        Verse(book = "Nonm", chapter = 11, verseNumber = 21, text = "Moyiz di Seyè a: -Se sisanmil (600.000) moun wi ki sou kont mwen. Epi ou di w'ap ba yo vyann kont pou yo manje yon mwa.", bookId = 4),
        Verse(book = "Nonm", chapter = 11, verseNumber = 22, text = "Kote pou yo jwenn kantite mouton ak bèf pou touye ki pou ta kont pou yo? Si yo ta ka ranmase tout pwason ki nan lanmè, ou kwè li ta ase pou yo?", bookId = 4),
        Verse(book = "Nonm", chapter = 11, verseNumber = 23, text = "Seyè a di Moyiz: -Pa gen bagay mwen vle fè mwen pa ka fè! Talè konsa w'a wè si sa m' di a p'ap rive vre.", bookId = 4),
        Verse(book = "Nonm", chapter = 11, verseNumber = 24, text = "Se konsa Moyiz soti, li di pèp la tou sa Seyè a te di l'. Li pran swasanndis nan chèf fanmi pèp Izrayèl la, li mete yo kanpe fè wonn kay Bondye a.", bookId = 4),
        Verse(book = "Nonm", chapter = 11, verseNumber = 25, text = "Seyè a desann nan yon nwaj, li pale ak Moyiz ankò. Apre sa, li pran ti gout nan lespri li te bay Moyiz la, li bay swasanndis chèf yo. Lè lespri a vin sou yo, yo tonbe pale tankou pwofèt yo sou tout kalite bagay. Apre sa, yo sispann.", bookId = 4),
        Verse(book = "Nonm", chapter = 11, verseNumber = 26, text = "Te gen de nan chèf fanmi yo te chwazi yo ki te rete nan kan an. Yo pa t' ale nan kay Bondye a. Yonn te rele Eldad, lòt la Medad. Lespri a te desann sou yo tou, yo t'ap pale pawòl Bondye a byen fò nan kan an.", bookId = 4),
        Verse(book = "Nonm", chapter = 11, verseNumber = 27, text = "Yon jenn gason kouri al di Moyiz men Eldad ak Medad ap pale pawòl Bondye a byen fò nan kan an.", bookId = 4),
        Verse(book = "Nonm", chapter = 11, verseNumber = 28, text = "Lè sa a Jozye, pitit gason Noun lan, ki te adjwen Moyiz nan tou sa l' t'ap fè depi li te jenn tibway, pran lapawòl, li pale ak Moyiz, li di l' konsa: -Msye Moyiz, fè yo sispann non!", bookId = 4),
        Verse(book = "Nonm", chapter = 11, verseNumber = 29, text = "Moyiz reponn li: -Kouman? Ou gen lè w'ap fè jalouzi pou mwen? Pa pito Seyè a te mete lespri l' sou tout pèp la pou yo te ka pale tankou pwofèt!", bookId = 4),
        Verse(book = "Nonm", chapter = 11, verseNumber = 30, text = "Apre sa, Moyiz tounen nan kan an ansanm ak swasanndis chèf fanmi yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 11, verseNumber = 31, text = "Apre sa, Seyè a fè yon sèl van soufle sot nan lanmè, li bwote yon bann zòtolan ki vin tonbe toupatou nan kan kote moun yo te rete a ak toutotou kan an. Yon moun ta gen dwa mache tout yon jounen nan nenpòt direksyon anvan pou l' ta kite kote zòtolan yo te tonbe a. Zòtolan yo te fè pil rive twa pye wotè sou tè a.", bookId = 4),
        Verse(book = "Nonm", chapter = 11, verseNumber = 32, text = "Pèp la pase tout jounen an, tout nwit la, ak tout jounen denmen an ap ranmase zòtolan. Sa ki te ranmase pi piti a te ranmase dis barik pou tèt pa l'. Yo blayi yo atè toupatou nan kan an pou mete yo cheche.", bookId = 4),
        Verse(book = "Nonm", chapter = 11, verseNumber = 33, text = "Yo te fèk konmanse manje vyann, lè Seyè a fè kòlè sou pèp la, li lage yon sèl epidemi sou yo pou pini yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 11, verseNumber = 34, text = "Yo rele kote sa a: Simityè Grangou, paske se la yo te antere tout moun nan pèp la ki t'ap plenyen pou vyann.", bookId = 4),
        Verse(book = "Nonm", chapter = 11, verseNumber = 35, text = "Apre sa, pèp la kite Simityè Grangou kote yo te ye a, yo pati pou Azewòt kote yo moute kay yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 12, verseNumber = 1, text = "Moyiz te marye ak yon fanm peyi Etiopi. Miryam ak Arawon t'ap pale Moyiz mal sou sa.", bookId = 4),
        Verse(book = "Nonm", chapter = 12, verseNumber = 2, text = "Yo t'ap di konsa: -Eske se sèlman Moyiz Seyè a te pran pou pale ak pèp la? Eske li pa konn pale ak nou pou pèp la tou? Seyè a tande sa yo t'ap di a.", bookId = 4),
        Verse(book = "Nonm", chapter = 12, verseNumber = 3, text = "Men Moyiz se yon nonm ki pa t' grandizè. pa t' gen pase l' sou latè.", bookId = 4),
        Verse(book = "Nonm", chapter = 12, verseNumber = 4, text = "Seyè a rete konsa li pale ak Moyiz, Arawon ak Miryam, li di yo: -Nou twa sa yo, soti non. Ale nan Tant Randevou a. Yo twa a ale vre.", bookId = 4),
        Verse(book = "Nonm", chapter = 12, verseNumber = 5, text = "Seyè a desann nan yon gwo nwaj ki te gen fòm yon poto. Li kanpe nan papòt tant lan, li rele Arawon ak Miryam ki pwoche vin jwenn li.", bookId = 4),
        Verse(book = "Nonm", chapter = 12, verseNumber = 6, text = "Li di yo konsa: -Tande byen sa m'ap di nou la a. Lè gen yon pwofèt nan mitan nou, se nan vizyon mwen fè l' wè mwen, se nan rèv mwen pale avè l'.", bookId = 4),
        Verse(book = "Nonm", chapter = 12, verseNumber = 7, text = "Men, se pa menm bagay la ak Moyiz, sèvitè m' lan. Li se sèl moun mwen fè konfyans nan mitan tout pèp la.", bookId = 4),
        Verse(book = "Nonm", chapter = 12, verseNumber = 8, text = "Mwen pale avè l' aklè, mwen pa ba li parabòl. Mwen fè l' wè mwen. Ki jan nou fè penmèt nou pale Moyiz, sèvitè m' lan, mal?", bookId = 4),
        Verse(book = "Nonm", chapter = 12, verseNumber = 9, text = "Seyè a te fè yon sèl fache sou yo, epi l' ale.", bookId = 4),
        Verse(book = "Nonm", chapter = 12, verseNumber = 10, text = "Nwaj la leve anwo tant lan, l' ale. Menm lè a, yon sèl maladi tonbe sou Miryam: tout po kò l' vin blanch kou koton. Arawon gade Miryam, li wè Miryam te kouvri ak bouton sou tout po li.", bookId = 4),
        Verse(book = "Nonm", chapter = 12, verseNumber = 11, text = "Arawon di Moyiz konsa: -Tanpri, mèt mwen. Pa kite nou peye pou sa nou fè a. Tèt nou pa t' la!", bookId = 4),
        Verse(book = "Nonm", chapter = 12, verseNumber = 12, text = "Tanpri, pa kite Miryam tounen tankou yon tibebe ki fèt tou mouri ak tout mwatye nan kò l' manje.", bookId = 4),
        Verse(book = "Nonm", chapter = 12, verseNumber = 13, text = "Se konsa, Moyiz rele nan pye Bondye, li di l' konsa: -Bondye, tanpri, geri l' non!", bookId = 4),
        Verse(book = "Nonm", chapter = 12, verseNumber = 14, text = "Men, Seyè a di Moyiz: -Si se te papa l' ki te krache nan figi l', li t'ap blije pote wont la pandan sèt jou, pa vre? Enben, se pou yo fèmen l' pou kont li pandan sèt jou yon kote andeyò limit kan an. Apre sa, y'a kite l' tounen.", bookId = 4),
        Verse(book = "Nonm", chapter = 12, verseNumber = 15, text = "Yo fèmen Miryam pou kont li pandan sèt jou yon kote andeyò limit kan an. Pèp la pa t' leve pati toutotan yo pa t' kite Miryam tounen nan kan an ankò.", bookId = 4),
        Verse(book = "Nonm", chapter = 12, verseNumber = 16, text = "Apre sa, pèp la kite Azewòt kote yo te ye a, yo pati al moute tant yo nan dezè Paran an.", bookId = 4)
    )

    private val part2 = listOf(
        Verse(book = "Nonm", chapter = 13, verseNumber = 1, text = "Seyè a pale ak Moyiz, li di l' konsa:", bookId = 4),
        Verse(book = "Nonm", chapter = 13, verseNumber = 2, text = "-Ou pral chwazi douz nan chèf fanmi pèp Izrayèl yo, yonn pou chak branch fanmi. Ou pral voye yo pou y' al wè ki jan peyi Kanaran an ye, peyi m'ap bay moun Izrayèl yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 13, verseNumber = 3, text = "Dapre lòd Moyiz te resevwa nan men Seyè a, li pran douz gason ki te chèf fanmi nan pèp Izrayèl la. Antan li te nan dezè Paran an, li voye yo al rekonèt peyi a.", bookId = 4),
        Verse(book = "Nonm", chapter = 13, verseNumber = 4, text = "Men non yo: Pou branch Woubenn lan, se te Chamwa, pitit gason Zakou a.", bookId = 4),
        Verse(book = "Nonm", chapter = 13, verseNumber = 5, text = "Pou branch fanmi Simeyon an, se te Chafa, pitit gason Ori a.", bookId = 4),
        Verse(book = "Nonm", chapter = 13, verseNumber = 6, text = "Pou branch fanmi Jida a, se te Kalèb, pitit gason Jefoune a.", bookId = 4),
        Verse(book = "Nonm", chapter = 13, verseNumber = 7, text = "Pou branch fanmi Isaka a, se te Jigal, pitit gason Jozèf la.", bookId = 4),
        Verse(book = "Nonm", chapter = 13, verseNumber = 8, text = "Pou branch fanmi Efrayim lan, se te Oze, pitit gason Noun lan.", bookId = 4),
        Verse(book = "Nonm", chapter = 13, verseNumber = 9, text = "Pou branch fanmi Benjamen an, se te Palti, pitit gason Rafou a.", bookId = 4),
        Verse(book = "Nonm", chapter = 13, verseNumber = 10, text = "Pou branch fanmi Zabilon an, se te Gadiyèl, pitit gason Sodi a.", bookId = 4),
        Verse(book = "Nonm", chapter = 13, verseNumber = 11, text = "Pou branch fanmi Jozèf la, nan branch Manase a, se te Gadi, pitit gason Souzi a.", bookId = 4),
        Verse(book = "Nonm", chapter = 13, verseNumber = 12, text = "Pou branch fanmi Dann lan, se te Amiyèl, pitit gason Jemali a.", bookId = 4),
        Verse(book = "Nonm", chapter = 13, verseNumber = 13, text = "Pou branch fanmi Asè a, se te Setou, pitit gason Mikayèl la.", bookId = 4),
        Verse(book = "Nonm", chapter = 13, verseNumber = 14, text = "Pou branch fanmi Neftali a, se te Nakbi, pitit gason Wopsi a.", bookId = 4),
        Verse(book = "Nonm", chapter = 13, verseNumber = 15, text = "Pou branch fanmi Gad la, se te Geouyèl, pitit gason Maki a.", bookId = 4),
        Verse(book = "Nonm", chapter = 13, verseNumber = 16, text = "Se te non douz mesye Moyiz te voye al rekonèt peyi Kanaran an. Moyiz te chanje non Oze, pitit gason Noun lan, li rele l' Jozye.", bookId = 4),
        Verse(book = "Nonm", chapter = 13, verseNumber = 17, text = "Lè Moyiz voye yo ale nan peyi Kanaran an, li di yo: -Moute nan peyi a. N'a pase pa Negèv la, n'a pran chemen mòn pou nou.", bookId = 4),
        Verse(book = "Nonm", chapter = 13, verseNumber = 18, text = "Ale gade peyi a. Chache konnen ki jan li ye, ki kalite moun ki rete ladan l', konbe yo ye, ak ki fòs yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 13, verseNumber = 19, text = "Chache konnen si tè a se yon bon tè osinon yon move tè, si moun yo rete nan lavil ki gen ranpa pou pwoteje yo osinon nan kan anba tant twal.", bookId = 4),
        Verse(book = "Nonm", chapter = 13, verseNumber = 20, text = "Chache konnen si peyi a rich osinon pòv, si gen anpil pyebwa sou tè a ou si pa genyen. Nou pa bezwen pè anyen. Lè n'ap tounen, pote kèk nan fwi ki donnen laba a. Se te sezon rezen te konmanse ap mi.", bookId = 4),
        Verse(book = "Nonm", chapter = 13, verseNumber = 21, text = "Se konsa mesye yo moute, y' al chache konnen tout bagay ki gen nan peyi a, depi dezè Zin ki nan sid peyi a rive jouk Reyòb toupre pas Amat la, nan nò.", bookId = 4),
        Verse(book = "Nonm", chapter = 13, verseNumber = 22, text = "Yo travèse zòn Negèv la, yo rive lavil Ebwon kote moun Ayiman yo, moun Chechayi yo ak moun Talmayi yo rete. Yo tout te fè pati ras moun Anak yo. Ebwon sa a, se yon lavil ki te bati sètan anvan yo te bati lavil Zoan nan peyi Lejip.", bookId = 4),
        Verse(book = "Nonm", chapter = 13, verseNumber = 23, text = "Yo rive nan ravin Echkòl, yo koupe yon branch rezen ki te gen yon sèl gwo grap rezen nan li. Yo mete l' sou yon gòl pou de moun te ka pote l' sou zepòl yo, si tèlman li te lou. Yo pote grenad ak fig frans tou.", bookId = 4),
        Verse(book = "Nonm", chapter = 13, verseNumber = 24, text = "Yo rele kote sa a Ravin Echkòl, poutèt gwo grap rezen moun pèp Izrayèl yo te koupe la a.", bookId = 4),
        Verse(book = "Nonm", chapter = 13, verseNumber = 25, text = "Apre karant jou, lè yo fin vizite toupatou nan peyi a, yo tounen,", bookId = 4),
        Verse(book = "Nonm", chapter = 13, verseNumber = 26, text = "yo vin jwenn Moyiz, Arawon ak tout moun pèp Izrayèl yo Kadès, nan dezè Paran an. Yo detaye ba yo tou sa yo te wè, yo moutre yo fwi yo te pote yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 13, verseNumber = 27, text = "Yo di Moyiz konsa: -Nou vizite toupatou nan peyi ou te voye nou al chache konnen an. Se yon peyi ki rich anpil, kote lèt ak siwo myèl koule tankou dlo. Se vre wi. Gade fwi nou jwenn ladan l'.", bookId = 4),
        Verse(book = "Nonm", chapter = 13, verseNumber = 28, text = "Men, moun ki rete nan peyi a gwonèg anpil. Lavil yo gran, yo byen pwoteje. Sa ki pi rèd nou wè yon kalite ras moun gwonèg bèl wotè.", bookId = 4),
        Verse(book = "Nonm", chapter = 13, verseNumber = 29, text = "Moun Amalèk yo rete nan sid peyi a, nan zòn Negèv la. Moun It yo, moun Jebis yo ak moun Amon yo rete nan mòn yo. Moun Kanaran yo rete bò lanmè Mediterane a ak bò larivyè Jouden an.", bookId = 4),
        Verse(book = "Nonm", chapter = 13, verseNumber = 30, text = "Kalèb fè moun yo sispann bougonnen sou do Moyiz, li di yo konsa: -Ann moute koulye a. Ann al pran peyi a pou nou. Pa gen anyen la a nou pa ka fè!", bookId = 4),
        Verse(book = "Nonm", chapter = 13, verseNumber = 31, text = "Men mesye ki te moute ansanm ak Kalèb yo di konsa: -Non. Nou pa ka al atake moun sa yo. Yo pi fò pase nou.", bookId = 4),
        Verse(book = "Nonm", chapter = 13, verseNumber = 32, text = "Se konsa yo pran pale mal sou peyi yo te al vizite a devan pèp Izrayèl la. Yo t'ap di: -Peyi nou ta l' vizite a, peyi nou ta l' chache konnen an, se yon peyi ki pa menm bay kont manje pou moun k'ap viv sou li yo. Epi, tout moun nou wè la se moun ki wo anpil.", bookId = 4),
        Verse(book = "Nonm", chapter = 13, verseNumber = 33, text = "Sa ki pi rèd, nou wè yon kalite gwonèg bèl wotè, moun ras Anak yo. Devan moun sa yo se krebete nou ye, tèlman nou piti. Se konsa nou te santi nou devan yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 14, verseNumber = 1, text = "Lè sa a, pèp la pran rele byen fò, yo pase tout nwit la ap kriye san rete.", bookId = 4),
        Verse(book = "Nonm", chapter = 14, verseNumber = 2, text = "Yo tout t'ap bougonnen sou Moyiz ak Arawon. Yo vin di yo konsa: -Pito nou te mouri nan peyi Lejip osinon nan dezè a!", bookId = 4),
        Verse(book = "Nonm", chapter = 14, verseNumber = 3, text = "Poukisa Seyè a mennen nou nan peyi sa a? Koulye a, yo pral touye nou nan lagè, yo pral pran madanm ak pitit nou yo fè yo tounen esklav. Pa pito nou tounen nan peyi Lejip?", bookId = 4),
        Verse(book = "Nonm", chapter = 14, verseNumber = 4, text = "Yonn t'ap di lòt: -Ann chwazi yon lòt chèf! Ann tounen nan peyi Lejip!", bookId = 4),
        Verse(book = "Nonm", chapter = 14, verseNumber = 5, text = "Lè Moyiz ak Arawon wè sa, yo tonbe fas atè devan tout pèp la ki te sanble la a.", bookId = 4),
        Verse(book = "Nonm", chapter = 14, verseNumber = 6, text = "Lè sa a, de nan mesye espyon yo, Jozye, pitit gason Noun lan, ak Kalèb, pitit gason Jefoune a, chire rad ki te sou yo sitèlman yo te fache.", bookId = 4),
        Verse(book = "Nonm", chapter = 14, verseNumber = 7, text = "Epi yo di pèp la: -Peyi nou te al vizite a se yon bon bon peyi.", bookId = 4),
        Verse(book = "Nonm", chapter = 14, verseNumber = 8, text = "Si Seyè a vle fè sa pou nou, l'ap fè nou antre nan peyi a, l'ap ban nou li. Se yon peyi ki rich anpil, yon peyi kote lèt ak siwo myèl koule tankou dlo.", bookId = 4),
        Verse(book = "Nonm", chapter = 14, verseNumber = 9, text = "Sèlman, pa kenbe tèt ak Seyè a! Nou pa bezwen pè moun k'ap viv nan peyi sa a. N'ap manje yo tankou kann. Bondye ki t'ap pwoteje yo a kouri mete deyò. Men Seyè a kanpe la avèk nou. Nou pa bezwen pè yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 14, verseNumber = 10, text = "Lè sa a, tout pèp la ranmase wòch pou yo kalonnen Jozye ak Kalèb. Men, lamenm pouvwa Bondye a parèt anwo Tant Randevou a, li fè tout pèp la wè l'.", bookId = 4),
        Verse(book = "Nonm", chapter = 14, verseNumber = 11, text = "Seyè a di Moyiz konsa: -Kilè pèp sa a va sispann meprize mwen? Kilè y'a soti pou yo fè m' konfyans? Gade tout bèl bagay mwen te fè pou yo. Malgre sa, yo pa vle kwè m' toujou!", bookId = 4),
        Verse(book = "Nonm", chapter = 14, verseNumber = 12, text = "M'ap voye yon sèl epidemi sou yo, m'ap touye yo tout. M'ap anpeche yo pran posesyon tè ki pou yo a. Men ou menm, m'ap fè ou tounen yon nasyon k'ap pi gwo, k'ap pi fò pase yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 14, verseNumber = 13, text = "Men, Moyiz di Seyè a konsa: -Se ou menm ak fòs ponyèt ou ki te fè pèp Izrayèl la soti kite peyi Lejip la.", bookId = 4),
        Verse(book = "Nonm", chapter = 14, verseNumber = 14, text = "Lè moun pèyi Lejip yo va vin konnen sa ou pral fè pèp la, y'a rakonte l' bay moun ki rete nan peyi Kanaran yo. Yo menm tou, yo deja konnen se ou menm, Seyè, ki kanpe la nan mitan pèp la, se ou menm ki parèt aklè devan je yo, se nwaj ou, Granmèt, ki rete anwo yo. Se ou menm ki t'ap mache devan yo lajounen nan yon gwo nwaj ki te gen fòm yon poto, lannwit nan yon gwo flanm dife ki te gen fòm yon poto tou.", bookId = 4),
        Verse(book = "Nonm", chapter = 14, verseNumber = 15, text = "Koulye a, si ou rete konsa ou touye tout pèp ou a, moun lòt nasyon yo ki te tande pale ki kalite moun ou ye, yo pral di", bookId = 4),
        Verse(book = "Nonm", chapter = 14, verseNumber = 16, text = "se kapab ou pa t' kapab mennen pèp la nan peyi ou te fè sèman w'ap ba yo a kifè ou touye yo nan dezè a.", bookId = 4),
        Verse(book = "Nonm", chapter = 14, verseNumber = 17, text = "Non. Seyè! Se koulye a pou ou fè wè gwo pouvwa ou la, jan ou te pwomèt l' a, lè ou te di:", bookId = 4),
        Verse(book = "Nonm", chapter = 14, verseNumber = 18, text = "Se mwen menm ki Seyè a, mwen pa an kòlè fasil, mwen p'ap janm sispann renmen nou. M'ap toujou padonnen sa nou fè ki mal ak sa nou te dwe fè nou pa fè. Men, mwen pa nan kase fèy kouvri sa ak pesonn. Si yon moun fè yon bagay mal, m'ap pini pitit li, pitit pitit li, ak pitit pitit pitit li yo pou sa li fè a, jouk sou twazyèm ak katriyèm jenerasyon.", bookId = 4),
        Verse(book = "Nonm", chapter = 14, verseNumber = 19, text = "Tanpri, jan ou gen bon kè sa a, padonnen sa pèp la fè ki mal la, menm jan ou te pran pasyans ak yo depi yo kite peyi Lejip jouk yo rive isit la.", bookId = 4),
        Verse(book = "Nonm", chapter = 14, verseNumber = 20, text = "Seyè a di: -M'ap padonnen yo, jan ou mande m' lan.", bookId = 4),
        Verse(book = "Nonm", chapter = 14, verseNumber = 21, text = "Men, menm jan ou wè mwen vivan an, menm jan ou wè pouvwa mwen toupatou sou latè,", bookId = 4),
        Verse(book = "Nonm", chapter = 14, verseNumber = 22, text = "okenn nan moun sa yo p'ap rive viv lontan ase pou yo antre nan peyi a. Yo te wè pouvwa mwen, yo te wè tout bèl bagay mwen te fè nan peyi Lejip ak nan dezè a. Men anpil fwa deja, yo chache wè jouk ki bò mwen ye ak yo, yo pa janm vle koute m' lè m' pale ak yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 14, verseNumber = 23, text = "Yo p'ap menm wè peyi mwen te sèmante mwen t'ap bay zansèt yo a. Yo tout ki vire do ban mwen yo, yo yonn p'ap wè peyi a.", bookId = 4),
        Verse(book = "Nonm", chapter = 14, verseNumber = 24, text = "Men, paske Kalèb, sèvitè m' lan, pa aji tankou yo, li swiv mwen san gad dèyè, m'ap fè l' antre nan peyi li te al rekonèt la. Pitit pitit li yo va pran peyi a pou yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 14, verseNumber = 25, text = "Y'a rete nan plenn kote moun Amalèk yo ak moun Kanaran yo rete koulye a. Denmen n'ap fè bak, n'a tounen nan dezè a ankò nan direksyon Lanmè Wouj la.", bookId = 4),
        Verse(book = "Nonm", chapter = 14, verseNumber = 26, text = "Apre sa, Seyè a pale ak Moyiz ansanm ak Arawon, li di yo konsa:", bookId = 4),
        Verse(book = "Nonm", chapter = 14, verseNumber = 27, text = "-Kilè bann moun mechan sa yo va sispann bougonnen sou do mwen konsa? Mwen bouke tande jan moun pèp Izrayèl yo ap pale m' mal.", bookId = 4),
        Verse(book = "Nonm", chapter = 14, verseNumber = 28, text = "Men sa pou ou di yo pou mwen: Se mwen menm menm, Seyè a, ki di sa. Menm jan nou wè m' vivan an, mwen fè sèman sa nou te di k'ap rive nou an, se li k'ap rive nou vre.", bookId = 4),
        Verse(book = "Nonm", chapter = 14, verseNumber = 29, text = "Y'ap antere kadav nou tout nan dezè a. Nou tout ki t'ap bougonnen sou mwen yo, nou tout yo te konte lè resansman an, nou tout ki gen ventan ak sa ki pi gran yo, nou yonn p'ap antre nan peyi a.", bookId = 4),
        Verse(book = "Nonm", chapter = 14, verseNumber = 30, text = "Dakò! Mwen te fè sèman mwen t'ap fè nou al rete nan peyi a. Men, nou yonn p'ap gen chans lan, esepte Kalèb, pitit gason Jefoune a, ak Jozye, pitit gason Noun lan.", bookId = 4),
        Verse(book = "Nonm", chapter = 14, verseNumber = 31, text = "Nou te di pitit pitit nou yo pral tonbe anba men lènmi nou yo. Men, se yo menm m'ap fè antre nan peyi nou menm nou refize al pran an.", bookId = 4),
        Verse(book = "Nonm", chapter = 14, verseNumber = 32, text = "Men, nou menm y'ap antere kadav nou yo isit nan dezè a.", bookId = 4),
        Verse(book = "Nonm", chapter = 14, verseNumber = 33, text = "Pitit nou yo pral moute desann nan tout dezè a. Pandan karant lanne, y'a peye pou vire nou te vire do ban mwen an, jouk nou tout nèt n'a fin mouri nan dezè a.", bookId = 4),
        Verse(book = "Nonm", chapter = 14, verseNumber = 34, text = "Nou menm, n'a peye konsekans peche nou an pandan karant lanne, yon lanne pou chak jou nan karant jou nou te pase ap vizite peyi a. Lè sa a, n'a konnen sa sa vle di lè m' vire do bay moun.", bookId = 4),
        Verse(book = "Nonm", chapter = 14, verseNumber = 35, text = "Se mwen menm Seyè a ki di sa: Mwen fè sèman se konsa mwen pral aji ak bann moun sa yo ki mete tèt yo ansanm sou do m'. Yo tout gen pou yo disparèt nan dezè sa a. Wi, se la menm yo tout ap mouri.", bookId = 4),
        Verse(book = "Nonm", chapter = 14, verseNumber = 36, text = "Mesye Moyiz te voye al rekonèt peyi a te fè tout pèp la ap bougonnen sou Moyiz avèk move rapò yo te fè sou peyi a, lè yo te tounen an.", bookId = 4),
        Verse(book = "Nonm", chapter = 14, verseNumber = 37, text = "Se konsa yon sèl maladi tonbe sou mesye sa yo ki te pale peyi a mal konsa. Yo tonbe, yo mouri frèt devan Seyè a.", bookId = 4),
        Verse(book = "Nonm", chapter = 14, verseNumber = 38, text = "Nan douz mesye ki te al vizite peyi a, se de sèlman ki pa t' mouri: se te Jozye, pitit gason Noun lan, ak Kalèb, pitit gason Jefoune a.", bookId = 4),
        Verse(book = "Nonm", chapter = 14, verseNumber = 39, text = "Lè Moyiz di moun pèp Izrayèl yo tout pawòl sa yo, sa te fè yo lapenn anpil.", bookId = 4),
        Verse(book = "Nonm", chapter = 14, verseNumber = 40, text = "Nan denmen maten, byen bònè, yo leve pou y' al janbe lòt bò mòn yo pou yo antre nan peyi a. Yo t'ap di: -Men nou! Nou pare pou n' ale kote Seyè a di pou n' ale a. Nou rekonèt sa nou te fè a mal.", bookId = 4),
        Verse(book = "Nonm", chapter = 14, verseNumber = 41, text = "Men Moyiz di yo: -Pouki pou n'ap dezobeyi lòd Seyè a ankò? Sa p'ap mache pou nou non, fwa sa a!", bookId = 4),
        Verse(book = "Nonm", chapter = 14, verseNumber = 42, text = "Piga nou moute. Seyè a vire do ban nou, nou pa bezwen ale fè lènmi nou yo bat nou pou gremesi.", bookId = 4),
        Verse(book = "Nonm", chapter = 14, verseNumber = 43, text = "Lè n'a rive devan moun Amalèk yo ak moun Kanaran yo, nou pral mouri nan batay la. Seyè a p'ap kanpe la avèk nou, paske nou te vire do ba li.", bookId = 4),
        Verse(book = "Nonm", chapter = 14, verseNumber = 44, text = "Pèp la fè tèt di, yo moute moute yo sou mòn yo pou yo seye antre nan peyi a. Men, ni Bwat Kontra Seyè a, ni Moyiz pa deplase kote yo te ye nan kan an.", bookId = 4),
        Verse(book = "Nonm", chapter = 14, verseNumber = 45, text = "Se konsa moun Amalèk yo ak moun Kanaran yo ki te rete nan mòn yo desann, yo bat yo, yo kouri dèyè yo jouk yon kote yo rele Oma.", bookId = 4),
        Verse(book = "Nonm", chapter = 15, verseNumber = 1, text = "Seyè a pale ak Moyiz ankò, li di l' konsa:", bookId = 4),
        Verse(book = "Nonm", chapter = 15, verseNumber = 2, text = "-Pale ak moun pèp Izrayèl yo, w'a di yo pou mwen: Lè n'a antre nan peyi mwen pral ban nou pou nou rete a,", bookId = 4),
        Verse(book = "Nonm", chapter = 15, verseNumber = 3, text = "lè n'ap ofri yon towo bèf, osinon yon mouton, oswa yon kabrit pou yo boule nèt nan dife pou Seyè a, tankou yon ofrann ki pou fè Seyè a plezi ak bon sant li, kit se paske nou te fè yon ve, kit se paske nou menm nou te fè lide fè yon ofrann, osinon paske lè fèt n'ap fete pou mwen yo rive,", bookId = 4),
        Verse(book = "Nonm", chapter = 15, verseNumber = 4, text = "wi, lè n'ap fè ofrann konsa pou Seyè a, n'a fè ofrann grenn ki donnen nan jaden pou mache ak yo tou: sèt ti mamit farin frans melanje avèk de boutèy ka plen lwil oliv.", bookId = 4),
        Verse(book = "Nonm", chapter = 15, verseNumber = 5, text = "Lè n'ap fè ofrann pou yo boule nèt pou Seyè a, n'a ofri de boutèy ka plen diven pou chak ti mouton n'ap ofri.", bookId = 4),
        Verse(book = "Nonm", chapter = 15, verseNumber = 6, text = "Lè se yon belye mouton n'ap ofri, se va katòz ti mamit farin frans melanje avèk twa boutèy ka plen lwil oliv n'a ofri pou ofrann grenn ki donnen nan jaden,", bookId = 4),
        Verse(book = "Nonm", chapter = 15, verseNumber = 7, text = "ansanm ak twa boutèy ka diven. Ofrann sa yo, lè yo boule nan dife, y'a fè Seyè a plezi ak bon sant yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 15, verseNumber = 8, text = "Lè se yon jenn towo n'ap ofri pou yo boule nèt nan dife osinon pou yo touye pou Seyè a, kit se paske nou te fè yon ve, kit se pou di Bondye mèsi,", bookId = 4),
        Verse(book = "Nonm", chapter = 15, verseNumber = 9, text = "se pou nou pote yon ofrann grenn ki donnen nan jaden tou: venteyen ti mamit farin frans melanje ak senk ti boutèy ka lwil oliv.", bookId = 4),
        Verse(book = "Nonm", chapter = 15, verseNumber = 10, text = "Lèfini, n'a ofri kat boutèy ka diven avèk li. Ofrann sa a, lè li boule nan dife, l'a fè Seyè a plezi ak bon sant li.", bookId = 4),
        Verse(book = "Nonm", chapter = 15, verseNumber = 11, text = "Se sa pou nou bay ansanm ak chak jenn towo, chak belye mouton osinon chak bouk kabrit n'ap ofri.", bookId = 4),
        Verse(book = "Nonm", chapter = 15, verseNumber = 12, text = "Pou chak bèt n'ap ofri an plis, n'a ofri kantite grenn jaden ki pou mache ak l' a.", bookId = 4),
        Verse(book = "Nonm", chapter = 15, verseNumber = 13, text = "Se konsa chak moun natif natal peyi Izrayèl la gen pou fè l' lè y'ap ofri yon bèt pou boule nèt pou Seyè a, yon ofrann ki pou fè Seyè a plezi ak bon sant li.", bookId = 4),
        Verse(book = "Nonm", chapter = 15, verseNumber = 14, text = "Lè yon moun lòt nasyon k'ap viv nan mitan nou pou yon ti tan, osinon pou tout tan, ap fè yon ofrann bay Bondye, yon ofrann pou yo boule nan dife epi ki pou fè Seyè a plezi ak bon sant li, se pou l' swiv menm regleman ak nou.", bookId = 4),
        Verse(book = "Nonm", chapter = 15, verseNumber = 15, text = "Nan peyi a, se va yon sèl regleman pou tout moun, ni pou nou menm ni pou moun lòt nasyon k'ap viv nan mitan nou yo, yon sèl regleman pou tout tan, de pitit an pitit: Se va menm bagay la ni pou nou ni pou moun lòt nasyon yo devan Seyè a.", bookId = 4),
        Verse(book = "Nonm", chapter = 15, verseNumber = 16, text = "Se va yon sèl lwa, yon sèl regleman ni pou nou ni pou moun lòt nasyon k'ap viv nan mitan nou yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 15, verseNumber = 17, text = "Apre sa Seyè a pale ak Moyiz, li di l' konsa:", bookId = 4),
        Verse(book = "Nonm", chapter = 15, verseNumber = 18, text = "-Pale ak moun pèp Izrayèl yo. W'a di yo pou mwen: Lè n'a antre nan peyi kote mwen pral mennen nou an,", bookId = 4),
        Verse(book = "Nonm", chapter = 15, verseNumber = 19, text = "lè n'ap manje manje peyi a va bay, n'a wete yon pòsyon, n'a mete l' apa pou nou fè Seyè a kado.", bookId = 4),
        Verse(book = "Nonm", chapter = 15, verseNumber = 20, text = "Chak lanne, apre rekòt la, n'a pran yon pen nan premye pen fèt ak ble nou fèk rekòlte a, n'a mete l' apa pou nou fè Seyè a kado, jan nou fè l' pou grenn ki pase sou glasi.", bookId = 4),
        Verse(book = "Nonm", chapter = 15, verseNumber = 21, text = "Se pou nou toujou wete yon pen nan premye pen nou fè apre rekòt nou yo pou nou fè Seyè a kado. Se va yon lwa pou pitit ak pitit pitit nou yo, depi koulye a ak pou tout tan.", bookId = 4),
        Verse(book = "Nonm", chapter = 15, verseNumber = 22, text = "Men, si san nou pa fè espre, nou pa swiv yonn nan lòd Seyè a te bay Moyiz yo,", bookId = 4),
        Verse(book = "Nonm", chapter = 15, verseNumber = 23, text = "lòd pou nou te toujou swiv de pitit an pitit depi jou li te voye Moyiz pale ak nou an, men sa pou yo fè:", bookId = 4),
        Verse(book = "Nonm", chapter = 15, verseNumber = 24, text = "Si se tout pèp la ki fè sa l' pa t' dwe fè san li pa t' konnen sa l'ap fè a, yo tout ansanm y'a ofri yon jenn ti towo bèf pou yo boule nèt nan dife pou Seyè a. Se va yon ofrann pou yo boule nan dife pou fè Seyè a plezi ak bon sant li. Y'a ofri l' ansanm ak ofrann grenn jaden ak bwason ki pou mache avè l' la. Apre sa, y'a ofri yon bouk kabrit pou repare sa yo te fè ki mal la.", bookId = 4),
        Verse(book = "Nonm", chapter = 15, verseNumber = 25, text = "Prèt la va pote ofrann lan devan Bondye, l'a touye bèt yo ofri pou peche tout moun pèp Izrayèl yo te fè a, epi Bondye va padonnen sa yo te fè a, paske yo pa t' fè espre, epi yo te pote ofrann pou yo te boule nan dife pou Seyè a ansanm ak ofrann pou repare sa yo te fè ki mal devan Seyè a san yo pa t' fè espre a.", bookId = 4),
        Verse(book = "Nonm", chapter = 15, verseNumber = 26, text = "Se konsa Bondye va padonnen tout moun pèp Izrayèl yo ansanm ak tout moun lòt nasyon k'ap viv nan mitan yo, paske se yo tout ki te koupab nan sa yo te fè san yo pa konnen an.", bookId = 4),
        Verse(book = "Nonm", chapter = 15, verseNumber = 27, text = "Si se yon moun ki fè sa l' pa t' dwe fè san li pa fè espre, l'a gen pou l' ofri yon ti fenmèl kabrit ki poko gen ennan pou repare pou sa l' te fè a.", bookId = 4),
        Verse(book = "Nonm", chapter = 15, verseNumber = 28, text = "Prèt la va pote ofrann lan devan Seyè a, l'a touye bèt yo ofri pou peche moun lan te fè san li pa t' fè espre a, epi Bondye va padonnen l' sa l' te fè a.", bookId = 4),
        Verse(book = "Nonm", chapter = 15, verseNumber = 29, text = "Se va menm regleman an pou tout moun ki fè bagay yo pa t' dwe fè san yo pa fè espre, kit se yon moun pèp Izrayèl la menm li ye, kit se yon moun lòt nasyon k'ap viv nan mitan yo a.", bookId = 4),
        Verse(book = "Nonm", chapter = 15, verseNumber = 30, text = "Men, lè yon moun fè yon bagay li konnen byen pwòp li pa t' dwe fè, kit se yon moun pèp Izrayèl la menm li ye, kit se yon moun lòt nasyon k'ap viv nan mitan yo a, se pase l'ap pase Seyè a nan betiz. Se pou yo wete moun sa a nan mitan pèp la.", bookId = 4),
        Verse(book = "Nonm", chapter = 15, verseNumber = 31, text = "Paske li refize tande sa Seyè a te di a, li fè sa li konnen li pa t' dwe fè. Dapre lòd Seyè a, se pou yo touye l'. Epi se li menm sèl ki va reskonsab lanmò li.", bookId = 4),
        Verse(book = "Nonm", chapter = 15, verseNumber = 32, text = "Yon jou, antan moun pèp Izrayèl yo te nan dezè a, yo bare yon nonm ki t'ap ranmase bwa jou repo a.", bookId = 4),
        Verse(book = "Nonm", chapter = 15, verseNumber = 33, text = "Moun ki te bare l' yo mennen l' bay Moyiz, Arawon ak tout moun pèp Izrayèl yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 15, verseNumber = 34, text = "Yo pran msye, yo mete moun veye l', paske yo pa t' fin konnen sa pou yo te fè avè l'.", bookId = 4),
        Verse(book = "Nonm", chapter = 15, verseNumber = 35, text = "Lè sa a, Seyè a di Moyiz konsa: -Se pou nou touye nonm lan pou sa li fè a. Y'a mennen msye andeyò limit kan kote yo rete a, pou tout moun kalonnen l' kout wòch jouk li mouri.", bookId = 4),
        Verse(book = "Nonm", chapter = 15, verseNumber = 36, text = "Se konsa tout moun yo fè msye soti andeyò limit kan an, epi yo kalonnen msye kout wòch jouk li mouri, jan Seyè a te ba yo lòd la.", bookId = 4),
        Verse(book = "Nonm", chapter = 15, verseNumber = 37, text = "Seyè a pale ak Moyiz, li di l' konsa:", bookId = 4),
        Verse(book = "Nonm", chapter = 15, verseNumber = 38, text = "-Pale ak moun pèp Izrayèl yo. W'a di yo pou mwen: Se pou yo toujou mete ponpon sou woulèt rad yo, se pou yo pase kòdon ble nan chak ponpon. Se pou nou toujou fè sa de pitit an pitit.", bookId = 4),
        Verse(book = "Nonm", chapter = 15, verseNumber = 39, text = "Chak fwa n'a wè ponpon sa yo, sa va fè nou chonje tou sa Seyè a te ban nou lòd fè pou nou ka fè yo. Konsa, nou p'ap pèdi tèt nou, nou p'ap vire do ban mwen pou nou swiv pwòp lide pa nou ak pwòp dezi pa nou.", bookId = 4),
        Verse(book = "Nonm", chapter = 15, verseNumber = 40, text = "Ponpon yo va fè nou chonje tout lòd mwen te ban nou pou nou ka swiv yo, pou nou ka viv apa nèt pou mwen menm ki Bondye nou an.", bookId = 4),
        Verse(book = "Nonm", chapter = 15, verseNumber = 41, text = "Se mwen menm ki Seyè a, Bondye nou an. Se mwen menm ki te fè nou soti kite peyi Lejip la pou m' te ka Bondye nou. Se mwen menm ki Seyè a, Bondye nou an.", bookId = 4),
        Verse(book = "Nonm", chapter = 16, verseNumber = 1, text = "Kore, pitit gason Iza, moun laras Levi nan fanmi Keyat la, pran tèt Datan ak Abiram, pitit gason Eliyab yo ansanm ak One, pitit gason Pelèt, twa moun laras Woubenn.", bookId = 4),
        Verse(book = "Nonm", chapter = 16, verseNumber = 2, text = "Yo revòlte kont Moyiz. Te gen desansenkant (250) lòt moun nan pèp Izrayèl la avèk yo. Mesye sa yo, se te chèf pèp la menm te chwazi, moun ki te fè pati konsèy pèp la, chèf moun yo te konsidere anpil.", bookId = 4),
        Verse(book = "Nonm", chapter = 16, verseNumber = 3, text = "Yo tout reyini devan Moyiz ak Arawon, yo di yo konsa: -Koulye a, mesye, n' al twò lwen tande! Dènye moun nan pèp la se pou Seyè a y'ap viv. Seyè a la nan mitan nou tout, pa vre? Poukisa, nou menm Moyiz ak Arawon, nou pran pòz chèf nou anwo pèp Seyè a konsa?", bookId = 4),
        Verse(book = "Nonm", chapter = 16, verseNumber = 4, text = "Lè Moyiz tande sa, li lage kò l' atè plat, li lapriyè. Lèfini, li di Kore ak bann moun ki te avè l' yo konsa:", bookId = 4),
        Verse(book = "Nonm", chapter = 16, verseNumber = 5, text = "-Denmen maten, Seyè a va fè nou konnen ki moun ki pou li, ki moun li mete apa pou l' ak ki moun ki gen dwa pwoche bò kote l'. Moun la kite pwoche bò kote l' la, n'a konnen se moun sa a Bondye chwazi.", bookId = 4),
        Verse(book = "Nonm", chapter = 16, verseNumber = 6, text = "Men sa pou n' fè. Ou menm, Kore, ak chak moun ki nan bann ou an, nou chak n'a pran yon ti recho dife.", bookId = 4),
        Verse(book = "Nonm", chapter = 16, verseNumber = 7, text = "Denmen maten chak moun va ranje chabon dife nan recho pa l' la, epi l'a mete lansan sou dife a devan lotèl Seyè a. Konsa, moun Seyè a va chwazi a, n'a konnen se li menm Bondye mete apa pou l' a. Se nou menm, pitit Levi yo, ki pral twò lwen koulye a!", bookId = 4),
        Verse(book = "Nonm", chapter = 16, verseNumber = 8, text = "Moyiz di Kore konsa: -Koute non, nou menm pitit Levi yo!", bookId = 4),
        Verse(book = "Nonm", chapter = 16, verseNumber = 9, text = "Apre tou sa Bondye fè pou nou, nou jwenn li pa fè ase toujou: Nan tout pèp Izrayèl la, se nou li chwazi pou pwoche bò kote l', pou fè sèvis li nan kay li, pou kanpe devan pèp la pou fè sèvis pou yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 16, verseNumber = 10, text = "Ou menm Kore ak tout frè ou yo, pitit Levi yo, li ban nou dwa pou nou pwoche bò kote l'. Epi koulye a, n'ap mande pou yo ban nou plas prèt yo!", bookId = 4),
        Verse(book = "Nonm", chapter = 16, verseNumber = 11, text = "Lè ou menm ak tout bann mesye ou yo n'ap plenyen konsa sou do Arawon, kisa Arawon ye nan sa? Konnen se kont Seyè a menm wi nou pran pozisyon.", bookId = 4),
        Verse(book = "Nonm", chapter = 16, verseNumber = 12, text = "Apre sa, Moyiz voye rele Datan ak Abiram, de nan pitit gason Eliyab yo. Men yo voye di Moyiz: -Nou p'ap vini.", bookId = 4),
        Verse(book = "Nonm", chapter = 16, verseNumber = 13, text = "Ou fin fè nou kite yon bon ti peyi kote lèt ak siwo myèl t'ap koule tankou dlo, ou mennen nou vin mouri isit nan dezè a, epi koulye a ou vle pran pòz chèf ou sou nou ankò!", bookId = 4),
        Verse(book = "Nonm", chapter = 16, verseNumber = 14, text = "Ou mèt di sa ou vle, men se pa nan yon peyi kote lèt ak siwo myèl koule tankou dlo ou mennen nou la a! Ou pa ban nou okenn jaden pou n' plante grenn ni okenn jaden rezen ou te di ou t'ap ban nou an. Atò, ou kwè ou kapab pete je moun sa yo? Non! Nou p'ap vini.", bookId = 4),
        Verse(book = "Nonm", chapter = 16, verseNumber = 15, text = "Lè sa a, Moyiz fè yon sèl fache, li di Seyè a konsa: -Pa asepte okenn ofrann moun sa yo ta pote vin ofri ou. Mwen pa janm pran anyen nan zafè yo, pa menm yon bourik. Mwen pa janm fè yonn ladan yo anyen.", bookId = 4),
        Verse(book = "Nonm", chapter = 16, verseNumber = 16, text = "Apre sa, Moyiz di Kore konsa: -Ou menm ak tout bann moun ou yo, denmen n'a vini devan lotèl Seyè a. Arawon va la tou.", bookId = 4),
        Verse(book = "Nonm", chapter = 16, verseNumber = 17, text = "Chak moun va pran yon ti recho dife, y'a mete lansan ladan l', epi y'a pote recho yo devan Seyè a. Sa va fè desansenkant (250) recho. Ou menm ak Arawon, n'a vini ak recho pa nou tou.", bookId = 4),
        Verse(book = "Nonm", chapter = 16, verseNumber = 18, text = "Se konsa, yo chak pran yon ti recho, yo ranje chabon dife ladan l', yo mete lansan sou dife a, epi yo vin kanpe devan pòt Tant Randevou a ansanm ak Moyiz ak Arawon.", bookId = 4),
        Verse(book = "Nonm", chapter = 16, verseNumber = 19, text = "Kore te fè tout pèp la reyini nan pòt Tant Randevou a anfas Moyiz ak Arawon. Yo rete konsa, epi pouvwa Bondye parèt tankou yon gwo limyè devan tout pèp la.", bookId = 4),
        Verse(book = "Nonm", chapter = 16, verseNumber = 20, text = "Seyè a pale ak Moyiz ansanm ak Arawon, li di yo:", bookId = 4),
        Verse(book = "Nonm", chapter = 16, verseNumber = 21, text = "-Wete kò nou nan mitan moun sa yo. Mwen pral disparèt yo koulye a.", bookId = 4),
        Verse(book = "Nonm", chapter = 16, verseNumber = 22, text = "Men Moyiz ak Arawon tonbe fas atè, yo di: -O Bondye, ou menm ki bay tout moun lavi, se pa paske yon sèl moun fè sa l' pa t' dwe fè kifè pou ou fache sou tout pèp la.", bookId = 4),
        Verse(book = "Nonm", chapter = 16, verseNumber = 23, text = "Seyè a pale ak Moyiz, li di l' konsa:", bookId = 4),
        Verse(book = "Nonm", chapter = 16, verseNumber = 24, text = "-Pale ak tout pèp la. Di yo pou mwen pou yo wete kò yo bò kote Kore, Datan ak Abiram rete a.", bookId = 4),
        Verse(book = "Nonm", chapter = 16, verseNumber = 25, text = "Moyiz leve, l' al jwenn Datan ak Abiram. Tout chèf fanmi pèp Izrayèl yo te ale avè l' tou.", bookId = 4),
        Verse(book = "Nonm", chapter = 16, verseNumber = 26, text = "Li pale ak pèp la, li di yo: -Wete kò nou bò kote bann mechan sa yo rete a. Pa manyen anyen ki pou yo, si nou pa vle pase tou nan chatiman yo pral ba yo pou peche yo fè a.", bookId = 4),
        Verse(book = "Nonm", chapter = 16, verseNumber = 27, text = "Se konsa, tout pèp la wete kò yo, yo rete byen lwen kote Kore, Datan ak Abiram te rete a. Datan ak Abiram menm soti, yo vin kanpe devan pòt kay yo ansanm ak madanm yo, pitit yo ak pitit pitit yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 16, verseNumber = 28, text = "Moyiz di pèp la konsa: -Avèk sa ki pral rive a, nou pral konnen se Seyè a menm ki te voye m' fè tout travay sa yo. Se pa mwen menm ki rete konsa mwen di mwen pral fè yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 16, verseNumber = 29, text = "Si moun sa yo mouri jan tout moun fèt pou mouri a, san se pa Bondye ki pini yo, enben, se pa Seyè a ki te voye m'.", bookId = 4),
        Verse(book = "Nonm", chapter = 16, verseNumber = 30, text = "Men, si Seyè a fè bagay nou poko janm wè, si li fè tè a louvri pou l' vale moun sa yo ansanm ak tou sa ki pou yo, kifè y'ap desann tou vivan nan peyi kote mò yo ye a, n'a konnen se Seyè a menm yo t'ap derespekte konsa.", bookId = 4),
        Verse(book = "Nonm", chapter = 16, verseNumber = 31, text = "Fini li fini di pawòl sa yo, tè a fann, li louvri anba pye Datan ak Abiram.", bookId = 4),
        Verse(book = "Nonm", chapter = 16, verseNumber = 32, text = "Li vale yo, yo menm, tout fanmi yo ansanm ak tout moun ki te pran pozisyon pou Kore, ak tou sa ki te pou yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 16, verseNumber = 33, text = "Yo desann tou vivan avèk tou sa ki te pou yo nan peyi kote mò yo ye a. Apre sa, tè a fèmen sou yo, yo disparèt nèt nan mitan pèp la.", bookId = 4),
        Verse(book = "Nonm", chapter = 16, verseNumber = 34, text = "Tout moun nan pèp la ki te la pran kouri lè yo tande jan moun yo t'ap rele. Yo t'ap di: -Ann kouri pou tè a pa vale nou tou.", bookId = 4),
        Verse(book = "Nonm", chapter = 16, verseNumber = 35, text = "Menm lè a tou, Seyè a voye yon sèl dife ki devore tout desansenkant (250) mesye ki t'ap ofri lansan yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 16, verseNumber = 36, text = "Seyè a pale ak Moyiz, li di l' konsa:", bookId = 4),
        Verse(book = "Nonm", chapter = 16, verseNumber = 37, text = "-Mande Eleaza, pitit gason Arawon, prèt la, pou l' ale wete recho dife an kwiv yo nan mitan rès moun boule yo. L'a jete chabon dife ki ladan yo yon kote byen lwen, paske recho dife sa yo se bagay ki apa pou mwen.", bookId = 4),
        Verse(book = "Nonm", chapter = 16, verseNumber = 38, text = "Wi, yo apa pou mwen paske mesye sa yo ki mouri pou peche yo te ofri yo devan lotèl Seyè a. W'a pran recho sa yo, w'a bat yo ak mato fè yo tounen plak fin pou kouvri lotèl la. Sa va sèvi yon avètisman pou moun pèp Izrayèl yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 16, verseNumber = 39, text = "Se konsa, Eleaza, prèt la, te pran recho an kwiv moun boule yo te ofri yo, li bat yo ak mato, li fè yon kouvèti pou lotèl la", bookId = 4),
        Verse(book = "Nonm", chapter = 16, verseNumber = 40, text = "pou sa sèvi yon avètisman pou moun pèp Izrayèl yo, pou yo konnen moun ki pa fè pati fanmi Arawon an pa gen dwa pwoche devan lotèl Seyè a pou boule lansan. Si yo fè sa, sa ki rive Kore ak moun li yo, se sa k'ap rive moun sa yo tou. Tou sa pase konsa vre dapre lòd Seyè a te bay Moyiz pou Eleaza.", bookId = 4),
        Verse(book = "Nonm", chapter = 16, verseNumber = 41, text = "Nan denmen, tout moun pèp Izrayèl yo pran bougonnen sou do Moyiz ak Arawon, yo t'ap di: -Se nou menm ki lakòz moun pèp Seyè a ap mouri konsa.", bookId = 4),
        Verse(book = "Nonm", chapter = 16, verseNumber = 42, text = "Lè pèp la fin sanble pou yo pran pozisyon kont Moyiz ak Arawon, yo vire je yo gade Tant Randevou a, yo wè nwaj la te kouvri tant lan. Menm lè a, pouvwa Bondye-a parèt tankou yon gwo limyè.", bookId = 4),
        Verse(book = "Nonm", chapter = 16, verseNumber = 43, text = "Moyiz ak Arawon ale, yo kanpe devan Tant Randevou a.", bookId = 4),
        Verse(book = "Nonm", chapter = 16, verseNumber = 44, text = "Seyè a pale ak Moyiz ansanm ak Arawon, li di yo konsa:", bookId = 4),
        Verse(book = "Nonm", chapter = 16, verseNumber = 45, text = "-Wete kò nou nan mitan pèp sa a. Mwen pral disparèt yo koulye a menm! De mesye yo tonbe fas atè.", bookId = 4),
        Verse(book = "Nonm", chapter = 16, verseNumber = 46, text = "Epi Moyiz di Arawon konsa: -Pran ti recho dife ou la, pran chabon dife sou lotèl la, mete ladan l'. Vide ti lansan sou dife a. Epi kouri vit avè l' al jwenn pèp la. W'a fè sèvis pou mande Bondye padon pou yo. Fè vit non! Seyè a fache anpil, li gen tan pran desizyon l'. Malè a konmanse deja.", bookId = 4),
        Verse(book = "Nonm", chapter = 16, verseNumber = 47, text = "Arawon pran ti recho a, li fè sa Moyiz te di l' fè a. Epi li pran kouri nan mitan pèp la. Men, malè a te deja konmanse ap fè dega nan pèp la. Lè Arawon wè sa, li mete lansan sou dife a, li fè sèvis pou mande Bondye padon pou yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 16, verseNumber = 48, text = "Se konsa malè a te sispann. Arawon te kanpe nan mitan ak mò yo yon bò, moun vivan yo yon lòt bò.", bookId = 4),
        Verse(book = "Nonm", chapter = 16, verseNumber = 49, text = "Te gen katòzmil sètsan moun (14.700) antou ki te mouri nan malè sa a, san konte sa ki te mouri akòz Kore yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 16, verseNumber = 50, text = "Lè malè a sispann nèt, Arawon tounen al jwenn Moyiz, devan papòt Kay Randevou a.", bookId = 4),
        Verse(book = "Nonm", chapter = 17, verseNumber = 1, text = "Seyè a pale ak Moyiz, li di l' konsa:", bookId = 4),
        Verse(book = "Nonm", chapter = 17, verseNumber = 2, text = "-Pale ak moun pèp Izrayèl yo. Di yo pou yo pote douz branch bwa, yon branch bwa pou chak branch fanmi pèp Izrayèl la. Wi, y'a pran yon branch bwa nan men chèf chak branch fanmi. Epi w'a ekri non chak chèf sou branch bwa pa yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 17, verseNumber = 3, text = "W'a ekri non Arawon sou branch bwa Levi a. Va gen yon sèl branch bwa pou chak moun ki chèf nan branch fanmi pa l'.", bookId = 4),
        Verse(book = "Nonm", chapter = 17, verseNumber = 4, text = "W'a mete yo nan Tant Randevou a, devan Bwat Kontra a, kote mwen ban nou randevou a.", bookId = 4),
        Verse(book = "Nonm", chapter = 17, verseNumber = 5, text = "Branch bwa ki pote non moun mwen chwazi a, se li menm ki va fè flè. Se konsa m'a fè moun Izrayèl yo sispann bougonnen sou do ou.", bookId = 4),
        Verse(book = "Nonm", chapter = 17, verseNumber = 6, text = "Moyiz pale ak moun pèp Izrayèl yo. Epi chak chèf pote ba li yon branch bwa, yonn pou chak branch fanmi. Sa te fè douz branch bwa antou. Branch bwa Arawon an te nan mitan tout lòt yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 17, verseNumber = 7, text = "Moyiz pran tout branch bwa yo, li mete yo devan Bwat Kontra Seyè a, nan Tant Randevou a.", bookId = 4),
        Verse(book = "Nonm", chapter = 17, verseNumber = 8, text = "Nan denmen, lè Moyiz antre nan Tant Randevou a, li wè branch bwa Arawon an, ki pou branch fanmi Levi a, te fè flè. Li te gen tan fè bouton, flè yo te louvri, zanmann yo te mi.", bookId = 4),
        Verse(book = "Nonm", chapter = 17, verseNumber = 9, text = "Moyiz pran tout branch bwa yo ki te devan lotèl Seyè a, li pote yo bay moun pèp Izrayèl yo. Yo wè sa ki rive, epi chak chèf pran branch bwa ki te pou yo a.", bookId = 4),
        Verse(book = "Nonm", chapter = 17, verseNumber = 10, text = "Seyè a di Moyiz: -Remete branch bwa Arawon an devan Bwat Kontra a. Se pou yo konsève l' pou sa sèvi yon siy pou moun tèt di sa yo, pou yo ka sispann bougonnen. Si yo pa sispann bougonnen, y'ap mouri!", bookId = 4),
        Verse(book = "Nonm", chapter = 17, verseNumber = 11, text = "Moyiz fè jan Seyè a te ba li lòd fè a.", bookId = 4),
        Verse(book = "Nonm", chapter = 17, verseNumber = 12, text = "Apre sa, moun pèp Izrayèl yo pale ak Moyiz, yo di l' konsa: -Gade jan n'ap mouri, n'ap deperi, nou tout ap fini.", bookId = 4),
        Verse(book = "Nonm", chapter = 17, verseNumber = 13, text = "Depi yon moun pwoche bò Tant Randevou a, li mouri. Si se konsa, nou tout ap mouri!", bookId = 4),
        Verse(book = "Nonm", chapter = 18, verseNumber = 1, text = "Seyè a di Arawon konsa: -Se ou menm, pitit gason ou yo ansanm ak tout lòt moun nan branch fanmi Levi a, ki va reskonsab tout bagay mal ki pase nan tant yo mete apa pou Bondye a. Men, se ou menm ak pitit gason ou yo ase ki va reskonsab tout bagay mal ki pase nan travay prèt yo gen pou fè a.", bookId = 4),
        Verse(book = "Nonm", chapter = 18, verseNumber = 2, text = "W'a pran fanmi ou yo, moun branch fanmi Levi, granpapa ou la, w'a mete yo ansanm avè ou pou yo ka ede ou, pandan ou menm ak pitit gason ou yo, n'ap fè travay nou devan Tant Randevou a.", bookId = 4),
        Verse(book = "Nonm", chapter = 18, verseNumber = 3, text = "Y'a fè tou sa yo gen pou yo fè pou ou, ak tou sa pou yo fè nan kay Bondye a. Men, se pa pou yo janm pwoche bò bagay yo mete apa pou Bondye yo, ni bò lotèl yo. Si yo fè sa, ni ou menm ni yo menm, n'ap mouri.", bookId = 4),
        Verse(book = "Nonm", chapter = 18, verseNumber = 4, text = "Y'a travay ansanm avè ou, y'a fè tou sa y'a gen pou yo fè nan kay Bondye a, nan tout travay ki gen pou fèt nan kay Bondye a. Pesonn lòt pa gen dwa travay avè ou.", bookId = 4),
        Verse(book = "Nonm", chapter = 18, verseNumber = 5, text = "Men, ou menm ak pitit gason ou yo, n'a fè tou sa nou gen pou nou fè nan kote ki apa pou Seyè a, tou sa nou gen pou nou fè pou lotèl la. Konsa, mwen p'ap janm fache ankò sou moun pèp Izrayèl yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 18, verseNumber = 6, text = "Se mwen menm ki te pran fanmi ou yo, moun Levi yo, ki te chwazi yo nan mitan tout moun pèp Izrayèl yo, mwen mete yo apa pou mwen. Se mwen ki ba ou yo pou yo ka travay nan Tant Randevou a.", bookId = 4),
        Verse(book = "Nonm", chapter = 18, verseNumber = 7, text = "Men, se ou menm sèl ak pitit gason ou yo ki pou fè travay prèt yo bò lotèl la ak dèyè rido a. Sa se travay pa nou sa. Mwen ban nou pouvwa pou nou sèvi m' prèt. Se yon kado mwen fè nou. Se pou yo touye nenpòt lòt moun ki va pwoche bò bagay yo mete apa pou mwen yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 18, verseNumber = 8, text = "Apre sa, Seyè a di Arawon konsa: -Chonje mwen pran yon pòsyon nan tout ofrann moun pèp Izrayèl yo fè pou mwen, mwen ba ou yo. Se va pòsyon ki va toujou rete pou ou ak pou pitit gason ou yo depi lè mwen te mete nou apa pou mwen an, dapre regleman ki la pou tout tan tout tan an.", bookId = 4),
        Verse(book = "Nonm", chapter = 18, verseNumber = 9, text = "Nan ofrann yo mete apa nèt pou mwen yo, lè ou fin wete pòsyon pou boule nan dife a, tout rès la va pou nou: tout ofrann grenn ki donnen nan jaden, tout ofrann pou mande Bondye padon, tout ofrann pou repare sa yo fè ki mal. Tou sa yo ofri ban mwen tankou yon ofrann yo mete apa pou mwen, se pou ou ak pou pitit gason ou yo y'a ye.", bookId = 4),
        Verse(book = "Nonm", chapter = 18, verseNumber = 10, text = "N'a manje yo yon kote yo mete apa pou Seyè a. Se gason ase ki pou manje ladan yo. Konsidere ofrann sa yo tankou bagay ki apa pou Seyè a.", bookId = 4),
        Verse(book = "Nonm", chapter = 18, verseNumber = 11, text = "Lèfini, tout ofrann espesyal moun pèp Izrayèl yo va fè pou yo balanse devan Seyè a, se pou ou yo va ye tou. M'ap ba ou yo pou ou, pou pitit gason ou yo ak pitit fi ou yo, dapre yon regleman k'ap la pou tout tan tout tan. Tout moun nan fanmi ou ki nan kondisyon pou fè sèvis pou mwen va gen dwa manje ladan l'.", bookId = 4),
        Verse(book = "Nonm", chapter = 18, verseNumber = 12, text = "M'ap ba ou tou tousa ki pi bon nan premye fwi rekòt y'ap ofri bay Seyè a chak lanne: lwil oliv, diven ak grenn ki donnen nan jaden.", bookId = 4),
        Verse(book = "Nonm", chapter = 18, verseNumber = 13, text = "Tout premye fwi ki mi nan peyi a, fwi yo ofri bay Seyè a, se va pou ou tou. Tout moun lakay ou ki nan kondisyon pou sèvi Seyè a va gen dwa manje ladan yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 18, verseNumber = 14, text = "Tout bagay moun pèp Izrayèl yo pran angajman mete apa pou Seyè a va pou ou tou.", bookId = 4),
        Verse(book = "Nonm", chapter = 18, verseNumber = 15, text = "Tout premye pitit, kit se pitit moun, kit se pitit bèt, y'a mete yo apa pou mwen, e se pou ou yo va ye tou. Men, se pou ou asepte yo peye ou pou chak premye pitit moun ak tout premye pitit bèt ki pa ka sèvi ofrann pou mwen.", bookId = 4),
        Verse(book = "Nonm", chapter = 18, verseNumber = 16, text = "Lè premye pitit gason an va gen yon mwa, w'a fè yo peye ou senk pyès ajan dapre sistèm yo sèvi nan kay Bondye a, -vin gera pou yon pyès ajan-,pou yo ka achte lavi l' nan men m'.", bookId = 4),
        Verse(book = "Nonm", chapter = 18, verseNumber = 17, text = "Men, pou premye ti mal yon manman bèf osinon yon manman kabrit ou ankò yon manman mouton fè, ou p'ap asepte anyen pou yo. Se bagay ki apa pou mwen nèt. Se pou yo touye yo. Y'a vide san yo sou lotèl la, w'a boule grès yo. Se va yon ofrann y'a boule nèt pou mwen, yon ofrann ki va fè m' plezi ak bon sant li.", bookId = 4),
        Verse(book = "Nonm", chapter = 18, verseNumber = 18, text = "Men, vyann yo va rete pou ou ansanm ak vyann pwatrin lan ak jigo dwat ki te deja pou ou a.", bookId = 4),
        Verse(book = "Nonm", chapter = 18, verseNumber = 19, text = "M'ap ba ou pou ou menm, pou pitit gason ak pitit fi ou yo tout pòsyon ki va rete nan ofrann moun pèp Izrayèl yo va mete apa pou mwen. Se va yon regleman k'ap la pou tout tan tout tan. Se yon kontra ki p'ap janm kase ni ki p'ap janm gate mwen fè la avèk ou, pou ou ak pou tout ras fanmi ou.", bookId = 4),
        Verse(book = "Nonm", chapter = 18, verseNumber = 20, text = "Apre sa, Seyè a di Arawon konsa: -Ou p'ap jwenn okenn pòsyon nan tè eritaj ki pou pèp la. Ou p'ap janm gen yon moso tè ki va rele ou pa ou nan peyi a. Se mwen menm ki tout ou, se mwen menm ki tout byen ou nan mitan pèp Izrayèl la.", bookId = 4),
        Verse(book = "Nonm", chapter = 18, verseNumber = 21, text = "Seyè a di konsa: -Mwen mete tout ladim moun Izrayèl yo va bay la apa pou moun branch fanmi Levi yo, pou sèvis y'ap rann nan tanp lan, pou travay y'ap fè nan Tant Randevou a.", bookId = 4),
        Verse(book = "Nonm", chapter = 18, verseNumber = 22, text = "Moun pèp Izrayèl yo pa janm bezwen preche bò Tant Randevou a. Konsa, yo p'ap rive fè yon peche ki pou ta fè yo mouri.", bookId = 4),
        Verse(book = "Nonm", chapter = 18, verseNumber = 23, text = "Depi koulye a, se moun Levi yo ki va pran swen tout bagay nan Tant Randevou a. Y'a reskonsab pou tout bagay mal y'a fè. Sa se yon lòd sevè pou tout moun swiv de pitit an pitit. Se konsa yo menm tou, yo p'ap gen tè k'ap rele yo pa yo pou tout tan nan mitan pèp Izrayèl la.", bookId = 4),
        Verse(book = "Nonm", chapter = 18, verseNumber = 24, text = "M'ap bay moun Levi yo tout ladim moun pèp Izrayèl yo pran sou sa yo genyen pou ofri bay Seyè a. Se poutèt sa, mwen di moun fanmi Levi yo p'ap gen okenn pòsyon tè ki pou rele yo pa yo nan peyi Izrayèl la.", bookId = 4),
        Verse(book = "Nonm", chapter = 18, verseNumber = 25, text = "Seyè a pale ak Moyiz ankò, li di l':", bookId = 4),
        Verse(book = "Nonm", chapter = 18, verseNumber = 26, text = "-Pale ak moun Levi yo, di yo konsa: Lè n'a resevwa nan men moun pèp Izrayèl yo ladim Seyè a ban nou pou byen pa nou, n'a wete yon dizyèm ladan l' pou mwen. Se va ofrann ladim pa nou bay Seyè a.", bookId = 4),
        Verse(book = "Nonm", chapter = 18, verseNumber = 27, text = "Y'a konsidere ofrann sa a tankou ofrann lòt moun yo fè sou farin ble ak diven apre chak rekòt.", bookId = 4),
        Verse(book = "Nonm", chapter = 18, verseNumber = 28, text = "Konsa, nou menm tou, n'a pran yon pòsyon nan tout ofrann ladim moun pèp Izrayèl yo va fè, n'a mete l' apa pou mwen. Epi n'a pran pòsyon nou wete pou Seyè a nan sa ki pou nou an, n'a bay Arawon, prèt la, li pou tèt pa li.", bookId = 4),
        Verse(book = "Nonm", chapter = 18, verseNumber = 29, text = "N'a pran sa ki pi bon nan tout sa ki pou nou an, n'a ofri l' bay Seyè a.", bookId = 4),
        Verse(book = "Nonm", chapter = 18, verseNumber = 30, text = "W'a di yo tou: Lè moun Levi yo fin pran sa ki pi bon nan tou sa ki pou vin pou yo a, y'a konsidere rès ki rete a tankou rekòt farin ble ak diven yo menm yo fè.", bookId = 4),
        Verse(book = "Nonm", chapter = 18, verseNumber = 31, text = "Y'a manje l' kote yo vle, ansanm ak tout moun lakay yo. Se tankou lajan yo ba yo pou travay y'ap fè nan Tant Randevou a.", bookId = 4),
        Verse(book = "Nonm", chapter = 18, verseNumber = 32, text = "Depi nou ofri sa ki pi bon an bay Seyè a, nou mèt manje rès la san kè sote, anyen p'ap rive nou. Piga nou derespekte bagay moun pèp Izrayèl yo mete apa pou mwen. Si nou fè sa, n'ap mouri.", bookId = 4),
        Verse(book = "Nonm", chapter = 19, verseNumber = 1, text = "Seyè a pale ak Moyiz ansanm ak Arawon, li di yo konsa:", bookId = 4),
        Verse(book = "Nonm", chapter = 19, verseNumber = 2, text = "-Men yon regleman Seyè a bay lòd pou yo swiv tankou yon lwa: Men sa li di: Mande moun pèp Izrayèl yo pou yo fè ou jwenn yon gazèl pwal koulè wouj, ki pa gen okenn enfimite e ki poko janm travay.", bookId = 4),
        Verse(book = "Nonm", chapter = 19, verseNumber = 3, text = "W'a renmèt Eleaza, prèt la, li. L'a fè l' soti andeyò limit kan kote moun yo rete a, epi l'a fè yo touye l' devan je li.", bookId = 4),
        Verse(book = "Nonm", chapter = 19, verseNumber = 4, text = "Apre sa, Eleaza va pran ti gout nan san an. Epi, kote l' kanpe a, avèk dwèt li, l'a voye san an sèt fwa nan direksyon Tant Randevou a.", bookId = 4),
        Verse(book = "Nonm", chapter = 19, verseNumber = 5, text = "Lèfini, y'a boule tout bèt la nèt devan je prèt la: po a, vyann lan, san an ansanm ak tout tripay la.", bookId = 4),
        Verse(book = "Nonm", chapter = 19, verseNumber = 6, text = "Prèt la va pran kèk moso bwa sèd, kèk branch izòp, yon moso twal wouj, l'a jete yo nan boukan dife kote gazèl la ap boule a.", bookId = 4),
        Verse(book = "Nonm", chapter = 19, verseNumber = 7, text = "Apre sa, prèt la va lave rad ki te sou li, l'a benyen nan gwo dlo. Lèfini, l'a tounen antre nan kan an. Prèt la p'ap nan kondisyon pou l' fè okenn sèvis pou Bondye jouk aswè.", bookId = 4),
        Verse(book = "Nonm", chapter = 19, verseNumber = 8, text = "Moun ki te boule gazèl la va lave rad ki te sou l' a, epi l'a benyen nan gwo dlo tou. Li menm tou, li p'ap nan kondisyon pou l' fè okenn sèvis pou Bondye jouk aswè.", bookId = 4),
        Verse(book = "Nonm", chapter = 19, verseNumber = 9, text = "Yon lòt moun ki nan kondisyon pou fè sèvis pou Bondye va ranmase tout sann gazèl wouj la, l'a mete l' yon kote ki apa pou Bondye andeyò limit kan kote moun yo rete a. Y'a konsève sann lan pou lè moun pèp Izrayèl yo va bezwen pran ladan l' pou pare dlo y'a sèvi pou mete nenpòt bagay nan kondisyon pou fè sèvis Bondye ankò, lè y'ap fè sèvis pou mande Bondye padon pou sa yo fè ki mal.", bookId = 4),
        Verse(book = "Nonm", chapter = 19, verseNumber = 10, text = "Nonm ki te ranmase sann gazèl la va lave rad ki te sou l' a, epi li p'ap nan kondisyon pou l' fè okenn sèvis pou Bondye jouk aswè. Sa se va yon regleman pou tout moun nan peyi a toujou swiv, kit se moun pèp Izrayèl yo, kit se moun lòt nasyon k'ap viv nan mitan yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 19, verseNumber = 11, text = "Depi yon moun manyen kadav yon moun mouri, pandan sèt jou apre sa, li p'ap nan kondisyon pou l' fè sèvis pou Bondye.", bookId = 4),
        Verse(book = "Nonm", chapter = 19, verseNumber = 12, text = "L'a fè sèvis pou mande Bondye gras avèk dlo yo pare pou sa a sou twazyèm jou a ak sou setyèm jou a. Apre sa, l'a nan kondisyon pou l' fè sèvis Bondye. Men, si li pa fè sèvis pou mande Bondye gras sou twazyèm jou a ak sou setyèm jou a, li p'ap nan kondisyon pou l' fè sèvis Bondye.", bookId = 4),
        Verse(book = "Nonm", chapter = 19, verseNumber = 13, text = "Depi yon moun manyen kadav yon moun mouri, si li pa fè sèvis pou mande Bondye gras, piga li pwoche bò Tant Randevou a pou li pa derespekte tant lan. Si li fè sa, se pou yo touye l'. Se pou yo konsidere moun sa a tankou yon moun ki pa fè pati pèp Bondye a, paske yo pa t' voye dlo pou mete nan bon kondisyon an sou li, li pa nan kondisyon pou l' sèvi Bondye. Toutotan yo pa fè sèvis la pou li, l'ap rete nan kondisyon sa a.", bookId = 4),
        Verse(book = "Nonm", chapter = 19, verseNumber = 14, text = "Men regleman pou yo swiv: lè yon moun mouri nan yon kay, tout moun ki te nan kay la lè lanmò a, ou ankò tout moun ki vin antre nan kay la apre sa, p'ap nan kondisyon pou fè sèvis Bondye pandan sèt jou.", bookId = 4),
        Verse(book = "Nonm", chapter = 19, verseNumber = 15, text = "Tout veso ki pa kouvri ak yon kouvèti byen mare sou li p'ap ka sèvi pou moun ki nan kondisyon pou sèvi Bondye.", bookId = 4),
        Verse(book = "Nonm", chapter = 19, verseNumber = 16, text = "Konsa tou, depi yon moun k'ap mache nan jaden manyen kadav yon moun mouri, kit moun lan mouri mò natirèl, kit se ansasinen yo te ansasinen l', osinon depi yon moun manyen zosman yon moun mouri oswa tonm kote yo antere yon moun mouri, moun sa a p'ap nan kondisyon pou l' sèvi Bondye pandan sèt jou.", bookId = 4),
        Verse(book = "Nonm", chapter = 19, verseNumber = 17, text = "Si yon moun ta rive nan kondisyon sa a konsa, y'a pran ti gout nan sann gazèl yo te boule pou wete peche a, y'a mete l' nan yon veso, epi y'a vide ti gout dlo dous sou li.", bookId = 4),
        Verse(book = "Nonm", chapter = 19, verseNumber = 18, text = "Nan premye ka a, yon moun ki nan kondisyon pou fè sèvis Bondye va pran yon branch izòp, l'a plonje l' nan dlo a, epi l'a voye dlo sou kay la, sou tout bagay ki ladan l' ak sou tout moun ki te la nan kay la. Nan dezyèm ka a, l'a voye dlo a sou moun lan, kit li te manyen zosman moun mouri osinon kadav moun yo te ansasinen, osinon kadav moun ki te mouri mò natirèl, kit li te manyen yon tonm moun mouri.", bookId = 4),
        Verse(book = "Nonm", chapter = 19, verseNumber = 19, text = "Sou twazyèm jou a ak sou setyèm jou a, nonm ki nan kondisyon pou fè sèvis pou Bondye a va voye dlo a sou moun ki pa nan kondisyon pou sèvi Bondye a. Sou setyèm jou a, l'a fè sèvis pou mande Bondye gras pou nonm lan. Apre sa, nonm lan va lave rad ki sou l' a, l'a benyen nan gwo dlo. Men, se lè solèy va fin kouche la nan kondisyon ankò pou l' fè sèvis Bondye.", bookId = 4),
        Verse(book = "Nonm", chapter = 19, verseNumber = 20, text = "Men lè yon nonm pa nan kondisyon pou fè sèvis Bondye, si li pa fè sèvis pou mande Bondye gras, se pou yo konsidere l' tankou yon moun ki pa fè pati pèp Bondye a. Li pa ka pwoche bò Tant Randevou a pou l' pa derespekte l'. Toutotan yo pa fè pou li sèvis voye dlo ki pou mete l' nan bon kondisyon an, l'ap rete nan kondisyon pou l' pa ka fè sèvis Bondye.", bookId = 4),
        Verse(book = "Nonm", chapter = 19, verseNumber = 21, text = "Se va la yon regleman pou yo toujou swiv tout tan. Moun ki te voye dlo sou lòt la pou mete l' nan bon kondisyon an, va gen pou l' lave rad ki te sou l' a tou. Depi yon moun manyen dlo pou mete nan bon kondisyon an, li p'ap nan kondisyon pou l' fè sèvis pou Bondye jouk nan aswè menm jou a.", bookId = 4),
        Verse(book = "Nonm", chapter = 19, verseNumber = 22, text = "Depi yon nonm ki pa nan kondisyon pou sèvi Bondye manyen yon bagay, moun ki nan kondisyon pou sèvi Bondye pa ka sèvi ak bagay sa a. Depi yon moun manyen yon bagay konsa, li menm tou, li p'ap nan kondisyon pou l' sèvi Bondye jouk aswè rive.", bookId = 4),
        Verse(book = "Nonm", chapter = 20, verseNumber = 1, text = "Sou premye mwa a, tout moun pèp Izrayèl yo te rive nan dezè Zin lan, epi yo moute tant yo yon kote yo rele Kadès. Se la Miryam mouri, se la menm yo antere l'.", bookId = 4),
        Verse(book = "Nonm", chapter = 20, verseNumber = 2, text = "Men, pa t' gen dlo la pou pèp la te bwè. Pèp la sanble bò kote Moyiz ak Arawon, yo leve kont ak yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 20, verseNumber = 3, text = "Pèp la fè kont ak Moyiz, yo di l' konsa: -Pa pito nou te mouri devan lotèl Seyè a ansanm ak lòt frè nou yo!", bookId = 4),
        Verse(book = "Nonm", chapter = 20, verseNumber = 4, text = "Poukisa ou mennen nou nan dezè a? Gen lè se pou fè nou mouri, nou menm pèp Seyè a, ansanm ak tou bèt nou yo?", bookId = 4),
        Verse(book = "Nonm", chapter = 20, verseNumber = 5, text = "Poukisa ou fè nou soti kite peyi Lejip la pou mennen nou nan move kote sa a? Se yon kote ou pa jwenn grenn pou simen, ou pa jwenn okenn pye fig frans, ni pye rezen, ni pye grenad. Pa menm gen dlo pou moun bwè!", bookId = 4),
        Verse(book = "Nonm", chapter = 20, verseNumber = 6, text = "Moyiz ak Arawon pati kite pèp la, y' ale devan pòt Tant Randevou a. Yo lage kò yo fas atè, epi bèl limyè prezans Bondye a parèt sou yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 20, verseNumber = 7, text = "Seyè a pale ak Moyiz, li di l' konsa:", bookId = 4),
        Verse(book = "Nonm", chapter = 20, verseNumber = 8, text = "-Pran baton ki sou devan Bwat Kontra a. Lèfini, ou menm ak Arawon, frè ou la, sanble tout pèp la. Epi devan yo tout, w'a pale ak wòch ki bò laba a, wòch la va bay dlo. Se konsa w'a fè dlo soti nan wòch la pou pèp la, pou yo tout ka bwè ansanm ak bèt yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 20, verseNumber = 9, text = "Moyiz pran baton ki sou devan lotèl la, jan Seyè a te ba li lòd la.", bookId = 4),
        Verse(book = "Nonm", chapter = 20, verseNumber = 10, text = "Moyiz ak Arawon sanble tout pèp la devan gwo wòch la. Epi Moyiz di yo: -Louvri zòrèy nou, bann moun tèt di! Se vle nou vle mwen fè dlo soti nan wòch sa a pou nou?", bookId = 4),
        Verse(book = "Nonm", chapter = 20, verseNumber = 11, text = "Moyiz leve men l', li frape wòch la de fwa avèk baton an. Epi yon gwo sous dlo pete nan wòch la. Tout moun yo bwè ansanm ak bèt yo tou.", bookId = 4),
        Verse(book = "Nonm", chapter = 20, verseNumber = 12, text = "Men, Seyè a di Moyiz ak Arawon konsa: -Paske nou pa t' fin gen konfyans nèt nan mwen pou n' te fè moun pèp Izrayèl yo wè jan mwen se yon Bondye apa, se pa nou menm m'ap kite mennen pèp la antre nan peyi mwen pwomèt m'ap ba yo a.", bookId = 4),
        Verse(book = "Nonm", chapter = 20, verseNumber = 13, text = "Se kote sa a yo rele sous Meriba a, paske se la moun pèp Izrayèl yo te leve kont ak Seyè a. Se la Seyè a te moutre yo li se yon Bondye ki pa tankou lòt bondye yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 20, verseNumber = 14, text = "Moyiz rete Kadès, li voye kèk mesaje bò wa peyi Edon an pou di l' konsa: -Men sa moun pèp Izrayèl yo, moun menm fanmi ak ou yo, voye di ou: Ou konnen tout tray nou pase.", bookId = 4),
        Verse(book = "Nonm", chapter = 20, verseNumber = 15, text = "Ou konnen ki jan zansèt nou yo te desann al rete nan peyi Lejip pandan lontan, ki jan moun peyi sa a tonbe maltrete nou menm jan yo te maltrete zansèt nou yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 20, verseNumber = 16, text = "Lè nou wè sa, nou rele nan pye Seyè a. Li tande vwa nou, epi li voye zanj li, li fè nou soti kite peyi Lejip sa a. Koulye a, men nou Kadès, yon lavil ki toupre fwontyè peyi ou la.", bookId = 4),
        Verse(book = "Nonm", chapter = 20, verseNumber = 17, text = "Tanpri, n'ap mande ou yon ti pèmisyon pou nou pase ase nan mitan peyi ou la. Nou p'ap kite wout nou pou n' pase nan mitan jaden ou, ni nan mitan pye rezen ou yo. Ata dlo nan pi ou yo nou p'ap bwè. Nou p'ap kite gran chemen w'a moutre nou an, nou p'ap vire ni adwat ni agoch, jouk n'a fin travèse lòt bò peyi a.", bookId = 4),
        Verse(book = "Nonm", chapter = 20, verseNumber = 18, text = "Wa Edon an voye di yo: -Non. Nou p'ap kite nou travèse peyi a. Si nou chache fè sa, n'ap mache pran nou, n'ap atake nou.", bookId = 4),
        Verse(book = "Nonm", chapter = 20, verseNumber = 19, text = "Men, moun pèp Izrayèl yo voye di l' ankò: -Nou p'ap kite gran chemen w'a louvri devan nou an. Epi si yonn nan nou, osinon yonn nan bèt nou yo ta bwè nan dlo peyi ou la, n'ap peye ou pou sa. Se annik pase nou bezwen pase nan mitan peyi a, pa lòt bagay!", bookId = 4),
        Verse(book = "Nonm", chapter = 20, verseNumber = 20, text = "Men, wa Edon an voye di yo ankò: -Non! Nou p'ap pase menm! Epi li soti avèk yon gwo lame ak yon bann lòt moun, yo mache kontre moun pèp Izrayèl yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 20, verseNumber = 21, text = "Se konsa moun peyi Edon yo te refize kite moun pèp Izrayèl yo pase nan peyi yo a. Kifè moun Izrayèl yo te blije vire do yo, fè yon lòt wout.", bookId = 4),
        Verse(book = "Nonm", chapter = 20, verseNumber = 22, text = "Tout moun pèp Izrayèl yo kite Kadès, yo rive sou Mòn Or la,", bookId = 4),
        Verse(book = "Nonm", chapter = 20, verseNumber = 23, text = "ki te toupre fwontyè peyi Edon an. Antan yo la, Seyè a pale ak Moyiz ansanm ak Arawon, li di yo:", bookId = 4),
        Verse(book = "Nonm", chapter = 20, verseNumber = 24, text = "-Arawon pa pral antre nan peyi mwen pwomèt pou m' bay moun pèp Izrayèl yo. Msye pral mouri, li pral jwenn moun li yo ki te mouri anvan l' yo, paske nou tou de, nou pa t' fè sa mwen te ban nou lòd fè bò sous dlo Meriba a.", bookId = 4),
        Verse(book = "Nonm", chapter = 20, verseNumber = 25, text = "Pran Arawon ak Eleaza, pitit gason l' lan, moute sou mòn Or la ak yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 20, verseNumber = 26, text = "W'a wete rad espesyal ki sou Arawon yo, w'a mete yo sou Eleaza, pitit gason l' lan. Se la sou mòn lan Arawon pral mouri.", bookId = 4),
        Verse(book = "Nonm", chapter = 20, verseNumber = 27, text = "Moyiz fè tou sa Seyè a te mande l' fè a: Devan je tout moun, yo tou twa yo moute sou mòn Or la.", bookId = 4),
        Verse(book = "Nonm", chapter = 20, verseNumber = 28, text = "Lèfini, Moyiz wete rad espesyal ki te sou Arawon yo, li mete yo sou Eleaza, pitit gason Arawon an. Se la sou tèt mòn lan Arawon mouri. Apre sa, Moyiz ak Eleaza desann desann yo sou mòn lan.", bookId = 4),
        Verse(book = "Nonm", chapter = 20, verseNumber = 29, text = "Tout pèp la vin konnen Arawon te mouri. Se konsa tout moun nan pèp Izrayèl la pase trant jou ap kriye pou Arawon.", bookId = 4),
        Verse(book = "Nonm", chapter = 21, verseNumber = 1, text = "Wa lavil Arad la, nan rejyon Negèv la, te yon moun peyi Kanaran. Lè li vin tande moun pèp Izrayèl yo t'ap vini sou chemen ki mennen Atarim lan, l' al atake yo. Li fè kèk ladan yo prizonye.", bookId = 4),
        Verse(book = "Nonm", chapter = 21, verseNumber = 2, text = "Lè sa a, moun pèp Izrayèl yo fè yon ve bay Seyè a, yo di konsa: -Si ou lage moun sa yo nan men nou, n'ap mete yo tout apa pou ou ansanm ak tout lavil yo. N'ap detwi yo nèt.", bookId = 4),
        Verse(book = "Nonm", chapter = 21, verseNumber = 3, text = "Seyè a tande sa yo te mande l' la, epi li ede yo, li fè yo mete men sou moun Kanaran yo. Moun pèp Izrayèl yo disparèt tout moun yo ansanm ak tout lavil yo. Se poutèt sa yo rele kote sa a Oma.", bookId = 4),
        Verse(book = "Nonm", chapter = 21, verseNumber = 4, text = "Moun Izrayèl yo pati, yo kite mòn Or la, yo pran wout ki mennen bò Lanmè Wouj la, pou yo pa pase nan peyi Edon an. Men, antan y'ap vwayaje a, pèp la vin dekouraje.", bookId = 4),
        Verse(book = "Nonm", chapter = 21, verseNumber = 5, text = "Pèp la pale Bondye ansanm ak Moyiz mal, yo leve dèyè yo, yo di konsa: -Poukisa nou fè nou soti kite peyi Lejip la? Gen lè se pou fè nou vin mouri nan dezè sa a kote ki pa gen ni manje ni dlo. Nou bouke manje vye manje sa a ki pa ka fè anyen pou nou ankò.", bookId = 4),
        Verse(book = "Nonm", chapter = 21, verseNumber = 6, text = "Lè sa a, Seyè a voye yon bann ti sèpan sou pèp la. Kote sèpan sa yo mòde ou la boule kou dife. Yo mòde pèp la. Anpil moun te mouri.", bookId = 4),
        Verse(book = "Nonm", chapter = 21, verseNumber = 7, text = "Pèp la vin jwenn Moyiz, yo di l' konsa: -Nou rekonèt nou fè sa ki mal lè nou pale kont Seyè a ak kont ou menm tou. Tanpri, lapriyè Seyè a pou nou pou l' fè sèpan sa yo ale. Moyiz lapriyè pou pèp la vre.", bookId = 4),
        Verse(book = "Nonm", chapter = 21, verseNumber = 8, text = "Seyè a di Moyiz konsa: -Fè pòtre yon sèpan parèy ak sèpan sa yo. Mete l' sou yon poto byen wo. Konsa, depi yon sèpan mòde yon moun, moun lan va annik gade pòtre sèpan an, epi li p'ap mouri.", bookId = 4),
        Verse(book = "Nonm", chapter = 21, verseNumber = 9, text = "Moyiz pran kwiv, li fonn li, li fè yon sèpan parèy ak sèpan yo. Lèfini, li mete l' sou yon poto byen wo. Tout moun sèpan mòde, depi yo voye je yo gade sèpan an kwiv la, yo pa mouri.", bookId = 4),
        Verse(book = "Nonm", chapter = 21, verseNumber = 10, text = "Moun pèp Izrayèl yo pati, y' al moute kan yo nan fon Obòt la.", bookId = 4),
        Verse(book = "Nonm", chapter = 21, verseNumber = 11, text = "Apre sa, yo kite fon Obòt, y' al moute kan yo bò mazi Abarim yo nan dezè ki sou bò lès peyi Moab la.", bookId = 4),
        Verse(book = "Nonm", chapter = 21, verseNumber = 12, text = "Apre sa ankò, yo kite kote yo te ye a, y' al moute kan yo nan ravin Zerèd.", bookId = 4),
        Verse(book = "Nonm", chapter = 21, verseNumber = 13, text = "Lè yo kite ravin Zerèd, y' al moute kan yo lòt bò larivyè Anon nan dezè ki rive jouk nan teritwa moun Amori yo. Rivyè Anon sa a te sèvi fwontyè ant peyi Moab ak peyi Amori a.", bookId = 4),
        Verse(book = "Nonm", chapter = 21, verseNumber = 14, text = "Se poutèt sa, nan liv istwa ki rakonte batay Seyè a, nou jwenn yo pale sou lavil Vayèb, nan peyi Soufa a, ak ravin li yo, sou rivyè Anon", bookId = 4),
        Verse(book = "Nonm", chapter = 21, verseNumber = 15, text = "avèk fon lavalas li yo, ki desann bò lavil Amoab la nan direksyon fwontyè peyi Moab la.", bookId = 4),
        Verse(book = "Nonm", chapter = 21, verseNumber = 16, text = "Apre sa, yo kite kote yo te ye a, y' al yon kote yo rele Beyè. Se la Seyè a te pale ak Moyiz, lè li te di l': Reyini tout pèp la. Mwen pral ba yo dlo.", bookId = 4),
        Verse(book = "Nonm", chapter = 21, verseNumber = 17, text = "Lè sa a, moun Izrayèl yo pran chante chante sa a: Pi a bay dlo! Annou chante pou sa!", bookId = 4),
        Verse(book = "Nonm", chapter = 21, verseNumber = 18, text = "Pi chèf yo te fouye Avèk baton kòmandan yo! Pi grannèg yo te fouye Avèk baton yo sèvi lè y'ap mache a! Apre sa, yo kite dezè a, y' al moute kan yo Matana.", bookId = 4),
        Verse(book = "Nonm", chapter = 21, verseNumber = 19, text = "Lè yo kite Matana, y' ale Nakalyèl. Lè yo kite Nakalyèl, yo moute Bannòt.", bookId = 4),
        Verse(book = "Nonm", chapter = 21, verseNumber = 20, text = "Lè yo kite Bannòt, y' ale nan fon ki nan peyi Moab la, jouk sou tèt mòn Pisga, kote y'ap gade tout dezè a nan pye yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 21, verseNumber = 21, text = "Lè sa a, moun pèp Izrayèl yo voye mesaje bò kote Siyon, wa peyi Amori a, pou di l' konsa:", bookId = 4),
        Verse(book = "Nonm", chapter = 21, verseNumber = 22, text = "-Kite nou pase ase nan mitan peyi ou la! Nou p'ap kite wout nou pou pase nan mitan jaden ou, ni nan mitan pye rezen ou yo. Ata bwè nou p'ap bwè dlo nan pi ou yo. N'ap rete sou gran chemen ou va moutre nou an, jouk n'a fin travèse lòt bò peyi ou la.", bookId = 4),
        Verse(book = "Nonm", chapter = 21, verseNumber = 23, text = "Men, Siyon pa t' vle kite pèp Izrayèl la pase sou tè li yo. Li leve tout pèp l' a, li mache sou moun pèp Izrayèl yo, l' al kontre ak yo yon kote nan dezè a yo rele Jaza, l' atake yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 21, verseNumber = 24, text = "Men, moun Izrayèl yo touye anpil ladan yo nan batay la, yo pran tout peyi a nan men yo, depi larivyè Anon nan sid rive larivyè Jabòk nan nò, toupre fwontyè peyi Amon an, ki te yon fwontyè byen gade.", bookId = 4),
        Verse(book = "Nonm", chapter = 21, verseNumber = 25, text = "Se konsa, moun Izrayèl yo pran tout lavil moun Amori yo, depi Esbon, kapital la ak lòt ti bouk nan vwazinaj li ki te sou kont li, epi yo rete ladan yo tout.", bookId = 4),
        Verse(book = "Nonm", chapter = 21, verseNumber = 26, text = "Lavil Esbon te kapital peyi a. Se la Siyon, wa peyi Amori a, te rete. Se menm Siyon sa a ki te goumen kont ansyen wa peyi Moab la epi ki te pran tout peyi a pou li jouk larivyè Anon.", bookId = 4),
        Verse(book = "Nonm", chapter = 21, verseNumber = 27, text = "Se poutèt sa sanba yo di: -Ann ale Esbon! Ann al bati l' ankò! Ann al mete lavil wa Siyon an kanpe sou de pye l' ankò!", bookId = 4),
        Verse(book = "Nonm", chapter = 21, verseNumber = 28, text = "Paske yon sèl dife te soti lavil Esbon, Wi, lame wa Siyon an derape tankou yon flanm dife, li boule lavil A Moab. Li devore tout chèf ki rete sou mòn Anon an.", bookId = 4),
        Verse(book = "Nonm", chapter = 21, verseNumber = 29, text = "Sa pral rèd nèt pou nou, moun peyi Moab! Nou pèdi nèt, nou menm sèvitè Kemòch! Bondye nou an fè pitit gason nou yo kouri al kache. Li kite pitit fi nou yo tounen prizonye nan men Siyon, wa peyi Amori a.", bookId = 4),
        Verse(book = "Nonm", chapter = 21, verseNumber = 30, text = "Men koulye a, se moun lavil Esbon yo ki pèdi nèt fwa sa a! Nou mete kou sou yo depi lavil Esbon rive Dibon! Nou devaste peyi a kite l' blanch jouk Nofak, toupre Medeba.", bookId = 4),
        Verse(book = "Nonm", chapter = 21, verseNumber = 31, text = "Se konsa, moun pèp Izrayèl yo vin rete nan peyi Amori a.", bookId = 4),
        Verse(book = "Nonm", chapter = 21, verseNumber = 32, text = "Moyiz menm voye kèk moun wè ki jan sa ye nan lavil Jazè. Apre sa, moun Izrayèl yo mache pran lavil la ak lòt ti bouk ki nan vwazinaj li. Kote yo pase, yo mete moun Amori yo deyò lakay yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 21, verseNumber = 33, text = "Apre sa, moun pèp Izrayèl yo tounen sou wout yo, yo pran chemen ki mennen lavil Bazan. Epi Og, wa lavil Bazan an, leve tout pèp l' a, li vin kontre ak yo pou l' atake yo bò Edreyi.", bookId = 4),
        Verse(book = "Nonm", chapter = 21, verseNumber = 34, text = "Seyè a di Moyiz konsa: -Ou pa bezwen pè msye! M'ap fè nou kraze l' anba pye nou, li menm ansanm ak tout pèp l' a. M'ap fè nou pran peyi l' la pou nou. Nou pral fè l' pase sa nou te fè Siyon, wa peyi Amori ki te rete Esbon an, pase.", bookId = 4),
        Verse(book = "Nonm", chapter = 21, verseNumber = 35, text = "Se konsa, moun pèp Izrayèl yo touye Og, ansanm ak pitit gason l' yo ak tout pèp l' a. Yo pa kite yonn chape, yo pran tout peyi a pou yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 22, verseNumber = 1, text = "Moun pèp Izrayèl yo kite kote yo te ye a, y' al moute kan yo nan plenn Moab, ki lòt bò larivyè Jouden, anfas lavil Jeriko.", bookId = 4),
        Verse(book = "Nonm", chapter = 22, verseNumber = 2, text = "Lè wa Balak, pitit Zipò, wè tou sa moun pèp Izrayèl yo te fè moun Amori yo,", bookId = 4),
        Verse(book = "Nonm", chapter = 22, verseNumber = 3, text = "li menm ak tout moun pèp Moab yo te vin pè pèp Izrayèl la kou chat, paske moun pèp Izrayèl yo te anpil anpil.", bookId = 4),
        Verse(book = "Nonm", chapter = 22, verseNumber = 4, text = "Moun Moab yo pale ak chèf fanmi moun Madyan yo, yo di yo: -Bann moun sa yo pral manje tou sa ki alantou nou, tankou bèf k'ap manje zèb nan savann. Lè sa a, se Balak, pitit Zipò, ki te wa peyi Moab.", bookId = 4),
        Verse(book = "Nonm", chapter = 22, verseNumber = 5, text = "Li voye kèk mesaje bò kote Balaram, pitit Beyò a, ki te rete lavil Petò, bò gwo larivyè Lefrat la nan peyi moun Amaf yo. Men komisyon li te voye ba li: -Men, gen yon pèp la a ki soti nan peyi Lejip. Y'ap mache pran tout peyi pou yo. Koulye a, men yo kanpe toupre lòt bò fwontyè peyi mwen an.", bookId = 4),
        Verse(book = "Nonm", chapter = 22, verseNumber = 6, text = "Tanpri, vini non. Vin madichonnen yo pou mwen, paske yo pi fò pase m'. Lè sa a, ou pa janm konnen, m'a ka bat yo, m'a mete yo deyò nan peyi a. Paske mwen konnen lè ou beni yon moun, li beni nèt, Konsa tou, lè ou bay yon moun madichon, li madichonnen nèt.", bookId = 4),
        Verse(book = "Nonm", chapter = 22, verseNumber = 7, text = "Se konsa, chèf fanmi moun Moab yo ak chèf fanmi moun Madyan yo pati. Yo te pote ak yo sa ki te nesesè pou peye konsiltasyon an. Yo rive kay Balaram, epi yo ba li komisyon Balak la.", bookId = 4),
        Verse(book = "Nonm", chapter = 22, verseNumber = 8, text = "Balaram di yo: -Bon. Nou mèt pase nwit la isit la. Denmen m'a ban nou repons mwen dapre sa Seyè a va fè m' konnen. Se konsa, chèf fanmi moun Moab yo rete lakay Balaram.", bookId = 4),
        Verse(book = "Nonm", chapter = 22, verseNumber = 9, text = "Bondye vin bò kote Balaram, li di l' konsa: -Ki moun sa yo ki lakay ou a?", bookId = 4),
        Verse(book = "Nonm", chapter = 22, verseNumber = 10, text = "Balaram reponn: -Se Balak, pitit Zipò a, wa peyi Moab, ki voye yo vin di m':", bookId = 4),
        Verse(book = "Nonm", chapter = 22, verseNumber = 11, text = "Men gen yon pèp ki soti nan peyi Lejip k'ap mache pran tout peyi pou yo. Tanpri, vini ba yo madichon pou li. Konsa, l'a ka rive bat yo, l'a ka mete yo deyò nan peyi a.", bookId = 4),
        Verse(book = "Nonm", chapter = 22, verseNumber = 12, text = "Men Bondye di Balaram konsa: -Piga ou ale ak mesye sa yo, tande. Piga ou bay pèp Izrayèl la madichon, paske se mwen ki beni yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 22, verseNumber = 13, text = "Nan denmen maten, byen bonè, Balaram leve, l' al jwenn moun Balak te voye yo, li di yo: -Tounen lakay nou, paske Seyè a pa vle kite m' ale ak nou.", bookId = 4),
        Verse(book = "Nonm", chapter = 22, verseNumber = 14, text = "Se konsa chèf moun Moab yo leve, yo tounen bò kote Balak, yo di l' konsa: -Balaram refize vini avèk nou!", bookId = 4),
        Verse(book = "Nonm", chapter = 22, verseNumber = 15, text = "Lè sa a, Balak voye yon bann lòt chèf kote Balaram ankò. Men, fwa sa a chèf sa yo te pi plis, epi yo te pi grannèg pase premye yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 22, verseNumber = 16, text = "Mesye yo leve vre, y' ale bò kote Balaram, epi yo di l' konsa: -Men sa Balak, pitit Zipò a, voye di ou: Tanpri, pa kite anyen anpeche ou vin bò kote m'.", bookId = 4),
        Verse(book = "Nonm", chapter = 22, verseNumber = 17, text = "Gade: m'ap kite anpil bèl bagay pou ou. M'ap fè tou sa ou di m' fè. Tanpri, vini non! Vin bay pèp sa a madichon pou mwen.", bookId = 4),
        Verse(book = "Nonm", chapter = 22, verseNumber = 18, text = "Men, Balaram reponn moun Balak yo, li di yo: -Balak te mèt ban mwen kay li plen ajan ak lò, mwen p'ap fè anyen, ni lou ni lejè, ki pou fè m' dezobeyi lòd Seyè a, Bondye mwen an.", bookId = 4),
        Verse(book = "Nonm", chapter = 22, verseNumber = 19, text = "Yon sèl bagay, nou mèt dòmi isit la aswè a, pou m' ka konnen si Seyè a gen lòt bagay li vle di m' ankò.", bookId = 4),
        Verse(book = "Nonm", chapter = 22, verseNumber = 20, text = "Jou lannwit sa a, Bondye vin jwenn Balaram, epi li di l' konsa: -Si se chache mesye sa yo vin chache ou, ou mèt leve ale ak yo. Men, se sa mwen di ou fè ase pou ou fè.", bookId = 4),
        Verse(book = "Nonm", chapter = 22, verseNumber = 21, text = "Nan denmen maten, byen bonè, Balaram leve, li sele manman bourik l' a, epi li pati avèk chèf moun Moab yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 22, verseNumber = 22, text = "Pati Balaram pati, Bondye fache sou li. Se konsa, antan Balaram taprale sou manman bourik l' a, avèk de domestik ki t'ap mache avè l' yo, zanj Seyè a vin kanpe nan mitan wout la pou bare chemen l'.", bookId = 4),
        Verse(book = "Nonm", chapter = 22, verseNumber = 23, text = "Lè manman bourik la wè zanj Seyè a ki te kanpe nan mitan wout la avèk nepe li nan men l', bourik la chankre, li lage kò l' nan jaden. Balaram bat bourik la jouk li fè l' tounen sou wout la.", bookId = 4),
        Verse(book = "Nonm", chapter = 22, verseNumber = 24, text = "Men zanj Seyè a vin kanpe yon kote wout la te jennen, kote wout la pase nan mitan de jaden rezen avèk yon miray kloti sou chak bò.", bookId = 4),
        Verse(book = "Nonm", chapter = 22, verseNumber = 25, text = "Lè manman bourik la wè zanj Seyè a, l' al fwote kò l' sou miray la. Se konsa li kwense pye Balaram sou miray la. Balaram tanmen bat l' ankò.", bookId = 4),
        Verse(book = "Nonm", chapter = 22, verseNumber = 26, text = "Zanj Seyè a fè yon ti mache ankò, epi l' al kanpe yon kote wout la te pi jennen toujou, kifè pa t' gen yon ti espas menm pou pase ni adwat, ni agoch.", bookId = 4),
        Verse(book = "Nonm", chapter = 22, verseNumber = 27, text = "Lè bourik la wè zanj Seyè a, fwa sa a, li kouche ak tout Balaram sou li. Balaram fache, li tonbe bat bourik la ak gwo baton ki te nan men l' lan.", bookId = 4),
        Verse(book = "Nonm", chapter = 22, verseNumber = 28, text = "Lè sa a, Seyè a bay bourik la lapawòl. Bourik la di Balaram konsa: -Kisa m' fè ou? Poukisa an twa fwa ou bat mwen konsa:", bookId = 4),
        Verse(book = "Nonm", chapter = 22, verseNumber = 29, text = "Balaram di bourik la konsa: -Se paske w'ap pase m' nan jwèt! Pa pito se te yon manchèt osinon yon nepe ki te nan men m', ou ta gen tan konnen. Ou mouri lontan!", bookId = 4),
        Verse(book = "Nonm", chapter = 22, verseNumber = 30, text = "Bourik la reponn, li di l': -Eske se pa bourik ou mwen ye! Se pa sou mwen ou toujou moute depi tout tan jouk jòdi a? Ou janm wè mwen konn aji konsa avè ou? Balaram reponn: -Non!", bookId = 4),
        Verse(book = "Nonm", chapter = 22, verseNumber = 31, text = "Lè sa a, Seyè a louvri je Balaram, li fè l' wè zanj lan ki te kanpe nan mitan wout la avèk nepe l' nan men l'. Balaram lage kò l' fas atè.", bookId = 4),
        Verse(book = "Nonm", chapter = 22, verseNumber = 32, text = "Zanj lan di l' konsa: -Poukisa an twa fwa ou bat bourik la konsa? Se mwen menm ki vin bare chemen ou, paske ou pa t' dwe al fè vwayaj sa a.", bookId = 4),
        Verse(book = "Nonm", chapter = 22, verseNumber = 33, text = "Men bourik ou a te wè m'. Se poutèt sa, an twa fwa, li te vle chankre. Men, ou mèt di l' mèsi, paske si li pa t' fè sa, mwen ta gen tan touye ou. Li menm, mwen pa t'ap fè l' anyen.", bookId = 4),
        Verse(book = "Nonm", chapter = 22, verseNumber = 34, text = "Balaram reponn: -Sa m' fè a pa bon, vre! Sèlman, mwen pa t' konnen se ou menm ki te bare wout la devan m'. Men si koulye a ou pa vle m' al pi lwen, m'ap tou tounen lakay mwen.", bookId = 4),
        Verse(book = "Nonm", chapter = 22, verseNumber = 35, text = "Men, zanj Bondye a di li: -Ou mèt ale ak mesye yo. Sèlman, pa di anyen pase sa m'a di ou di. Se konsa Balaram ale ak chèf Balak te voye bò kote l' yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 22, verseNumber = 36, text = "Lè Balak vin konnen Balaram t'ap vini, li pati, l' al kontre l' jouk Amoab, yon lavil sou fwontyè bò larivyè Anon an.", bookId = 4),
        Verse(book = "Nonm", chapter = 22, verseNumber = 37, text = "Balak di Balaram konsa: -Ki jan fè mwen voye moun al chache ou, ou pa vin jwenn mwen? Se konprann ou konprann mwen pa ta ka resevwa ou jan ou merite l' la?", bookId = 4),
        Verse(book = "Nonm", chapter = 22, verseNumber = 38, text = "Balaram reponn: -Apa mwen vini fwa sa a! Men mwen tou pale ou, se pawòl Bondye va mete nan bouch mwen ase m'ap di.", bookId = 4),
        Verse(book = "Nonm", chapter = 22, verseNumber = 39, text = "Se konsa, Balaram ale avèk Balak jouk yo rive lavil Kiriyat-Ousòt.", bookId = 4),
        Verse(book = "Nonm", chapter = 22, verseNumber = 40, text = "Rive la, Balak fè touye bèf ak mouton, epi li voye kèk moso vyann bay Balaram ansanm ak chèf ki te avè l' yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 22, verseNumber = 41, text = "Nan denmen maten, Balak pran Balaram, yo moute sou mòn Bamòtbaal. Antan yo la, yo te kapab wè yon pòsyon nan moun Izrayèl yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 23, verseNumber = 1, text = "Balaram di Balak konsa: -Bati sèt lotèl isit la pou mwen. Apre sa, ban mwen sèt towo bèf ak sèt belye mouton.", bookId = 4),
        Verse(book = "Nonm", chapter = 23, verseNumber = 2, text = "Balak fè sa Balaram te di l' fè a. Lèfini, Balaram ak Balak touye yon towo bèf ak yon belye mouton sou chak lotèl.", bookId = 4),
        Verse(book = "Nonm", chapter = 23, verseNumber = 3, text = "Apre sa, Balaram di Balak konsa: -Rete kanpe bò kote ofrann ou mete ap boule la a. Mwen menm, mwen pral wè si Seyè a p'ap vin jwenn mwen. Apre sa, m'a fè ou konnen sa l'a fè m' wè a. Epi l' ale sou tèt yon ti mòn ki pa t' gen yon ti pyebwa sou li.", bookId = 4),
        Verse(book = "Nonm", chapter = 23, verseNumber = 4, text = "Epi Bondye vin jwenn li la. Balaram di l' konsa: -Mwen te fè bati sèt lotèl pou ou, epi mwen te touye yon towo bèf ak yon belye mouton sou chak lotèl pou ou.", bookId = 4),
        Verse(book = "Nonm", chapter = 23, verseNumber = 5, text = "Seyè a pale ak Balaram byen pale. Apre sa, li di l': -Tounen bò kote Balak. W'a pale avè l' jan mwen di ou la.", bookId = 4),
        Verse(book = "Nonm", chapter = 23, verseNumber = 6, text = "Se konsa, Balaram tounen bò kote Balak. Li jwenn li kanpe bò ofrann boule yo ansanm ak lòt chèf moun Moab yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 23, verseNumber = 7, text = "Lèfini, li pran chante chante sa a: -Balak fè m' kite peyi m', peyi Aram. Wa Moab la fè m' desann soti nan mòn bò solèy leve yo. Li di m': Vini non! Vin bay moun Jakòb yo madichon. Vini non! Vin kraponnen moun Izrayèl yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 23, verseNumber = 8, text = "Men ki jan ou ta vle pou m' madichonnen moun Bondye pa madichonnen? Ki jan ou ta vle pou m' kraponnen moun Bondye pa kraponnen?", bookId = 4),
        Verse(book = "Nonm", chapter = 23, verseNumber = 9, text = "Mwen kanpe sou tèt gwo wòch yo, mwen wè yo. Antan mwen sou ti mòn yo, m'ap gade anba: Wi, se yon pèp k'ap viv yon jan apa pou kont li. Se yon pèp ki pa menm ak lòt pèp yo!", bookId = 4),
        Verse(book = "Nonm", chapter = 23, verseNumber = 10, text = "Ki moun ki ka konte valè pitit Jakòb genyen? Yo anpil tankou grenn pousyè ki sou latè. Ki moun ki ka konte valè pitit Izrayèl yo ye? Mwen ta renmen mouri tankou moun ki mache dwat devan Bondye. Mwen ta renmen fini tankou yo ak kè poze.", bookId = 4),
        Verse(book = "Nonm", chapter = 23, verseNumber = 11, text = "Balak di Balaram: -Kisa w'ap fè m' konsa? Mwen mennen ou isit la pou bay lènmi m' yo madichon, epi se beni mwen wè w'ap beni yo!", bookId = 4),
        Verse(book = "Nonm", chapter = 23, verseNumber = 12, text = "Balaram reponn: -Mwen te tou di ou se sèlman pawòl Seyè a va mete nan bouch mwen m'ap di.", bookId = 4),
        Verse(book = "Nonm", chapter = 23, verseNumber = 13, text = "Balak di Balaram konsa: -Ann al avè m' yon lòt kote. Antan ou va la, ou p'ap wè tout pèp Izrayèl la, men sèlman yon pòsyon ladan l'. W'a rete kanpe la, epi w'a bay ti sa w'a wè a madichon pou mwen.", bookId = 4),
        Verse(book = "Nonm", chapter = 23, verseNumber = 14, text = "Balak pran Balaram, li mennen l' nan jaden Santinèl yo, sou tèt mòn Pisga. Lè l' rive la, li bati sèt lotèl. Epi li touye yon jenn ti towo bèf ak yon belye mouton sou chak lotèl pou Bondye.", bookId = 4),
        Verse(book = "Nonm", chapter = 23, verseNumber = 15, text = "Balaram di Balak konsa: -Rete kanpe bò kote ofrann ou mete boule sou lotèl yo. Mwen menm, mwen pral kontre ak Bondye pi devan.", bookId = 4),
        Verse(book = "Nonm", chapter = 23, verseNumber = 16, text = "Seyè a vin jwenn Balaram, li pale ak Balaram byen pale ankò, epi li di l': -Tounen al jwenn Balak. W'a pale avè l' jan mwen di ou la.", bookId = 4),
        Verse(book = "Nonm", chapter = 23, verseNumber = 17, text = "Se konsa Balaram tounen bò kote Balak, li jwenn li kanpe bò ofrann boule yo ansanm ak tout chèf moun Moab yo. Epi Balak mande l': -Kisa Seyè a di konsa?", bookId = 4),
        Verse(book = "Nonm", chapter = 23, verseNumber = 18, text = "Epi Balaram pran chante chante sa a: -Souke kò ou, Balak! Vin tande! Pare zòrèy ou, pitit Zipò!", bookId = 4),
        Verse(book = "Nonm", chapter = 23, verseNumber = 19, text = "Bondye pa tankou moun k'ap bay manti. Non! Li pa tankou moun k'ap chanje lide yo pou ti krik ti krak! Depi li pwomèt yon bagay, l'ap fè l'. Depi li pale, fòk sa li di a rive vre!", bookId = 4),
        Verse(book = "Nonm", chapter = 23, verseNumber = 20, text = "Yo ban m' lòd pou m' beni pèp Izrayèl la! Lè Bondye fin bay benediksyon l', nanpwen anyen mwen ka fè ankò.", bookId = 4),
        Verse(book = "Nonm", chapter = 23, verseNumber = 21, text = "Mwen pa wè okenn malè pou moun Jakòb yo. Ni mwen pa wè okenn traka pou moun Izrayèl yo. Seyè a, Bondye yo a, l'a avèk yo. Yo tout kontan, y'ap fè konnen se li ki wa yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 23, verseNumber = 22, text = "Paske, lè Bondye t'ap fè yo soti kite peyi Lejip la, li te ba yo fòs pou yo te goumen tankou towo mawon.", bookId = 4),
        Verse(book = "Nonm", chapter = 23, verseNumber = 23, text = "Pa gen wanga ki ka pran sou moun Jakòb yo. Pa gen maji ki ka fè moun Izrayèl yo anyen. Lè lè a va rive, y'a di moun Jakòb yo ak moun Izrayèl yo: Gade sa Seyè a fè pou nou!", bookId = 4),
        Verse(book = "Nonm", chapter = 23, verseNumber = 24, text = "Gade! Pèp Izrayèl la kanpe tankou yon manman lyon. Yo leve kanpe tankou yon mal lyon. Yo p'ap chita toutotan yo pa fin devore moun ki tonbe anba men yo, toutotan yo pa fin bwè san moun yo touye yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 23, verseNumber = 25, text = "Lè sa a, Balak di Balaram konsa: -Menm jan ou pa vle ba yo madichon an, ou pa t' dwe asepte ba yo benediksyon non plis.", bookId = 4),
        Verse(book = "Nonm", chapter = 23, verseNumber = 26, text = "Men, Balaram reponn Balak, li di l': -Mwen te tou pale ou wi. Mwen te di ou: Tou sa Seyè a va di m' fè, se sa m'ap fè.", bookId = 4),
        Verse(book = "Nonm", chapter = 23, verseNumber = 27, text = "Balak di Balaram konsa: -Ann al non! Mwen pral mennen ou yon lòt kote. Ou pa janm konnen, antan ou la a, Bondye ka kite ou bay pèp la madichon pou mwen.", bookId = 4),
        Verse(book = "Nonm", chapter = 23, verseNumber = 28, text = "Balak mennen Balaram sou tèt mòn Peyò a. Antan yo la, yo dekouvri tout dezè a nan pye yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 23, verseNumber = 29, text = "Balaram di Balak konsa: -Bati sèt lotèl pou mwen isit la. Lèfini, fè m' jwenn sèt jenn ti towo bèf ak sèt belye mouton.", bookId = 4),
        Verse(book = "Nonm", chapter = 23, verseNumber = 30, text = "Balak fè tou sa Balaram te di l' fè a, epi li touye yon ti towo bèf ak yon belye mouton sou chak lotèl pou Bondye.", bookId = 4),
        Verse(book = "Nonm", chapter = 24, verseNumber = 1, text = "Lè sa a, Balaram te fin konprann se yon sèl bagay Seyè a te vle, se beni pou li beni pèp Izrayèl la. Se poutèt sa, li pa fè tankou lòt fwa yo. Li pa al chache konnen sa Seyè a te vle fè l' konnen an. Men, li bay fas li sou dezè a.", bookId = 4),
        Verse(book = "Nonm", chapter = 24, verseNumber = 2, text = "Li leve je l', epi li wè moun pèp Izrayèl yo ak tant yo byen ranje, chak branch fanmi apa. Lespri Bondye desann sou li.", bookId = 4),
        Verse(book = "Nonm", chapter = 24, verseNumber = 3, text = "Epi li pran chante chante sa a: -Men sa mwen menm, Balaram, pitit Bèyò, m'ap di: Men pawòl k'ap soti nan bouch moun Bondye te louvri je a,", bookId = 4),
        Verse(book = "Nonm", chapter = 24, verseNumber = 4, text = "pawòl moun ki te tande sa Bondye ap di a, pawòl moun ki te wè sa Bondye ki gen tout pouvwa a fè l' wè a. Lè sa a, li te tonbe fas atè, men Bondye te louvri je l'.", bookId = 4),
        Verse(book = "Nonm", chapter = 24, verseNumber = 5, text = "Ala bèl tant nou yo bèl, moun Jakòb yo! Ala bèl kote nou rete a bèl, moun Izrayèl yo!", bookId = 4),
        Verse(book = "Nonm", chapter = 24, verseNumber = 6, text = "Yo laji kò yo tankou dlo larivyè k'ap desann. Yo tankou jaden k'ap pouse sou bò larivyè, tankou yon pye lalwa Bondye li menm ta plante, tankou yon pye sèd k'ap grandi bò kannal dlo.", bookId = 4),
        Verse(book = "Nonm", chapter = 24, verseNumber = 7, text = "Lame pèp Izrayèl la ap fè nasyon yo tranble. Pèp Izrayèl la ap donminen sou anpil lòt pèp. Wa li yo ap pi fò pase wa Agag, Y'ap gouvènen sou anpil nasyon.", bookId = 4),
        Verse(book = "Nonm", chapter = 24, verseNumber = 8, text = "Bondye te mennen yo soti kite peyi Lejip. Li te goumen pou yo tankou yon towo mawon. L'ap manje tout nasyon ki pa vle wè yo. L'ap kraze tout zo yo an miyèt moso. L'ap pèse yo pak an pak ak flèch li yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 24, verseNumber = 9, text = "Pèp Izrayèl la chita atè a, l' ap pran repo, tankou yon lyon, tankou yon fenmèl lyon. Lè l'ap dòmi, ki moun ki ka penmèt yo leve l'? benediksyon pou tout moun ki mande benediksyon pou pèp Izrayèl la! Madichon pou tout moun k'ap mande madichon pou pèp Izrayèl la!", bookId = 4),
        Verse(book = "Nonm", chapter = 24, verseNumber = 10, text = "Lè sa a, Balak fè yon sèl move sou Balaram, li frape pye l' atè, li di konsa: -Mwen te rele ou isit la pou bay lènmi m' yo madichon pou mwen. Men, gade sa ou fè. Se beni ou beni yo pito. Sa fè twa fwa ou fè sa.", bookId = 4),
        Verse(book = "Nonm", chapter = 24, verseNumber = 11, text = "Koulye a, pito ou kouri al lakay ou, tande. Mwen te pwomèt pou m' te fè anpil bèl bagay pou ou. Men, gade sa Seyè a fè ou: ou pèdi tout.", bookId = 4),
        Verse(book = "Nonm", chapter = 24, verseNumber = 12, text = "Balaram reponn, li di l' konsa: -Mwen te tou pale moun ou te voye chache m' yo. Mwen te di yo:", bookId = 4),
        Verse(book = "Nonm", chapter = 24, verseNumber = 13, text = "Balak te mèt ban mwen kay li plen ajan ak lò, mwen p'ap fè anyen poutèt pa m' ki pou fè m' dezobeyi lòd Seyè a, ni an byen ni an mal. Sa Seyè a di m' di, se sa ase m'ap di.", bookId = 4),
        Verse(book = "Nonm", chapter = 24, verseNumber = 14, text = "Balaram di Balak ankò: -Wi, koulye a mwen pral lakay mwen. Men, anvan m' ale, vini m' di ou kisa pèp Izrayèl la pral fè pèp ou a nan jou k'ap vini yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 24, verseNumber = 15, text = "Epi Balaram pran chante chante sa a: -Men sa mwen menm, Balaram, pitit Bèyò, m'ap di. Men pawòl k'ap soti nan bouch moun Bondye te louvri je a,", bookId = 4),
        Verse(book = "Nonm", chapter = 24, verseNumber = 16, text = "moun ki ka tande sa Bondye ap di a, moun ki gen konesans ki soti nan men Bondye ki anwo nan syèl la, moun ki te wè sa Bondye ki gen tout pouvwa a fè l' wè a. Li te tonbe fas atè, men Bondye te louvri je l'.", bookId = 4),
        Verse(book = "Nonm", chapter = 24, verseNumber = 17, text = "Mwen wè sa ki gen pou rive pèp Izrayèl la. M'ap gade sa ki pral rive l' pita. Tankou yon gwo zetwal, mwen wè yon chèf k'ap soti nan fanmi Jakòb la. Yon gwo wa pral leve nan mitan pèp Izrayèl la. L'ap kraze chèf Moab yo, l'ap detwi tout pitit Sèt yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 24, verseNumber = 18, text = "Y'a deposede moun Edon yo. Y'a pran peyi Seyi a nan men lènmi l' yo. Men, yo menm, moun Izrayèl yo, y'ap fè mèvèy nan lagè.", bookId = 4),
        Verse(book = "Nonm", chapter = 24, verseNumber = 19, text = "Yon gwo chèf pral soti nan pèp Izrayèl la. L'a gouvènen sou yo tout. L'a touye rès moun ki te rete nan lavil yo apre batay la.", bookId = 4),
        Verse(book = "Nonm", chapter = 24, verseNumber = 20, text = "Apre sa, Balaam wè moun Amalèk yo nan vizyon l' lan. Li bay mesaj sa a, li di konsa: -Moun Amalèk yo, se yon nasyon ki fò anpil. Men, bout pou bout, yo gen pou yo disparèt nèt.", bookId = 4),
        Verse(book = "Nonm", chapter = 24, verseNumber = 21, text = "Apre sa, Balaram wè moun Kayen yo nan vizyon l' lan. Li bay mesaj sa a, li di konsa: -Kote ou rete a ou byen pwoteje. Ou ta di yon nich poze sou tèt yon gwo falèz.", bookId = 4),
        Verse(book = "Nonm", chapter = 24, verseNumber = 22, text = "Men, wè pa wè, moun Kayen yo la pou yo fini mal. Peyi Lasiri va depòte yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 24, verseNumber = 23, text = "Balaram pran pale ankò. Li bay mesaj sa a, li di ankò: -Kilès ki va la lè Bondye va fè tou sa?", bookId = 4),
        Verse(book = "Nonm", chapter = 24, verseNumber = 24, text = "Lè sa a, moun ap soti lavil Kitim nan bato vin anvayi peyi a. Yo pral kraze peyi Lasiri ak lavil Babilòn. Men, ata moun Kitim yo gen pou disparèt nèt tou.", bookId = 4),
        Verse(book = "Nonm", chapter = 24, verseNumber = 25, text = "Apre sa, Balaram leve, li tounen tounen l' lakay li. Epi Balak al fè wout li.", bookId = 4)
    )

    private val part3 = listOf(
        Verse(book = "Nonm", chapter = 25, verseNumber = 1, text = "Pèp Izrayèl la vin moute tant yo nan Fon Zakasya yo. Lè sa a, mesye yo konmanse lage kò yo nan vagabondaj ak fanm peyi Moab yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 25, verseNumber = 2, text = "Medam peyi Moab yo menm envite yo nan seremoni ofrann bèt yo t'ap touye pou bondye pa yo. Moun pèp Izrayèl yo ale vre, yo manje epi yo sèvi bondye moun Moab yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 25, verseNumber = 3, text = "Se konsa pèp Izrayèl la pran sèvi Baal-Peyò. Sa te fè Seyè a ankòlè anpil sou moun pèp Izrayèl yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 25, verseNumber = 4, text = "Seyè a di Moyiz konsa: -Pran tout chèf pèp la, pann yo gwo midi devan mwen. Konsa, mwen p'ap ankòlè sou yo ankò.", bookId = 4),
        Verse(book = "Nonm", chapter = 25, verseNumber = 5, text = "Moyiz di chèf ki te reskonsab pèp la: -Se pou nou chak nou touye tout gason nan moun nou yo ki te al sèvi Baal-Peyò.", bookId = 4),
        Verse(book = "Nonm", chapter = 25, verseNumber = 6, text = "Lè sa a, antan tout moun yo t'ap kriye sou devan pòt Tant Randevou a, yonn nan gason pèp Izrayèl la ale, li mennen yon fanm peyi Madyan lakay li, devan Moyiz ak tout moun pèp Izrayèl la.", bookId = 4),
        Verse(book = "Nonm", chapter = 25, verseNumber = 7, text = "Lè Fineas, pitit gason Eleaza a, pitit pitit Arawon, prèt la, wè sa, li leve, li kite moun yo kote yo te reyini an, li pase men l', li pran yon frenn.", bookId = 4),
        Verse(book = "Nonm", chapter = 25, verseNumber = 8, text = "Li swiv nonm lan ak fanm lan anba tant lan, epi li pèse tou de, ni nonm lan ni fanm lan, ak frenn lan anba ti vant yo. Lamenm, epidemi ki t'ap ravaje pèp la sispann.", bookId = 4),
        Verse(book = "Nonm", chapter = 25, verseNumber = 9, text = "Te gen vennkatmil (24.000) moun ki te gen tan mouri nan epidemi an.", bookId = 4),
        Verse(book = "Nonm", chapter = 25, verseNumber = 10, text = "Seyè a pale ak Moyiz, li di l' konsa:", bookId = 4),
        Verse(book = "Nonm", chapter = 25, verseNumber = 11, text = "-Se Fineas, pitit gason Eleaza a, pitit pitit gason Arawon prèt la, ki te fè m' sispann ankòlè sou pèp la. Paske nan tout moun sa yo, se li menm ki pa t' ka sipòte wè yon moun nan pèp Izrayèl la kite m' pou l' al sèvi yon lòt bondye. Se poutèt sa, atout mwen t'ap fè jalouzi a, mwen pa fin touye tout pèp la nèt.", bookId = 4),
        Verse(book = "Nonm", chapter = 25, verseNumber = 12, text = "Men sa pou ou di Fineas pou mwen: m'ap siyen yon kontra avè l' ki pou ba li kè poze.", bookId = 4),
        Verse(book = "Nonm", chapter = 25, verseNumber = 13, text = "M'ap mete li, li menm ak tout ras fanmi l' apre li, pou yo sèvi m' prèt pou tout tan. Paske li te fè m' wè jan li pa t' tolere moun sèvi lòt bondye pase mwen. Se konsa li fè m' padonnen sa pèp la te fè ki mal la.", bookId = 4),
        Verse(book = "Nonm", chapter = 25, verseNumber = 14, text = "Nonm pèp Izrayèl ki te mouri ansanm ak fanm peyi Madyan an te rele Zimri. Se te pitit gason Salou, chèf nan branch fanmi Simeyon an.", bookId = 4),
        Verse(book = "Nonm", chapter = 25, verseNumber = 15, text = "Fanm peyi Madyan yo te touye a te rele Kozbi. Se te pitit fi Sou, ki li menm te chèf yon branch nan fanmi moun Madyan yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 25, verseNumber = 16, text = "Lè sa a, Seyè a pale ak Moyiz, li di l':", bookId = 4),
        Verse(book = "Nonm", chapter = 25, verseNumber = 17, text = "-Al atake moun Madyan yo. Bat yo byen bay.", bookId = 4),
        Verse(book = "Nonm", chapter = 25, verseNumber = 18, text = "Paske se yo menm ki te atake nou anvan ak malefis yo te voye sou nou nan zafè Peyò a, ak nan zafè Kozbi a, pitit fi chèf peyi Madyan an, moun menm ras ak yo a, fanm yo te touye lè epidemi te tonbe sou nou nan peyi Peyò a.", bookId = 4),
        Verse(book = "Nonm", chapter = 26, verseNumber = 1, text = "Apre epidemi an, Seyè a pale ak Moyiz ansanm ak Eleaza, pitit gason Arawon, prèt la, li di yo konsa:", bookId = 4),
        Verse(book = "Nonm", chapter = 26, verseNumber = 2, text = "-Nou pral fè resansman tout moun pèp Izrayèl la, tou sa ki gen ventan osinon ki pi gran, chak fanmi apa, dapre zansèt yo. W'a pran non tout gason nan pèp Izrayèl la ki bon pou fè lagè.", bookId = 4),
        Verse(book = "Nonm", chapter = 26, verseNumber = 3, text = "Se konsa, antan pèp la nan plenn peyi Moab yo, toupre larivyè Jouden, anfas lavil Jeriko, Moyiz ak Eleaza, prèt la, ba yo lòd", bookId = 4),
        Verse(book = "Nonm", chapter = 26, verseNumber = 4, text = "pou tout gason ki gen ventan osinon ki pi gran vin bay non yo, dapre lòd Seyè a te bay Moyiz. Men moun pèp Izrayèl la ki te soti kite peyi Lejip:", bookId = 4),
        Verse(book = "Nonm", chapter = 26, verseNumber = 5, text = "Nan branch fanmi Woubenn, premye pitit gason Izrayèl la, te gen fanmi moun Enòk yo, fanmi moun Palou yo,", bookId = 4),
        Verse(book = "Nonm", chapter = 26, verseNumber = 6, text = "fanmi moun Ezwon yo ak fanmi moun Kami yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 26, verseNumber = 7, text = "Se tout moun sa yo ki nan branch fanmi Woubenn lan. Lè resansman an, yo te jwenn karanntwamil sètsantrant (43.730) gason nan branch fanmi sa a.", bookId = 4),
        Verse(book = "Nonm", chapter = 26, verseNumber = 8, text = "Palou te papa Eliyab.", bookId = 4),
        Verse(book = "Nonm", chapter = 26, verseNumber = 9, text = "Eliyab te papa Nemwèl, Datan ak Abiram. Se Datan ak Abiram sa yo, de nèg moun yo te konsidere anpil, ki te revòlte kont Moyiz ak Arawon. Yo te fè pati bann moun Kore yo ki te revòlte kont Seyè a.", bookId = 4),
        Verse(book = "Nonm", chapter = 26, verseNumber = 10, text = "Lè sa a, tè a te louvri, li vale yo, epi yo mouri ansanm ak Kore ak tout bann moun li yo. Jou sa a, dife te boule desansenkant (250) moun. Se te yon avètisman pou pèp la.", bookId = 4),
        Verse(book = "Nonm", chapter = 26, verseNumber = 11, text = "Men, pitit gason Kore yo pa t' mouri lè sa a.", bookId = 4),
        Verse(book = "Nonm", chapter = 26, verseNumber = 12, text = "Men pitit gason Simeyon yo ak tout kòt fanmi yo. Te gen fanmi moun Nemwèl yo, fanmi moun Yamen yo, fanmi moun Yakim yo,", bookId = 4),
        Verse(book = "Nonm", chapter = 26, verseNumber = 13, text = "fanmi moun Zera yo ak fanmi moun Sayil yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 26, verseNumber = 14, text = "Se tout moun sa yo ki nan branch fanmi Simeyon an. Lè resansman an, te gen venndemil desan (22.200) gason nan branch fanmi sa a.", bookId = 4),
        Verse(book = "Nonm", chapter = 26, verseNumber = 15, text = "Men pitit gason Gad yo ak tout kòt fanmi yo. Te gen fanmi moun Sefon yo, fanmi moun Agi yo, fanmi moun Chouni yo,", bookId = 4),
        Verse(book = "Nonm", chapter = 26, verseNumber = 16, text = "fanmi moun Ozni yo, fanmi moun Eri yo,", bookId = 4),
        Verse(book = "Nonm", chapter = 26, verseNumber = 17, text = "fanmi moun Awòd yo, fanmi moun Areli yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 26, verseNumber = 18, text = "Se tout moun sa yo ki nan branch fanmi Gad la. Lè resansman an, te gen karantmil senksan (40.500) gason nan branch fanmi sa a.", bookId = 4),
        Verse(book = "Nonm", chapter = 26, verseNumber = 19, text = "Men pitit gason Jida yo. Te gen Er ak Onan, men yo tou de mouri nan peyi Kanaran san kite pitit.", bookId = 4),
        Verse(book = "Nonm", chapter = 26, verseNumber = 20, text = "Apre yo, te gen Chela, Perèz ak Zirak, ki bay yo chak yon kòt fanmi.", bookId = 4),
        Verse(book = "Nonm", chapter = 26, verseNumber = 21, text = "Perèz te gen de pitit gason. Yo chak bay yon fanmi apa. Se te fanmi Eswon an ak fanmi Amoul lan.", bookId = 4),
        Verse(book = "Nonm", chapter = 26, verseNumber = 22, text = "Se tout moun sa yo ki nan branch fanmi Jida a. Lè resansman an, te gen swasannsèzmil senksan (76.500) gason nan branch fanmi sa a.", bookId = 4),
        Verse(book = "Nonm", chapter = 26, verseNumber = 23, text = "Men pitit gason Isaka yo ak tout kòt fanmi yo. Te gen fanmi moun Tola yo, fanmi moun Pouva yo,", bookId = 4),
        Verse(book = "Nonm", chapter = 26, verseNumber = 24, text = "fanmi moun Yachoub yo, fanmi moun Chimwon yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 26, verseNumber = 25, text = "Se tout moun sa yo ki te fè pati branch fanmi Isaka a. Lè resansman an, yo te jwenn swasannkatmil twasan (64.300) gason nan branch fanmi sa a.", bookId = 4),
        Verse(book = "Nonm", chapter = 26, verseNumber = 26, text = "Men pitit gason Zabilon yo ak tout kòt fanmi yo. Te gen fanmi moun Serèd yo, fanmi moun Elon yo, fanmi moun Yaleyèl yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 26, verseNumber = 27, text = "Se tout moun sa yo ki te fè pati branch fanmi Zabilon an. Lè resansman an, yo te jwenn swasantmil senksan (60.500) gason nan branch fanmi sa a.", bookId = 4),
        Verse(book = "Nonm", chapter = 26, verseNumber = 28, text = "Jozèf te gen de pitit gason: Manase ak Efrayim.", bookId = 4),
        Verse(book = "Nonm", chapter = 26, verseNumber = 29, text = "Men pitit gason Manase yo ak tout kòt fanmi yo: Te gen fanmi moun Maki yo. Maki te papa Galarad ki te bay fanmi moun Galarad yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 26, verseNumber = 30, text = "Galarad te fè sis pitit gason, yo chak bay yon branch fanmi. Te gen fanmi moun Yezè yo, fanmi moun Elèk yo,", bookId = 4),
        Verse(book = "Nonm", chapter = 26, verseNumber = 31, text = "fanmi moun Asriyèl yo, fanmi moun Sichèm yo,", bookId = 4),
        Verse(book = "Nonm", chapter = 26, verseNumber = 32, text = "fanmi moun Chemida yo, fanmi moun Efè yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 26, verseNumber = 33, text = "Men Zelofeyad, pitit gason Efè a, pa t' gen pitit gason. Se annik pitit fi li te genyen. Men non yo: Se te Mala, Noa, Ogla, Milka ak Tisa.", bookId = 4),
        Verse(book = "Nonm", chapter = 26, verseNumber = 34, text = "Se tout moun sa yo ki te fè pati branch fanmi Manase a. Lè resansman an, yo te jwenn senkanndemil sètsan (52.700) gason nan branch fanmi sa a.", bookId = 4),
        Verse(book = "Nonm", chapter = 26, verseNumber = 35, text = "Men pitit gason Efrayim yo ak tout kòt fanmi yo: Te gen fanmi moun Choutela yo, fanmi moun Bekè yo, fanmi moun Tayan yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 26, verseNumber = 36, text = "Choutela poutèt pa l' te gen yon pitit gason. Se te Eran ki bay yon fanmi apa.", bookId = 4),
        Verse(book = "Nonm", chapter = 26, verseNumber = 37, text = "Se tout moun sa yo ki te nan branch Efrayim lan. Lè resansman an, yo te jwenn tranndemil senksan (32.500) gason nan branch fanmi sa a.", bookId = 4),
        Verse(book = "Nonm", chapter = 26, verseNumber = 38, text = "Men pitit gason Benjamen yo ak tout kòt fanmi yo: Te gen fanmi moun Bela yo, fanmi moun Achbèl yo, fanmi moun Ayiram yo,", bookId = 4),
        Verse(book = "Nonm", chapter = 26, verseNumber = 39, text = "fanmi moun Choufan yo ak fanmi moun Oufam yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 26, verseNumber = 40, text = "Bela pou tèt pa l' te gen de pitit gason ki bay de lòt branch nan branch fanmi an ankò. Se te Ad ak Naaman.", bookId = 4),
        Verse(book = "Nonm", chapter = 26, verseNumber = 41, text = "Se tout moun sa yo ki te fè pati branch fanmi Benjamen an. Lè resansman an, yo te jwenn karannsenkmil sisan (45.600) gason nan branch fanmi sa a.", bookId = 4),
        Verse(book = "Nonm", chapter = 26, verseNumber = 42, text = "Men pitit gason Dann lan ak tout kòt fanmi l'. Se te fanmi moun Chwanm yo. Se tout moun sa yo ki te fè pati branch fanmi Dann lan.", bookId = 4),
        Verse(book = "Nonm", chapter = 26, verseNumber = 43, text = "Lè resansman an, yo te jwenn swasannkatmil katsan (64.400) gason nan branch fanmi sa a.", bookId = 4),
        Verse(book = "Nonm", chapter = 26, verseNumber = 44, text = "Men pitit gason Asè yo ak tout kòt fanmi yo. Te gen fanmi moun Imna yo, fanmi moun Ichvi yo ak fanmi moun Berya yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 26, verseNumber = 45, text = "Berya pou tèt pa l' te gen de pitit gason ki bay de lòt branch nan fanmi an ankò: Se te Ebè ak Malkiyèl.", bookId = 4),
        Verse(book = "Nonm", chapter = 26, verseNumber = 46, text = "Asè te gen yon pitit fi yo te rele Sera.", bookId = 4),
        Verse(book = "Nonm", chapter = 26, verseNumber = 47, text = "Se tout moun sa yo ki te fè pati branch fanmi Asè a. Lè resansman an, yo te jwenn senkanntwamil katsan (53.400) gason nan branch fanmi sa a.", bookId = 4),
        Verse(book = "Nonm", chapter = 26, verseNumber = 48, text = "Men pitit gason Neftali yo ak tout kòt fanmi yo. Te gen fanmi moun Yazeyèl yo, fanmi moun Gouni yo,", bookId = 4),
        Verse(book = "Nonm", chapter = 26, verseNumber = 49, text = "fanmi moun Yesè yo ak fanmi moun Chilèm yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 26, verseNumber = 50, text = "Se tout moun sa yo ki te fè pati branch fanmi Neftali a, fanmi pa fanmi. Lè resansman an, yo te konte karannsenkmil katsan (45.400) gason nan fanmi sa yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 26, verseNumber = 51, text = "Konsa, te gen antou sisan enmil sètsantrant (601.730) gason nan tout pèp Izrayèl la.", bookId = 4),
        Verse(book = "Nonm", chapter = 26, verseNumber = 52, text = "Seyè a pale ak Moyiz, li di l' konsa:", bookId = 4),
        Verse(book = "Nonm", chapter = 26, verseNumber = 53, text = "-Nou pral separe peyi a bay chak fanmi pòsyon pa yo dapre kantite gason yo jwenn nan chak.", bookId = 4),
        Verse(book = "Nonm", chapter = 26, verseNumber = 54, text = "Fanmi ki gen anpil gason va resevwa yon pi gwo pòsyon. Fanmi ki pa gen anpil gason va resevwa yon pi piti pòsyon. Chak fanmi va resevwa yon pòsyon dapre kantite gason ki gen ladan l'.", bookId = 4),
        Verse(book = "Nonm", chapter = 26, verseNumber = 55, text = "Men, pou fè separasyon peyi a, n'a tire osò: chak fanmi va resevwa pòsyon pa l' dapre kantite moun yo te konte nan chak.", bookId = 4),
        Verse(book = "Nonm", chapter = 26, verseNumber = 56, text = "Y'a tire osò pou yo separe bay chak branch fanmi pòsyon pa yo: yon gwo pòsyon pou chak branch fanmi ki anpil, yon ti pòsyon pou chak branch fanmi ki pa anpil.", bookId = 4),
        Verse(book = "Nonm", chapter = 26, verseNumber = 57, text = "Men, nan branch fanmi Levi a, men moun yo te konte dapre fanmi yo. Te gen fanmi Gèchon an, fanmi Keyat la ak fanmi Merari a.", bookId = 4),
        Verse(book = "Nonm", chapter = 26, verseNumber = 58, text = "Men lòt fanmi Levi yo: moun Libni yo, moun Ebwon yo, moun Makli yo, moun Mouchi yo ak moun Kore yo. Keyat te papa Amram.", bookId = 4),
        Verse(book = "Nonm", chapter = 26, verseNumber = 59, text = "Madan Amram te rele Yokebèd. Se te yon pitit fi Levi. Li te fèt nan peyi Lejip. Li te fè twa pitit pou Amram: Arawon, Moyiz ak Miryam, sè yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 26, verseNumber = 60, text = "Arawon te papa kat pitit gason: Nadab, Abiyou, Eleaza ak Itama.", bookId = 4),
        Verse(book = "Nonm", chapter = 26, verseNumber = 61, text = "Nadab ak Abiyou te mouri lè yo te ofri bay Seyè a yon dife yo pa t' dwe ofri.", bookId = 4),
        Verse(book = "Nonm", chapter = 26, verseNumber = 62, text = "Lè resansman an, yo te jwenn nan branch fanmi sa a venntwamil (23.000) gason ki te gen yon mwa depi yo te fèt osinon ki te pi gran. Yo pa t' konte yo ansanm ak rès pèp Izrayèl la, paske yo pa t'ap resevwa okenn pòsyon nan tè ki pou pèp la.", bookId = 4),
        Verse(book = "Nonm", chapter = 26, verseNumber = 63, text = "Men tout moun Moyiz ak Eleaza te konte lè yo t'ap fè resansman moun pèp Izrayèl la nan plenn Moab yo, lòt bò larivyè Jouden, anfas lavil Jeriko.", bookId = 4),
        Verse(book = "Nonm", chapter = 26, verseNumber = 64, text = "Pami yo pa t' gen yonn menm nan sa Moyiz ak Arawon te konte lè yo t'ap fè premye resansman pèp Izrayèl la nan dezè Sinayi a.", bookId = 4),
        Verse(book = "Nonm", chapter = 26, verseNumber = 65, text = "Paske Seyè a te di yo tout gen pou mouri nan dezè a. Yo tout te mouri vre, esepte Kaleb, pitit gason Jefoune a ak Jozye, pitit gason Noun lan.", bookId = 4),
        Verse(book = "Nonm", chapter = 27, verseNumber = 1, text = "Lè sa a, te gen nan branch fanmi Manase a senk fi, Mala, Noa, Ogla, Milka ak Tiza. Yo tout te pitit fi Zelochad. Zelochad sa a te pitit gason Efè. Efè te pitit gason Galarad, ki te pitit gason Maki, ki li menm te pitit gason Manase, ki te pitit gason Jozèf.", bookId = 4),
        Verse(book = "Nonm", chapter = 27, verseNumber = 2, text = "Medam yo vini, yo kanpe devan Moyiz ak Eleaza, prèt la, devan chèf fanmi yo ak devan tout pèp la, devan pòt Tant Randevou a, epi yo di:", bookId = 4),
        Verse(book = "Nonm", chapter = 27, verseNumber = 3, text = "-Papa nou mouri nan dezè a san li pa kite okenn pitit gason. Li pa t' fè pati bann moun Kore yo ki te revòlte kont Seyè a. Se poutèt pwòp peche pa l' yo kifè li mouri san li pa t' gen tan gen pitit gason.", bookId = 4),
        Verse(book = "Nonm", chapter = 27, verseNumber = 4, text = "Se pa paske papa nou pa t' gen pitit gason kifè pou non li disparèt nan fanmi an. Ban nou yon pòsyon tè tou nan mitan fanmi papa nou.", bookId = 4),
        Verse(book = "Nonm", chapter = 27, verseNumber = 5, text = "Moyiz al pale koze a avèk Seyè a.", bookId = 4),
        Verse(book = "Nonm", chapter = 27, verseNumber = 6, text = "Seyè a di l' konsa;", bookId = 4),
        Verse(book = "Nonm", chapter = 27, verseNumber = 7, text = "-Pitit fi Zelochad yo gen rezon. W'a ba yo yon pòsyon tè ki va rete pou yo nan mitan fanmi papa yo. W'a ba yo pòsyon tè ki te pou papa yo a.", bookId = 4),
        Verse(book = "Nonm", chapter = 27, verseNumber = 8, text = "Apre sa, w'a pale ak moun pèp Izrayèl yo, w'a di yo konsa: Si yon moun mouri san li pa kite pitit gason, n'a renmèt pòsyon tè pa l' la bay pitit fi li yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 27, verseNumber = 9, text = "Si li pa gen pitit fi, n'a renmèt pòsyon tè pa l' la bay frè l' yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 27, verseNumber = 10, text = "Si li pa gen frè, n'a renmèt tè a bay frè papa l' yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 27, verseNumber = 11, text = "Si papa l' pa t' gen frè, n'a renmèt li bay fanmi pi pre l' la. Epi tè a va rete pou li. Se pou moun pèp Izrayèl yo swiv regleman sa a tankou yon lwa, jan mwen menm Seyè a, mwen te bay Moyiz lòd la.", bookId = 4),
        Verse(book = "Nonm", chapter = 27, verseNumber = 12, text = "Seyè a di Moyiz konsa: -Moute sou mòn Abarim. Voye je ou gade peyi mwen pral bay moun pèp Izrayèl yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 27, verseNumber = 13, text = "Lè w'a fin wè li, ou pral mouri, tankou Arawon, frè ou la.", bookId = 4),
        Verse(book = "Nonm", chapter = 27, verseNumber = 14, text = "paske nou tou de nou pa t' fè sa m' te di nou fè a nan dezè Zin lan. Lè pèp la t'ap chache m' kont bò sous dlo Meriba yo, nou te refize kite m' fè yo wè pouvwa mwen nan zafè dlo a. (Meriba se sous dlo bò Kadès nan dezè Zin lan.)", bookId = 4),
        Verse(book = "Nonm", chapter = 27, verseNumber = 15, text = "Lè sa a, Moyiz pale ak Seyè a, li di l' konsa:", bookId = 4),
        Verse(book = "Nonm", chapter = 27, verseNumber = 16, text = "-O Seyè, Bondye ki bay tout moun lavi, tanpri, chwazi yon nonm ki ka mennen pèp la,", bookId = 4),
        Verse(book = "Nonm", chapter = 27, verseNumber = 17, text = "yon nonm ki ka mache alatèt yo nan tout antre soti yo, pou pèp ou a, pèp Seyè a, pa rete tankou yon bann mouton san gadò pou okipe yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 27, verseNumber = 18, text = "Seyè a reponn Moyiz: -Pran Jozye, pitit gason Noun lan. Se yon nonm ki gen lespri Bondye k'ap travay nan kè l'. W'a mete men ou sou tèt li,", bookId = 4),
        Verse(book = "Nonm", chapter = 27, verseNumber = 19, text = "epi w'a fè l' kanpe devan Eleaza, prèt la, ak devan tout pèp la. Epi la, devan yo tout, w'a ba li tout lòd ou gen pou ba li.", bookId = 4),
        Verse(book = "Nonm", chapter = 27, verseNumber = 20, text = "W'a separe avè l' pouvwa otorite ou genyen an, pou tout moun nan pèp Izrayèl la ka obeyi l'.", bookId = 4),
        Verse(book = "Nonm", chapter = 27, verseNumber = 21, text = "L'a toujou kanpe devan Eleaza, prèt la, ki va sèvi ak Ourim yo pou chache konnen sa mwen vle yo fè. Se konsa, Eleaza va dirije Jozye ak tout pèp la nan tout antre soti yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 27, verseNumber = 22, text = "Moyiz fè jan Seyè a te ba li lòd fè a. Li pran Jozye, li fè l' kanpe devan Eleaza, prèt la, ak tout pèp la.", bookId = 4),
        Verse(book = "Nonm", chapter = 27, verseNumber = 23, text = "Li mete men l' sou tèt li, epi li ba li lòd li yo, jan Seyè a te di l' la.", bookId = 4),
        Verse(book = "Nonm", chapter = 28, verseNumber = 1, text = "Seyè a pale ak Moyiz, li di l' konsa:", bookId = 4),
        Verse(book = "Nonm", chapter = 28, verseNumber = 2, text = "-Men lòd w'a bay moun pèp Izrayèl yo. W'a di yo pou mwen: Se pou yo toujou chonje dat pou yo fè ofrann yo, dat pou yo vin pote ofrann y'ap boule nèt pou mwen nan dife, ofrann k'ap fè m' plezi ak bon sant yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 28, verseNumber = 3, text = "W'a di yo pou mwen: Men ofrann pou nou boule nan dife pou Seyè a. Chak jou, san sote yonn, n'a ofri de ti mouton ki gen ennan, ki pa gen okenn enfimite. N'a boule yo nèt nan dife pou mwen.", bookId = 4),
        Verse(book = "Nonm", chapter = 28, verseNumber = 4, text = "N'a ofri premye ti mouton an nan maten, n'a ofri lòt la nan aswè.", bookId = 4),
        Verse(book = "Nonm", chapter = 28, verseNumber = 5, text = "Ansanm avèk chak ti mouton, n'a ofri sèt ti mamit farin frans melanje ak de boutèy ka plen pi bon kalite lwil oliv ou ka jwenn.", bookId = 4),
        Verse(book = "Nonm", chapter = 28, verseNumber = 6, text = "(Sa se ofrann pou yo boule nèt chak jou nan dife, ofrann yo te konn fè nan tan lontan sou mòn Sinayi a, tankou yon manje yo boule pou Seyè a, yon ofrann k'ap fè Seyè a plezi ak bon sant li.)", bookId = 4),
        Verse(book = "Nonm", chapter = 28, verseNumber = 7, text = "Avèk chak ti mouton, n'a ofri de boutèy ka bwason, n'a vide l' sou lotèl la pou Seyè a.", bookId = 4),
        Verse(book = "Nonm", chapter = 28, verseNumber = 8, text = "Nan aswè, n'a boule dezyèm ti mouton an menm jan nou te fè l' nan maten an. N'a fè ofrann farin frans lan tou ansanm ak bwason an. Se va yon manje n'a boule nèt pou Seyè a, yon ofrann k'ap fè Seyè a plezi ak bon sant li.", bookId = 4),
        Verse(book = "Nonm", chapter = 28, verseNumber = 9, text = "Pou jou repo a, n'a ofri de ti belye mouton ki gen ennan, ki san okenn enfimite, kat ti mamit farin frans melanje ak lwil oliv tankou ofrann grenn jaden ak yon ofrann bwason.", bookId = 4),
        Verse(book = "Nonm", chapter = 28, verseNumber = 10, text = "Chak jou repo, se pou nou fè ofrann sa yo an menm tan ak ofrann pou chak jou yo ansanm ak ofrann bwason yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 28, verseNumber = 11, text = "Nan konmansman chak mwa, n'a fè yon ofrann boule pou Seyè a. Lè sa a, n'a ofri de towo bèf, yon belye mouton ak sèt ti mouton ki gen ennan. Epi fòk yo tout san okenn enfimite.", bookId = 4),
        Verse(book = "Nonm", chapter = 28, verseNumber = 12, text = "N'a fè yon ofrann grenn manje tou ansanm ak chak bèt. Pou chak towo bèf, n'a ofri vennkat ti mamit farin frans melanje ak lwil oliv. Pou chak belye mouton, n'a ofri katòz ti mamit farin frans tankou yon ofrann grenn manje.", bookId = 4),
        Verse(book = "Nonm", chapter = 28, verseNumber = 13, text = "Pou chak ti mouton, n'a ofri sèt ti mamit farin frans. Se va yon ofrann n'a boule nèt pou Seyè a, yon ofrann k'ap fè Seyè a plezi ak bon sant li.", bookId = 4),
        Verse(book = "Nonm", chapter = 28, verseNumber = 14, text = "N'a fè ofrann bwason tou: kat boutèy ka pou chak towo bèf, twa boutèy ka pou belye mouton an ak de boutèy ka pou chak ti mouton. Se ofrann sa yo n'a boule nèt pou Seyè a, nan konmansman chak mwa, pandan tout lanne a.", bookId = 4),
        Verse(book = "Nonm", chapter = 28, verseNumber = 15, text = "Anplis ofrann pou chak jou yo, w'a touye yon bouk pou mande padon pou peche, epi w'a ofri tou ofrann bwason ki toujou mache ansanm avè l' la.", bookId = 4),
        Verse(book = "Nonm", chapter = 28, verseNumber = 16, text = "Katòzyèm jou nan premye mwa a, n'a fete fèt Delivrans lan pou Seyè a.", bookId = 4),
        Verse(book = "Nonm", chapter = 28, verseNumber = 17, text = "Kenzyèm jou menm mwa a va yon gwo jou fèt. Pandan sèt jou, n'a manje pen ki fèt san ledven.", bookId = 4),
        Verse(book = "Nonm", chapter = 28, verseNumber = 18, text = "Sou premye jou a, n'a reyini tout moun pou vin adore Seyè a. Lè sa a, pesonn p'ap gen dwa fè okenn gwo travay.", bookId = 4),
        Verse(book = "Nonm", chapter = 28, verseNumber = 19, text = "N'a fè ofrann bèt pou yo boule nèt pou Seyè a: de jenn towo bèf, yon belye mouton ak sèt ti mouton ki gen ennan. Fòk yo tout san okenn enfimite.", bookId = 4),
        Verse(book = "Nonm", chapter = 28, verseNumber = 20, text = "N'a fè ofrann grenn jaden sou fòm farin frans melanje ak lwil oliv: venteyen ti mamit pou chak towo, katòz ti mamit pou belye mouton an,", bookId = 4),
        Verse(book = "Nonm", chapter = 28, verseNumber = 21, text = "ak sèt ti mamit pou chak ti mouton.", bookId = 4),
        Verse(book = "Nonm", chapter = 28, verseNumber = 22, text = "N'a ofri tou yon bouk pou yo touye pou mande padon pou peche. Se konsa, n'a fè ofrann bèt pou nou touye pou mande Bondye gras pou pèp la.", bookId = 4),
        Verse(book = "Nonm", chapter = 28, verseNumber = 23, text = "N'a fè tout ofrann sa yo anplis ofrann bèt nou gen pou nou boule chak maten san sote jou a.", bookId = 4),
        Verse(book = "Nonm", chapter = 28, verseNumber = 24, text = "Se va menm jan an tou pou tout sèt jou yo. Chak jou n'a ofri manje pou yo boule nèt pou Seyè a: se va tankou yon ofrann k'ap fè Seyè a plezi ak bon sant li. N'a fè ofrann sa a anplis ofrann bèt pou yo boule chak jou pou Seyè a ak ofrann bwason ki mache avè l' la.", bookId = 4),
        Verse(book = "Nonm", chapter = 28, verseNumber = 25, text = "Sou setyèm jou a, n'a reyini tout pèp la ankò pou n' fè sèvis pou Seyè a. Jou sa a, nou p'ap fè okenn gwo travay non plis.", bookId = 4),
        Verse(book = "Nonm", chapter = 28, verseNumber = 26, text = "Konsa tou, premye jou fèt premye rekòt la, lè n'ap pote ofrann grenn nou fèk rekòlte yo bay Seyè a, n'a reyini tout moun pou yo vin fè sèvis pou Bondye. Jou sa a, pesonn p'ap gen dwa fè okenn gwo travay.", bookId = 4),
        Verse(book = "Nonm", chapter = 28, verseNumber = 27, text = "Men bèt n'a ofri pou yo boule nèt nan dife pou Seyè a, ofrann ki va fè Seyè a plezi ak bon sant li: de jenn towo, yon belye mouton ak sèt ti mouton ki gen ennan. Fòk yo tout san okenn enfimite.", bookId = 4),
        Verse(book = "Nonm", chapter = 28, verseNumber = 28, text = "N'a fè ofrann grenn jaden yo tou sou fòm farin frans melanje ak lwil oliv: ki vle di venteyen ti mamit pou chak towo, katòz ti mamit pou belye mouton an", bookId = 4),
        Verse(book = "Nonm", chapter = 28, verseNumber = 29, text = "ak sèt ti mamit pou chak ti mouton yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 28, verseNumber = 30, text = "N'a ofri tou yon bouk pou mande Bondye padon pou peche. Se konsa n'a fè ofrann bèt pou yo touye pou mande Bondye gras pou tout pèp la.", bookId = 4),
        Verse(book = "Nonm", chapter = 28, verseNumber = 31, text = "N'a ofri bèt sa yo ansanm ak ofrann bwason ki mache avèk yo chak, anplis ofrann bèt pou yo boule chak jou a ansanm ak ofrann grenn jaden yo. Se pou tout bèt yo san okenn enfimite.", bookId = 4),
        Verse(book = "Nonm", chapter = 29, verseNumber = 1, text = "Premye jou setyèm mwa a, n'a sanble tout moun pou yo vin fè sèvis pou adore Bondye. Jou sa a, pesonn p'ap gen dwa fè okenn gwo travay. Se jou sa a tou, y'a kònen twonpèt yo pou fè konnen jou a rive.", bookId = 4),
        Verse(book = "Nonm", chapter = 29, verseNumber = 2, text = "Men bèt n'a ofri pou yo boule nèt nan dife pou Seyè a, men ofrann ki va fè Seyè a plezi ak bon sant li: yon jenn towo bèf, yon belye mouton ak sèt ti mouton ki gen ennan. Fòk yo tout san okenn enfimite.", bookId = 4),
        Verse(book = "Nonm", chapter = 29, verseNumber = 3, text = "N'a fè ofrann grenn jaden yo tou sou fòm farin frans melanje ak lwil oliv: ki vle di venteyen ti mamit farin frans pou towo a, katòz ti mamit pou belye mouton an,", bookId = 4),
        Verse(book = "Nonm", chapter = 29, verseNumber = 4, text = "ak sèt ti mamit pou chak ti mouton yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 29, verseNumber = 5, text = "N'a ofri tou yon bouk kabrit pou mande padon pou peche. Se konsa n'a fè ofrann bèt pou touye pou mande Bondye gras pou tout pèp la.", bookId = 4),
        Verse(book = "Nonm", chapter = 29, verseNumber = 6, text = "N'a fè ofrann sa yo anplis ofrann bèt pou yo boule nan dife chak premye jou nan mwa yo ansanm ak ofrann grenn jaden ki toujou mache avèk yo a, mete sou ofrann bèt pou yo boule chak jou a ansanm ak ofrann grenn jaden ak bwason ki toujou mache avè l' la. Se ofrann manje sa yo n'a boule nèt pou Seyè a. Se va ofrann k'ap fè Seyè a plezi ak bon sant yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 29, verseNumber = 7, text = "Dizyèm jou setyèm mwa a, n'a reyini tout moun pou yo vin fè sèvis pou Bondye. Jou sa a, tout moun va rete san manje. Pesonn p'ap gen dwa fè okenn travay.", bookId = 4),
        Verse(book = "Nonm", chapter = 29, verseNumber = 8, text = "N'a ofri bèt pou yo boule nèt nan dife pou Bondye. Se va yon ofrann ki va fè Seyè a plezi ak bon sant li. Men bèt n'a ofri: yon towo bèf, yon belye mouton, sèt ti mouton ki gen ennan. Fòk yo tout san okenn enfimite.", bookId = 4),
        Verse(book = "Nonm", chapter = 29, verseNumber = 9, text = "N'a fè ofrann grenn jaden ki pou mache ak chak bèt sou fòm farin frans melanje ak lwil oliv: ki vle di venteyen ti mamit farin pou towo bèf la, katòz ti mamit pou belye mouton an", bookId = 4),
        Verse(book = "Nonm", chapter = 29, verseNumber = 10, text = "ak sèt ti mamit pou chak ti mouton yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 29, verseNumber = 11, text = "N'a ofri tou yon bouk pou mande Bondye padon pou peche anplis ofrann bèt pou touye pou gran jou padon an, mete sou ofrann bèt pou yo boule chak jou a ansanm ak ofrann grenn jaden yo ak ofrann bwason ki mache ak yo a.", bookId = 4),
        Verse(book = "Nonm", chapter = 29, verseNumber = 12, text = "Kenzyèm jou setyèm mwa a, n'a reyini tout moun pou yo vin adore Bondye. Jou sa a, pesonn p'ap gen dwa fè okenn gwo travay. N'a fè yon fèt pou Seyè a pandan sèt jou.", bookId = 4),
        Verse(book = "Nonm", chapter = 29, verseNumber = 13, text = "Premye jou a, n'a ofri bèt pou yo boule nèt nan dife pou Seyè a, ofrann ki va fè Seyè a plezi ak bon sant li: Men bèt pou nou ofri: trèz towo bèf, de belye mouton, katòz ti mouton ki gen ennan. Fòk yo tout san okenn enfimite.", bookId = 4),
        Verse(book = "Nonm", chapter = 29, verseNumber = 14, text = "Men ofrann grenn jaden sou fòm farin frans melanje ak lwil oliv ki pou mache ak bèt yo: venteyen ti mamit farin frans pou chak towo, katòz ti mamit pou chak belye,", bookId = 4),
        Verse(book = "Nonm", chapter = 29, verseNumber = 15, text = "ak sèt ti mamit pou chak ti mouton, ansanm ak ofrann bwason ki pou mache ak yo chak.", bookId = 4),
        Verse(book = "Nonm", chapter = 29, verseNumber = 16, text = "N'a ofri tou yon bouk kabrit pou mande Bondye padon pou peche. N'a fè ofrann sa yo anplis ofrann pou nou boule nèt chak jou a ansanm ak ofrann grenn jaden ak ofrann diven ki pou mache avè l' yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 29, verseNumber = 17, text = "Dezyèm jou fèt la, n'a ofri douz towo bèf, de belye mouton ak katòz ti mouton ki gen ennan. Fòk yo tout san okenn enfimite.", bookId = 4),
        Verse(book = "Nonm", chapter = 29, verseNumber = 18, text = "Ansanm ak chak bèt n'a fè ofrann grenn jaden ak ofrann bwason ki pou mache ak yo, dapre regleman an.", bookId = 4),
        Verse(book = "Nonm", chapter = 29, verseNumber = 19, text = "Epi, anplis ofrann bèt nou fè pou yo boule nèt pou Seyè a chak jou ansanm ak ofrann grenn jaden ak ofrann bwason ki mache ak yo a, n'a ofri yon bouk kabrit pou yo touye pou mande Bondye padon pou peche.", bookId = 4),
        Verse(book = "Nonm", chapter = 29, verseNumber = 20, text = "Twazyèm jou fèt la, n'a ofri onz towo bèf, de belye mouton ak katòz ti mouton ki gen ennan. Fòk yo tout san okenn enfimite.", bookId = 4),
        Verse(book = "Nonm", chapter = 29, verseNumber = 21, text = "Ansanm ak chak bèt n'a fè ofrann grenn jaden ak ofrann bwason ki pou mache ak yo, dapre regleman an.", bookId = 4),
        Verse(book = "Nonm", chapter = 29, verseNumber = 22, text = "Epi, anplis ofrann bèt nou fè chak jou pou yo boule nèt pou Seyè a ansanm ak ofrann grenn jaden ak ofrann bwason ki mache ak yo a, n'a ofri yon bouk kabrit pou yo touye pou mande Bondye padon pou peche.", bookId = 4),
        Verse(book = "Nonm", chapter = 29, verseNumber = 23, text = "Katriyèm jou fèt la, n'a ofri dis towo bèf, de belye mouton ak katòz ti mouton ki gen ennan. Fòk yo tout san okenn enfimite.", bookId = 4),
        Verse(book = "Nonm", chapter = 29, verseNumber = 24, text = "Ansanm ak chak bèt n'a fè ofrann grenn jaden ak ofrann bwason ki pou mache ak yo, dapre regleman an.", bookId = 4),
        Verse(book = "Nonm", chapter = 29, verseNumber = 25, text = "Epi, anplis ofrann bèt nou fè chak jou pou yo boule nèt pou Seyè a ansanm ak ofrann grenn jaden ak ofrann bwason ki mache ak yo a, n'a ofri yon bouk kabrit pou yo touye pou mande Bondye padon pou peche.", bookId = 4),
        Verse(book = "Nonm", chapter = 29, verseNumber = 26, text = "Senkyèm jou fèt la, n'a ofri nèf towo, de belye mouton ak katòz ti mouton ki gen ennan. Fòk yo tout san okenn enfimite.", bookId = 4),
        Verse(book = "Nonm", chapter = 29, verseNumber = 27, text = "Ansanm ak chak bèt n'a fè ofrann grenn jaden ak ofrann bwason ki pou mache ak yo, dapre regleman an.", bookId = 4),
        Verse(book = "Nonm", chapter = 29, verseNumber = 28, text = "Epi, anplis ofrann bèt nou fè chak jou pou boule nèt pou Seyè a ansanm ak ofrann grenn jaden ak ofrann bwason ki mache ak yo a, n'a ofri yon bouk kabrit pou yo touye pou mande Bondye padon pou peche.", bookId = 4),
        Verse(book = "Nonm", chapter = 29, verseNumber = 29, text = "Sizyèm jou fèt la, n'a ofri wit towo, de belye mouton ak katòz ti mouton ki gen ennan. Fòk yo tout san okenn enfimite.", bookId = 4),
        Verse(book = "Nonm", chapter = 29, verseNumber = 30, text = "Ansanm ak chak bèt n'a fè ofrann grenn jaden ak ofrann bwason ki pou mache ak yo, dapre regleman an.", bookId = 4),
        Verse(book = "Nonm", chapter = 29, verseNumber = 31, text = "Epi, anplis ofrann bèt nou fè chak jou pou boule nèt pou Seyè a ansanm ak ofrann grenn jaden ak ofrann bwason ki mache ak yo a, n'a ofri yon bouk kabrit pou yo touye pou mande Bondye padon pou peche.", bookId = 4),
        Verse(book = "Nonm", chapter = 29, verseNumber = 32, text = "Setyèm jou fèt la, n'a ofri sèt towo, de belye mouton ak katòz ti mouton ki gen ennan. Fòk yo tout san okenn enfimite.", bookId = 4),
        Verse(book = "Nonm", chapter = 29, verseNumber = 33, text = "Ansanm ak chak bèt n'a fè ofrann grenn jaden ak ofrann bwason ki pou mache ak yo, dapre regleman an.", bookId = 4),
        Verse(book = "Nonm", chapter = 29, verseNumber = 34, text = "Epi, anplis ofrann bèt nou fè chak jou pou boule nèt pou Seyè a ansanm ak ofrann grenn jaden ak ofrann bwason ki mache ak yo a, n'a ofri yon bouk kabrit pou yo touye pou mande Bondye padon pou peche.", bookId = 4),
        Verse(book = "Nonm", chapter = 29, verseNumber = 35, text = "Wityèm jou fèt la, n'a sanble tout moun pou adore Bondye. Jou sa a, pesonn p'ap fè okenn gwo travay.", bookId = 4),
        Verse(book = "Nonm", chapter = 29, verseNumber = 36, text = "N'a fè ofrann bèt pou yo boule nèt nan dife, ofrann ki va fè Seyè a plezi ak bon sant li. Men bèt pou nou ofri: yon towo bèf, yon belye mouton ak sèt ti mouton ki gen ennan. Fòk yo tout san okenn enfimite.", bookId = 4),
        Verse(book = "Nonm", chapter = 29, verseNumber = 37, text = "Ansanm ak chak bèt n'a ofri ofrann grenn jaden ak ofrann bwason ki pou mache ak yo, dapre regleman an,", bookId = 4),
        Verse(book = "Nonm", chapter = 29, verseNumber = 38, text = "Epi, anplis ofrann bèt nou fè chak jou pou boule nèt pou Seyè a ansanm ak ofrann grenn jaden ak ofrann bwason ki mache ak yo, n'a ofri yon bouk kabrit pou yo touye pou mande Bondye padon pou peche yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 29, verseNumber = 39, text = "Men tou sa nou va ofri bay Seyè a lè n'ap fè gwo fèt nou dwe fè pou li yo, apa ofrann n'ap fè paske nou te pran angajman pou nou te fè yo, ou ankò ofrann n'ap fè paske nou rete konsa nou vle fè l', mete sou bèt n'ap ofri pou boule nèt nan dife pou Bondye, sou ofrann grenn jaden ak ofrann bwason yo, ak sou ofrann nou fè pou di Bondye mèsi.", bookId = 4),
        Verse(book = "Nonm", chapter = 29, verseNumber = 40, text = "Se konsa Moyiz te di pèp Izrayèl la tou sa Seyè a te ba li lòd di yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 30, verseNumber = 1, text = "Moyiz pale ak chèf branch fanmi pèp Izrayèl yo. Li di yo konsa: -Men lòd Seyè a bay.", bookId = 4),
        Verse(book = "Nonm", chapter = 30, verseNumber = 2, text = "Lè yon moun fè yon ve l'ap bay Seyè a kichòy ou ankò lè yon moun pwomèt li p'ap fè yon bagay, li pa fèt pou l' pa kenbe pawòl. Se pou l' fè tou sa li te pwomèt l'ap fè a.", bookId = 4),
        Verse(book = "Nonm", chapter = 30, verseNumber = 3, text = "Si yon jenn fi ki lakay papa l' toujou fè yon ve l'ap bay Seyè a kichòy ou ankò li pwomèt pou l' pa fè yon bagay,", bookId = 4),
        Verse(book = "Nonm", chapter = 30, verseNumber = 4, text = "lè papa a vin konn sa, si li pa di l' anyen, jenn fi a gen obligasyon pou l' kenbe ve li te pran an, osinon pwomès li te fè a.", bookId = 4),
        Verse(book = "Nonm", chapter = 30, verseNumber = 5, text = "Men, si lè papa a vin konn sa, li fè opozisyon, ni ve jenn fi a te pran yo ni pwomès li te fè yo pa kenbe ankò: yo pa vo anyen. Seyè a p'ap gade sou sa, li p'ap fè l' anyen, paske se pa fòt li. Se papa l' ki derefize kite l' kenbe pawòl li.", bookId = 4),
        Verse(book = "Nonm", chapter = 30, verseNumber = 6, text = "Si yon jenn fi te anba obligasyon pou l' te kenbe yon ve li te pran osinon yon pwomès li te fè, menm si li te pran yo an jwèt, si li rive marye,", bookId = 4),
        Verse(book = "Nonm", chapter = 30, verseNumber = 7, text = "epi mari a pa di l' anyen lè li vin konn sa, fi a gen obligasyon pou l' kenbe ve li te pran an osinon pwomès li te fè a.", bookId = 4),
        Verse(book = "Nonm", chapter = 30, verseNumber = 8, text = "Men, si jou mari a vin konn sa li fè opozisyon, lamenm li wete fanm lan anba obligasyon li te genyen pou l' te kenbe ve li te pran an osinon pwomès li te fè a. Seyè a p'ap gade sou sa, li p'ap fè l' anyen.", bookId = 4),
        Verse(book = "Nonm", chapter = 30, verseNumber = 9, text = "Men lè yon fanm ki vèv osinon ki divòse fè yon ve pou l' bay Seyè a kichòy, osinon li pwomèt pou l' pa fè yon bagay, se pou l' kenbe pawòl li.", bookId = 4),
        Verse(book = "Nonm", chapter = 30, verseNumber = 10, text = "Si yon madanm marye, antan li lakay mari l', pran yon ve pou fè kichòy osinon pwomèt pou l' pa fè yon bagay,", bookId = 4),
        Verse(book = "Nonm", chapter = 30, verseNumber = 11, text = "epi si lè mari l' vin konn sa, li pa di l' anyen, li pa fè okenn opozisyon, fanm lan gen obligasyon pou l' kenbe ve li te pran an osinon pwomès li te fè a, nenpòt kisa yo te ye.", bookId = 4),
        Verse(book = "Nonm", chapter = 30, verseNumber = 12, text = "Men, si mari a vin konn sa, epi menm jou li vin konn sa a, li di li pa dakò, fanm lan p'ap nan obligasyon pou l' kenbe pawòl ni pou ve li te pran an, ni pou pwomès li te fè a. Se mari a ki te derefize kite l' kenbe pawòl li. Konsa, Seyè a p'ap gade sou sa, li p'ap fè l' anyen.", bookId = 4),
        Verse(book = "Nonm", chapter = 30, verseNumber = 13, text = "Yon mari gen dwa dakò, konsa tou li gen dwa refize dakò kite madanm li kenbe pawòl li, ni pou ve madanm li te pran an, ni pou pwomès li te fè a.", bookId = 4),
        Verse(book = "Nonm", chapter = 30, verseNumber = 14, text = "Men, si apre mari a vin konn sa li kite yon jou pase, li pa di l' anyen ankò, sa vle di li dakò ak ve madanm li te pran an osinon ak pwomès madanm lan te fè a. Depi mari a pa di l' anyen lè li vin konn sa, sa vle di se dakò li dakò.", bookId = 4),
        Verse(book = "Nonm", chapter = 30, verseNumber = 15, text = "Men si, apre mari a vin konn angajman madanm lan te pran an, mari a kite kèk jou pase anvan li di li pa dakò, se li menm k'ap sibi chatiman ki pou ta tonbe sou madanm lan pou pawòl li pa kenbe a.", bookId = 4),
        Verse(book = "Nonm", chapter = 30, verseNumber = 16, text = "Men tout regleman Seyè a te bay Moyiz pou yon fanm ki fè ve osinon ki pran yon angajman. Si li marye, men tout jan mari a ka boule avè l' nan ka sa a. Si li poko marye, li lakay papa l' toujou, men tout jan papa a ka pran sa.", bookId = 4),
        Verse(book = "Nonm", chapter = 31, verseNumber = 1, text = "Seyè a pale ak Mwiz, li di l' konsa:", bookId = 4),
        Verse(book = "Nonm", chapter = 31, verseNumber = 2, text = "-Ou pral pini moun Madyan yo pou sa yo fè moun pèp Izrayèl yo pase. Apre sa, ou pral mouri pou ou al jwenn moun pa ou yo ki mouri deja.", bookId = 4),
        Verse(book = "Nonm", chapter = 31, verseNumber = 3, text = "Se konsa, Moyiz pale ak pèp la, li di yo konsa: -Pare kèk gason nan mitan nou pou y' al goumen, pou yo mache pran moun Madyan yo, fè yo peye sa yo fè Seyè a.", bookId = 4),
        Verse(book = "Nonm", chapter = 31, verseNumber = 4, text = "N'a pran mil gason nan chak branch fanmi pèp Izrayèl la pou n' voye al goumen.", bookId = 4),
        Verse(book = "Nonm", chapter = 31, verseNumber = 5, text = "Se konsa nan tout kantite gason ki nan pèp Izrayèl la, yo pran mil gason nan chak branch fanmi. Sa te bay douzmil (12.000) gason antou ki te pare pou al goumen.", bookId = 4),
        Verse(book = "Nonm", chapter = 31, verseNumber = 6, text = "Moyiz voye douzmil gason sa yo al fè lagè. Li voye ak yo Fineas, pitit gason Eleaza, prèt la, ki t'ap pote veso Bondye yo ak twonpèt pou bay siyal yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 31, verseNumber = 7, text = "Yo atake moun Madyan yo jan Seyè a te bay Moyiz lòd la, yo touye tout gason yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 31, verseNumber = 8, text = "Yo touye senk wa moun Madyan yo: Evi, Rekèm, Zou, Our ak Reba. Yo touye Balaram, pitit Beyò a, tou.", bookId = 4),
        Verse(book = "Nonm", chapter = 31, verseNumber = 9, text = "Moun Izrayèl yo fè tout fanm ak tout timoun Madyan yo prizonye. Yo pase men yo pran tout bèf yo, tout mouton yo, tout kabrit yo ak tout lòt byen yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 31, verseNumber = 10, text = "Yo boule tout kay nan lavil yo ak tout kan kote moun yo te rete.", bookId = 4),
        Verse(book = "Nonm", chapter = 31, verseNumber = 11, text = "Apre sa, yo pran tou sa yo te ranmase, tout bèt ak tout moun yo te fè prizonye yo,", bookId = 4),
        Verse(book = "Nonm", chapter = 31, verseNumber = 12, text = "yo mennen yo bay Moyiz ansanm ak Eleaza, prèt la, ak tout moun pèp Izrayèl yo ki te nan kan an, nan plenn Moab yo, lòt bò larivyè Jouden, anfas lavil Jeriko.", bookId = 4),
        Verse(book = "Nonm", chapter = 31, verseNumber = 13, text = "Moyiz, Eleaza, prèt la ak tout chèf pèp Izrayèl yo soti nan kan an al kontre lame a.", bookId = 4),
        Verse(book = "Nonm", chapter = 31, verseNumber = 14, text = "Moyiz move sou chèf reskonsab lame yo, sou chèf divizyon mil yo ak chèf konpayi san yo ki t'ap tounen soti nan lagè a.", bookId = 4),
        Verse(book = "Nonm", chapter = 31, verseNumber = 15, text = "Li di yo konsa: -Poukisa nou pa touye tout medam sa yo?", bookId = 4),
        Verse(book = "Nonm", chapter = 31, verseNumber = 16, text = "Se yo menm ki te swiv konsèy Balaram yo, se yo ki te lakòz moun pèp Izrayèl yo te vire do bay Bondye nan zafè Baal-Peyò a, kifè gwo malè nou konnen an te tonbe sou pèp Izrayèl la.", bookId = 4),
        Verse(book = "Nonm", chapter = 31, verseNumber = 17, text = "Se pou nou touye tout pitit gason yo. Se pou nou touye tout fanm ki kouche ak gason deja.", bookId = 4),
        Verse(book = "Nonm", chapter = 31, verseNumber = 18, text = "Men, n'a sove lavi tout jenn fi ki poko janm kouche ak gason. N'a pran yo pou nou.", bookId = 4),
        Verse(book = "Nonm", chapter = 31, verseNumber = 19, text = "Men, nou menm ki touye moun osinon ki manyen kadav moun mouri, nou pral rete sèt jou andeyò limit kan an. Sou twazyèm jou a ak sou setyèm jou a n'a fè sèvis pou mete nou nan kondisyon, nou menm ak tout prizonye nou yo, pou nou ka fè sèvis Bondye.", bookId = 4),
        Verse(book = "Nonm", chapter = 31, verseNumber = 20, text = "N'a fè sèvis pou mete tout rad ak tout bagay ki fèt ak po bèt, bagay ki fèt ak pwal kabrit, bagay ki fèt an bwa, nan kondisyon pou moun k'ap sèvi Bondye ka sèvi ak yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 31, verseNumber = 21, text = "Eleaza, prèt la, pale ak mesye ki te tounen soti nan lagè yo. Li di yo konsa: -Men yon regleman nou jwenn nan lòd Seyè a te bay Moyiz.", bookId = 4),
        Verse(book = "Nonm", chapter = 31, verseNumber = 22, text = "Tout moso lò, tout moso ajan, tout bout fè, tout moso kwiv, tout moso plon,", bookId = 4),
        Verse(book = "Nonm", chapter = 31, verseNumber = 23, text = "tou sa ki pa ka boule nan dife, n'a pase yo nan dife pou yo ka nan kondisyon sèvi pou moun k'ap sèvi Bondye. Men tou sa ki ka boule nan dife, se nan dlo yo mete apa pou sa a n'a pase yo pou yo ka nan kondisyon sèvi pou moun k'ap sèvi Bondye.", bookId = 4),
        Verse(book = "Nonm", chapter = 31, verseNumber = 24, text = "Sou setyèm jou a, n'a lave rad ki sou nou yo. Konsa n'a nan kondisyon pou nou fè sèvis Bondye. Se lè sa a n'a ka antre nan kan an.", bookId = 4),
        Verse(book = "Nonm", chapter = 31, verseNumber = 25, text = "Seyè a pale ak Moyiz, li di l' konsa:", bookId = 4),
        Verse(book = "Nonm", chapter = 31, verseNumber = 26, text = "-Ou menm, Moyiz ak Eleaza, prèt la, ansanm ak tout lòt chèf pèp Izrayèl yo, n'a konte tou sa lame a te ranmase nan lagè a, san bliye bèt yo ak prizonye yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 31, verseNumber = 27, text = "Apre sa, n'a separe tout bagay mwatye pou mwatye, mwatye pou moun ki te al goumen yo, mwatye pou rès moun pèp Izrayèl yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 31, verseNumber = 28, text = "Nan mwatye ki pou moun ki te al goumen yo, n'a wete yon pòsyon ki va tankou yon taks y'a peye pou Seyè a: sou chak senksan (500) moun, sou chak senksan bèt menm kalite, bèf, bourik, mouton, kabrit, w'a wete yonn pou Seyè a.", bookId = 4),
        Verse(book = "Nonm", chapter = 31, verseNumber = 29, text = "Sa w'a wete nan mwatye ki pou moun ki te al goumen yo, w'a bay Eleaza, prèt la, tankou yon bagay yo pran pou Seyè a.", bookId = 4),
        Verse(book = "Nonm", chapter = 31, verseNumber = 30, text = "Sou lòt mwatye ki rete pou rès moun pèp Izrayèl la, w'a pran yonn sou chak senkant moun, sou chak senkant bèt menm kalite, bèf, bourik, mouton, kabrit. Epi w'a bay moun Levi yo ki reskonsab Tant Randevou Seyè a.", bookId = 4),
        Verse(book = "Nonm", chapter = 31, verseNumber = 31, text = "Moyiz ak Eleaza, prèt la, te fè tout bagay jan Seyè a te bay Moyiz lòd fè a.", bookId = 4),
        Verse(book = "Nonm", chapter = 31, verseNumber = 32, text = "San konte sa sòlda yo te pran pou yo menm, men sa yo te pran nan men lènmi yo epi yo te pote bay Moyiz: sisanswasannkenzmil (675.000) mouton ak kabrit,", bookId = 4),
        Verse(book = "Nonm", chapter = 31, verseNumber = 33, text = "swasanndouzmil (72.000) bèf,", bookId = 4),
        Verse(book = "Nonm", chapter = 31, verseNumber = 34, text = "swasanteyenmil (61.000) bourik,", bookId = 4),
        Verse(book = "Nonm", chapter = 31, verseNumber = 35, text = "tranndemil (32.000) jenn fi ki poko janm kouche ak gason.", bookId = 4),
        Verse(book = "Nonm", chapter = 31, verseNumber = 36, text = "Yo pran mwatye ladan yo bay sòlda ki te al goumen yo. Epi yo wete sa ki pou Seyè a ladan l'. Sa te fè twasantrannsètmil senksan (337.500) mouton ak kabrit,", bookId = 4),
        Verse(book = "Nonm", chapter = 31, verseNumber = 37, text = "ak sisanswasannkenz (675) ladan yo pou Seyè a,", bookId = 4),
        Verse(book = "Nonm", chapter = 31, verseNumber = 38, text = "trannsimil (36.000) bèf ak swasanndouz ladan yo pou Seyè a,", bookId = 4),
        Verse(book = "Nonm", chapter = 31, verseNumber = 39, text = "trantmil senksan (30.500) bourik ak swasanteyen ladan yo pou Seyè a,", bookId = 4),
        Verse(book = "Nonm", chapter = 31, verseNumber = 40, text = "sèzmil (16.000) jenn fi ak trannde ladan yo pou Seyè a.", bookId = 4),
        Verse(book = "Nonm", chapter = 31, verseNumber = 41, text = "Se konsa, Moyiz renmèt bay Eleaza, prèt la, tou sa yo te wete pou Seyè a, jan Seyè a te bay Moyiz lòd la.", bookId = 4),
        Verse(book = "Nonm", chapter = 31, verseNumber = 42, text = "Lòt mwatye a te pou rès pèp Izrayèl la. Lè Moyiz fin wete sa ki te pou sòlda yo,", bookId = 4),
        Verse(book = "Nonm", chapter = 31, verseNumber = 43, text = "men sa ki te rete: twasantrannsètmil senksan (337.500) mouton ak kabrit,", bookId = 4),
        Verse(book = "Nonm", chapter = 31, verseNumber = 44, text = "trannsimil (36.000) bèf,", bookId = 4),
        Verse(book = "Nonm", chapter = 31, verseNumber = 45, text = "trantmil senksan (30.500) bourik ak", bookId = 4),
        Verse(book = "Nonm", chapter = 31, verseNumber = 46, text = "sèzmil (16.000) jenn fi.", bookId = 4),
        Verse(book = "Nonm", chapter = 31, verseNumber = 47, text = "Sou mwatye ki te pou rès moun pèp Izrayèl la, Moyiz pran yon moun sou chak senkant moun ak yon bèt sou chak senkant bèt menm kalite, li bay moun Levi yo ki te reskonsab tant Seyè a, jan Seyè a te bay Moyiz lòd la.", bookId = 4),
        Verse(book = "Nonm", chapter = 31, verseNumber = 48, text = "Lè sa a, tout moun ki te chèf lame a, chèf divizyon mil yo ak chèf konpayi san yo, yo tout vin jwenn Moyiz.", bookId = 4),
        Verse(book = "Nonm", chapter = 31, verseNumber = 49, text = "Epi yo di l': -Nou konte kantite sòlda ki te sou kont nou yo, nou jwenn yo tout la.", bookId = 4),
        Verse(book = "Nonm", chapter = 31, verseNumber = 50, text = "Se poutèt sa, n'ap pote tout bijou lò nou te jwenn epi nou te pran: braslè, chennèt, bag, zanno, chenn ak meday, n'ap ofri yo bay Seyè a pou li ka fè nou gras.", bookId = 4),
        Verse(book = "Nonm", chapter = 31, verseNumber = 51, text = "Moyiz ak Eleaza, prèt la, resevwa tout bijou lò yo te pote yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 31, verseNumber = 52, text = "Sa te fè katsan (400) liv konsa chèf divizyon mil yo ak chèf konpayi san yo te pote bay Moyiz ak Eleaza ki te resevwa yo pou Seyè a.", bookId = 4),
        Verse(book = "Nonm", chapter = 31, verseNumber = 53, text = "Men, sòlda yo menm te kenbe sa yo te pran pou tèt pa yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 31, verseNumber = 54, text = "Se konsa Moyiz ak Eleaza, prèt la, pran lò chèf divizyon mil ak chèf konpayi san yo te pote ba yo a, yo pote l' nan Tant Randevou a, pou Seyè a te ka toujou chonje pwoteje pèp Izrayèl la.", bookId = 4),
        Verse(book = "Nonm", chapter = 32, verseNumber = 1, text = "Moun branch fanmi Woubenn ak moun branch fanmi Gad yo te gen anpil anpil bèt. Lè yo wè jan peyi Jazè a ak peyi Galarad la te bon pou fè gadinaj,", bookId = 4),
        Verse(book = "Nonm", chapter = 32, verseNumber = 2, text = "yo vin jwenn Moyiz, Eleaza, prèt la, ak chèf fanmi pèp Izrayèl yo, yo di yo konsa:", bookId = 4),
        Verse(book = "Nonm", chapter = 32, verseNumber = 3, text = "-Tout rejyon kote nou jwenn lavil sa yo: Atawo, Dibon, Jazè, Nimra, Esbon, Eleyale, Sèbam, Nebo ak Biyon,", bookId = 4),
        Verse(book = "Nonm", chapter = 32, verseNumber = 4, text = "tout peyi Seyè a te ede moun pèp Izrayèl yo pran pou yo bò isit la, se tè ki bon pou fè gadinaj, lèfini nou menm nou gen anpil bèt.", bookId = 4),
        Verse(book = "Nonm", chapter = 32, verseNumber = 5, text = "Tanpri, si ou vle fè nou favè sa a, ban nou peyi sa a pou pòsyon pa nou. Pa fòse nou janbe lòt bò larivyè Jouden an.", bookId = 4),
        Verse(book = "Nonm", chapter = 32, verseNumber = 6, text = "Moyiz reponn yo: -Nou ta renmen rete isit la pandan lòt frè nou yo pral nan goumen?", bookId = 4),
        Verse(book = "Nonm", chapter = 32, verseNumber = 7, text = "Poukisa nou vle dekouraje moun pèp Izrayèl yo pou yo pa ale nan peyi Seyè a ba yo a?", bookId = 4),
        Verse(book = "Nonm", chapter = 32, verseNumber = 8, text = "Se menm bagay la zansèt nou yo te fè wi lè mwen te voye yo ale vizite peyi a antan nou te Kadès Banea.", bookId = 4),
        Verse(book = "Nonm", chapter = 32, verseNumber = 9, text = "Yo moute jouk nan ravin Echkòl la, yo vizite tout peyi a. Apre sa, yo dekouraje moun pèp Izrayèl yo pou yo pa antre nan peyi Seyè a te ba yo a.", bookId = 4),
        Verse(book = "Nonm", chapter = 32, verseNumber = 10, text = "Jou sa a, Seyè a te move anpil sou yo. Li sèmante, li di konsa:", bookId = 4),
        Verse(book = "Nonm", chapter = 32, verseNumber = 11, text = "Okenn nan gason ki te gen ventan osinon ki te pi gran lè yo te soti kite peyi Lejip p'ap mete pwent pye yo nan peyi mwen te pwomèt sou sèman m'ap bay Abraram, Izarak ak Jakòb la, paske yo pa t' kenbe pawòl yo ak mwen,", bookId = 4),
        Verse(book = "Nonm", chapter = 32, verseNumber = 12, text = "an wetan Kalèb, pitit gason Jefoune, moun fanmi Kenaz yo, ak Jozye, pitit gason Noun lan. Se yo menm sèlman ki te toujou swiv Seyè a san mank.", bookId = 4),
        Verse(book = "Nonm", chapter = 32, verseNumber = 13, text = "Se konsa, Seyè a fè yon sèl move sou pèp Izrayèl la, li fè yo moute desann nan dezè a pandan karantan, jouk dènye moun ki te fè sa ki mal devan Seyè a mouri.", bookId = 4),
        Verse(book = "Nonm", chapter = 32, verseNumber = 14, text = "Epi koulye a, nou vle fè tankou papa nou yo? Ou byen wè se pitit yo nou ye vre! Nou pral fè Seyè a pi move ankò sou pèp Izrayèl la.", bookId = 4),
        Verse(book = "Nonm", chapter = 32, verseNumber = 15, text = "Si nou vire do nou ba li, l'a fè pèp la rete pi lontan ankò nan dezè a. Se nou menm ki va lakòz pèp la fini nèt.", bookId = 4),
        Verse(book = "Nonm", chapter = 32, verseNumber = 16, text = "Yo pwoche bò Moyiz, yo di l' konsa: -Pou konmanse, nou ta renmen moute kloti ak wòch pou fèmen pak bèt nou yo, epi nou ta renmen bati lavil ak ranpa pou pitit nou yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 32, verseNumber = 17, text = "Men, nou menm gason yo, nou tou pare pou n' ale goumen ansanm ak rès moun pèp Izrayèl yo, pou nou pran devan lè n'ap atake lènmi jouk yo rive nan peyi ki pou yo a. Pandan tan sa a, moun pa nou yo menm va rete isit la nan lavil ak ranpa yo kote moun peyi a p'ap ka fè yo anyen.", bookId = 4),
        Verse(book = "Nonm", chapter = 32, verseNumber = 18, text = "Nou p'ap tounen lakay nou toutotan tout lòt moun nan pèp Izrayèl la poko jwenn pòsyon tè ki pou yo a.", bookId = 4),
        Verse(book = "Nonm", chapter = 32, verseNumber = 19, text = "Nou p'ap pran anyen nan tè ki pou yo lòt bò larivyè Jouden an, paske yo ban nou tè ki bò isit larivyè Jouden an, sou kote solèy leve a, pou pòsyon pa nou.", bookId = 4),
        Verse(book = "Nonm", chapter = 32, verseNumber = 20, text = "Moyiz di yo konsa: -Si nou fè tou sa nou sot di la a, si vreman vre nou pare pou n' al goumen devan Seyè a,", bookId = 4),
        Verse(book = "Nonm", chapter = 32, verseNumber = 21, text = "si tout gason ki ka goumen pami nou yo janbe lòt bò larivyè Jouden an devan Seyè a, jouk Seyè a va fin kraze tout lènmi l' yo devan li,", bookId = 4),
        Verse(book = "Nonm", chapter = 32, verseNumber = 22, text = "enben, apre tout peyi a va tonbe anba men Seyè a, n'a tounen vin lakay nou, paske n'a fin fè tou sa nou te dwe fè pou Seyè a ak pou pèp Izrayèl la. Lè sa a, tout peyi ki bò isit la va rele nou pa nou devan Seyè a.", bookId = 4),
        Verse(book = "Nonm", chapter = 32, verseNumber = 23, text = "Men, si nou pa fè tou sa, konnen se kont Seyè a menm n'a peche. N'a peye konsekans peche nou an.", bookId = 4),
        Verse(book = "Nonm", chapter = 32, verseNumber = 24, text = "Nou mèt bati lavil ak ranpa pou moun pa nou yo. Nou mèt moute lantouraj pou mete bèt nou yo nan pak. Men, se pou nou fè sa nou pwomèt n'ap fè a.", bookId = 4),
        Verse(book = "Nonm", chapter = 32, verseNumber = 25, text = "Moun fanmi Woubenn yo ak moun fanmi Gad yo di konsa: -Mèt, n'ap fè tou sa ou mande nou fè.", bookId = 4),
        Verse(book = "Nonm", chapter = 32, verseNumber = 26, text = "Pitit nou yo va rete nan lavil ki nan peyi Galarad yo ansanm ak madanm nou yo ak tout bèf, tout mouton ak tout kabrit nou yo,", bookId = 4),
        Verse(book = "Nonm", chapter = 32, verseNumber = 27, text = "Men, nou menm gason ki pare pou n' al goumen yo, n'ap pase devan Seyè a pou n' al fè lagè jan ou di l' la.", bookId = 4),
        Verse(book = "Nonm", chapter = 32, verseNumber = 28, text = "Lè sa a, Moyiz bay Eleaza, prèt la, Jozye, pitit gason Noun lan, ak tout chèf fanmi pèp Izrayèl la lòd sa a sou moun sa yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 32, verseNumber = 29, text = "Li di yo: -Si gason nan branch fanmi Woubenn ak nan branch fanmi Gad yo janbe lòt bò larivyè Jouden an avèk nou tou pare pou y' al goumen devan Seyè a, lè tout peyi a va anba men nou, n'a ba yo tè peyi Galarad la pou yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 32, verseNumber = 30, text = "Men, si yo pa janbe lòt bò larivyè Jouden an pou y' al goumen avèk nou, y'a resevwa pòsyon tè pa yo nan peyi Kanaran an ansanm ak nou.", bookId = 4),
        Verse(book = "Nonm", chapter = 32, verseNumber = 31, text = "Mesye branch fanmi Woubenn ak branch fanmi Gad yo reponn Moyiz, yo di l' konsa: -N'a fè tou sa Seyè a mande nou fè. Se sèvitè li nou ye.", bookId = 4),
        Verse(book = "Nonm", chapter = 32, verseNumber = 32, text = "N'a janbe lòt bò larivyè a tou pare pou n' al goumen devan Seyè a, n'a antre nan peyi Kanaran an. Men toutjan, nou mande pou yo ban nou pòsyon tè ki bò isit larivyè Jouden an pou nou.", bookId = 4),
        Verse(book = "Nonm", chapter = 32, verseNumber = 33, text = "Se konsa Moyiz pran tout peyi Amori ki te pou wa Siyon, ak peyi Bazan ki te pou wa Og, avèk tout lavil ki nan limit fwontyè peyi yo, li bay moun fanmi Gad yo, moun fanmi Woubenn yo ak mwatye moun ki nan fanmi Manase, pitit gason Jozèf la.", bookId = 4),
        Verse(book = "Nonm", chapter = 32, verseNumber = 34, text = "Moun fanmi Gad yo rebati tout lavil sa yo: Dibon, Atawòt, Awoyè,", bookId = 4),
        Verse(book = "Nonm", chapter = 32, verseNumber = 35, text = "Atawo, Sofam, Jaze ak Jobeya,", bookId = 4),
        Verse(book = "Nonm", chapter = 32, verseNumber = 36, text = "Bèt-Nimra, Bèt aran. Yo rebati yo avèk ranpa pou pwoteje yo, yo fè pak tou pou mouton ak kabrit.", bookId = 4),
        Verse(book = "Nonm", chapter = 32, verseNumber = 37, text = "Moun fanmi Woubenn yo menm rebati lavil sa yo: Esbon, Elealè, Kiryatayim,", bookId = 4),
        Verse(book = "Nonm", chapter = 32, verseNumber = 38, text = "Nebo, Baal Meyon ak Sibma. Yo te chanje non lavil Nebo ak Baal Meyon. Yo bay tout lavil yo rebati yo lòt non.", bookId = 4),
        Verse(book = "Nonm", chapter = 32, verseNumber = 39, text = "Moun fanmi Maki, pitit gason Manase a, pati pou peyi Galarad kote moun Amori yo te rete a. Yo anvayi tout peyi a, yo mete moun Amori yo deyò.", bookId = 4),
        Verse(book = "Nonm", chapter = 32, verseNumber = 40, text = "Se konsa tou, Moyiz bay moun fanmi Maki, pitit gason Manase a, peyi Galarad la pou yo rete.", bookId = 4),
        Verse(book = "Nonm", chapter = 32, verseNumber = 41, text = "Moun fanmi Jayi, pitit gason Manase a, al atake yon seri ti bouk. Yo anvayi yo epi yo rele yo Bouk Jayi.", bookId = 4),
        Verse(book = "Nonm", chapter = 32, verseNumber = 42, text = "Noba menm al atake lavil Kenat ak lòt ti bouk ki sou lòd li yo. l' anvayi l', epi li ba li non l'. Li rele l' Noba.", bookId = 4),
        Verse(book = "Nonm", chapter = 33, verseNumber = 1, text = "Men non tout kote moun Izrayèl yo te pase depi apre yo tout te soti kite peyi Lejip tankou yon lame, avèk Moyiz ak Arawon alatèt yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 33, verseNumber = 2, text = "Dapre lòd Seyè a te bay Moyiz, chak kote yo te rive, li te make non kote a anvan yo reprann vwayaj yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 33, verseNumber = 3, text = "Moun pèp Izrayèl yo te kite lavil Ranmsès jou ki te kenzyèm jou nan premye mwa a, yon jou apre premye Fèt Delivrans lan. Yo soti kite peyi a devan je tout moun peyi Lejip yo san pesonn pa di yo anyen.", bookId = 4),
        Verse(book = "Nonm", chapter = 33, verseNumber = 4, text = "Lè sa a, moun peyi Lejip yo t'ap antere premye pitit gason yo. Se Seyè a menm ki te touye yo. Se konsa li te fè wè li gen plis pouvwa pase bondye moun peyi Lejip yo", bookId = 4),
        Verse(book = "Nonm", chapter = 33, verseNumber = 5, text = "Moun pep Izrayèl yo kite lavil Ranmsès, yo rive yon kote ki rele Soukòt. Se la yo moute kan yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 33, verseNumber = 6, text = "Apre sa, yo kite Soukòt, y' al moute kan yo Etam ki sou limit dezè a.", bookId = 4),
        Verse(book = "Nonm", chapter = 33, verseNumber = 7, text = "Yo kite Elam, yo tounen sou Pi ayiwòt, ki anfas Baal-Sefon, bò solèy leve, epi yo moute kan yo devan Migdòl.", bookId = 4),
        Verse(book = "Nonm", chapter = 33, verseNumber = 8, text = "Yo kite Pi ayiwòt, yo travèse Lanmè Wouj la, yo rive nan dezè a. Yo pase twa jou ap mache nan dezè Etam lan, yo rive Mara kote yo moute kan yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 33, verseNumber = 9, text = "Yo kite Mara, yo rive Elim kote ki te gen douz sous dlo ak swasanndis pye palmis. Yo moute kan yo la.", bookId = 4),
        Verse(book = "Nonm", chapter = 33, verseNumber = 10, text = "Yo kite Elim, y' al moute kan yo toupre Lanmè Wouj la.", bookId = 4),
        Verse(book = "Nonm", chapter = 33, verseNumber = 11, text = "Yo kite Lanmè Wouj, y' al moute kan yo nan dezè Zin lan.", bookId = 4),
        Verse(book = "Nonm", chapter = 33, verseNumber = 12, text = "Yo kite dezè Zin lan, y' al moute kan yo Dofka.", bookId = 4),
        Verse(book = "Nonm", chapter = 33, verseNumber = 13, text = "Yo kite Dofka, y' al moute kan yo Alouch.", bookId = 4),
        Verse(book = "Nonm", chapter = 33, verseNumber = 14, text = "Yo kite Alouch, y' al moute kan yo Refidim kote pèp la pa t' jwenn dlo pou yo bwè a.", bookId = 4),
        Verse(book = "Nonm", chapter = 33, verseNumber = 15, text = "Yo kite Refidim, y' al moute kan yo nan dezè Sinayi a.", bookId = 4),
        Verse(book = "Nonm", chapter = 33, verseNumber = 16, text = "Yo kite dezè Sinayi a, y' al moute kan yo Simityè Grangou.", bookId = 4),
        Verse(book = "Nonm", chapter = 33, verseNumber = 17, text = "Yo kite Simityè Grangou, y' al moute kan yo Azewòt.", bookId = 4),
        Verse(book = "Nonm", chapter = 33, verseNumber = 18, text = "Yo kite Azewòt, y' al moute kan yo Ritma.", bookId = 4),
        Verse(book = "Nonm", chapter = 33, verseNumber = 19, text = "Yo kite Ritma, y' al moute kan yo Rimonn Perèz.", bookId = 4),
        Verse(book = "Nonm", chapter = 33, verseNumber = 20, text = "Yo kite Rimonn Perèz, y' al moute kan yo Libna.", bookId = 4),
        Verse(book = "Nonm", chapter = 33, verseNumber = 21, text = "Yo kite Libna, y' al moute kan yo Risa.", bookId = 4),
        Verse(book = "Nonm", chapter = 33, verseNumber = 22, text = "Yo kite Risa, y' al moute kan yo Keyelata.", bookId = 4),
        Verse(book = "Nonm", chapter = 33, verseNumber = 23, text = "Yo kite Keyelata, y' al moute kan yo sou mòn Chefè a.", bookId = 4),
        Verse(book = "Nonm", chapter = 33, verseNumber = 24, text = "Yo kite mòn Chefè a, y' al moute kan yo Arada.", bookId = 4),
        Verse(book = "Nonm", chapter = 33, verseNumber = 25, text = "Yo kite Arada, y' al moute kan yo Makelòt.", bookId = 4),
        Verse(book = "Nonm", chapter = 33, verseNumber = 26, text = "Yo kite Makelòt, y' al moute kan yo Tayat.", bookId = 4),
        Verse(book = "Nonm", chapter = 33, verseNumber = 27, text = "Yo kite Tayat, y' al moute kan yo Tara.", bookId = 4),
        Verse(book = "Nonm", chapter = 33, verseNumber = 28, text = "Yo kite Tara, y' al moute kan yo Mitka.", bookId = 4),
        Verse(book = "Nonm", chapter = 33, verseNumber = 29, text = "Yo kite Mitka, y' al moute kan yo Asmona.", bookId = 4),
        Verse(book = "Nonm", chapter = 33, verseNumber = 30, text = "Yo kite Asmona, y' al moute kan yo Mosewòt.", bookId = 4),
        Verse(book = "Nonm", chapter = 33, verseNumber = 31, text = "Yo kite Mosewòt, y' al moute kan yo Benè-Jakan.", bookId = 4),
        Verse(book = "Nonm", chapter = 33, verseNumber = 32, text = "Yo kite Benè-Jakan, y' al moute kan yo Ogidgad.", bookId = 4),
        Verse(book = "Nonm", chapter = 33, verseNumber = 33, text = "Yo kite Ogidgad, y' al moute kan yo Jotbata.", bookId = 4),
        Verse(book = "Nonm", chapter = 33, verseNumber = 34, text = "Yo kite Jotbata, y' al moute kan yo Abwona.", bookId = 4),
        Verse(book = "Nonm", chapter = 33, verseNumber = 35, text = "Yo kite Abwona, y' al moute kan yo Ezyongebè.", bookId = 4),
        Verse(book = "Nonm", chapter = 33, verseNumber = 36, text = "Yo kite Ezyongebè, y' al moute kan yo nan dezè Zin lan, ki vle di Kadès.", bookId = 4),
        Verse(book = "Nonm", chapter = 33, verseNumber = 37, text = "Yo kite Kadès, y' al moute kan yo sou mòn Or, toupre fwontyè peyi Edon an.", bookId = 4),
        Verse(book = "Nonm", chapter = 33, verseNumber = 38, text = "Dapre lòd Seyè a te bay la, Arawon, prèt la, moute sou tèt mòn lan. Se la li mouri. Lè sa a, moun pèp Izrayèl yo te gen trantnevan kat mwa yon jou depi yo te soti kite peyi Lejip.", bookId = 4),
        Verse(book = "Nonm", chapter = 33, verseNumber = 39, text = "Lè Arawon mouri sou mòn Or la, li te gen sanvenntwazan sou tèt li.", bookId = 4),
        Verse(book = "Nonm", chapter = 33, verseNumber = 40, text = "Wa Arad, yon moun Kanaran ki te rete nan pati sid peyi Kanaran yo rele Negèv la, vin konnen moun Izrayèl yo t'ap rive.", bookId = 4),
        Verse(book = "Nonm", chapter = 33, verseNumber = 41, text = "Se konsa, moun Izrayèl yo kite Mòn Or la, y' al moute kan yo Zalmona.", bookId = 4),
        Verse(book = "Nonm", chapter = 33, verseNumber = 42, text = "Yo kite Zalmona, y' al moute kan yo Pounon.", bookId = 4),
        Verse(book = "Nonm", chapter = 33, verseNumber = 43, text = "Yo kite Pounon, y' al moute kan yo Obòt.", bookId = 4),
        Verse(book = "Nonm", chapter = 33, verseNumber = 44, text = "Yo kite Obòt, y' al moute kan yo Ije abrarim nan peyi Moab la.", bookId = 4),
        Verse(book = "Nonm", chapter = 33, verseNumber = 45, text = "Yo kite Ije abrarim nan peyi Moab la, y' al moute kan yo Dibon Gad.", bookId = 4),
        Verse(book = "Nonm", chapter = 33, verseNumber = 46, text = "Yo kite Dibon Gad, y' al moute kan yo Almon-Diblatayim.", bookId = 4),
        Verse(book = "Nonm", chapter = 33, verseNumber = 47, text = "Yo kite Almon-Diblatayim, y' al moute kan yo sou mòn Abarim yo, anfas Mòn Nebò, bò solèy leve.", bookId = 4),
        Verse(book = "Nonm", chapter = 33, verseNumber = 48, text = "Yo kite mòn Abarim yo, y' al moute kan yo nan plenn Moab yo, lòt bò larivyè Jouden, anfas lavil Jeriko.", bookId = 4),
        Verse(book = "Nonm", chapter = 33, verseNumber = 49, text = "Yo te moute kan yo nan tout plenn Moab yo, toupre larivyè Jouden an, depi Bèt ayechimòt jouk Abèl-Chitim.", bookId = 4),
        Verse(book = "Nonm", chapter = 33, verseNumber = 50, text = "Antan yo la nan plenn Moab yo, toupre larivyè Jouden, anfas lavil Jeriko, Seyè a pale ak Moyiz, li di l' konsa:", bookId = 4),
        Verse(book = "Nonm", chapter = 33, verseNumber = 51, text = "-Men sa pou ou di moun pèp Izrayèl yo pou mwen. Lè n'a janbe lòt bò larivyè Jouden pou nou antre nan peyi Kanaran an,", bookId = 4),
        Verse(book = "Nonm", chapter = 33, verseNumber = 52, text = "se pou nou mete tout moun ki rete nan peyi a deyò. N'a kraze tout estati zidòl yo fè nan moul, osinon ki fèt ak wòch, n'a demoli mete atè dènye kay kote moun yo fè sèvis pou bondye yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 33, verseNumber = 53, text = "N'a pran peyi a pou nou, n'a rete ladan l' paske se mwen menm ki ban nou li pou bitasyon nou.", bookId = 4),
        Verse(book = "Nonm", chapter = 33, verseNumber = 54, text = "N'a tire osò pou nou ka separe l' bay chak branch fanmi pa yo. N'a bay branch fanmi ki anpil la yon gwo pòsyon. N'a bay branch fanmi ki pa anpil la yon ti pòsyon. Chak branch fanmi va resevwa pòsyon ki va vin pou l' a. Se konsa n'a separe tè a bay chak branch fanmi zansèt nou yo pa yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 33, verseNumber = 55, text = "Men, si nou pa mete moun ki rete nan peyi a deyò, sa ki va rete yo pral ban nou gwo pwoblèm. Y'ap tankou yon pay ki tonbe nan je nou, osinon tankou pikan k'ap pike nou nan tout kò nou. Yo pral tounen yon tizon pou nou lè n'a fin tabli nan peyi a.", bookId = 4),
        Verse(book = "Nonm", chapter = 33, verseNumber = 56, text = "Lè sa a, sa m' te fè lide fè yo a, se nou m'ap fè l'.", bookId = 4),
        Verse(book = "Nonm", chapter = 34, verseNumber = 1, text = "Seyè a pale ak Moyiz, li di l' konsa:", bookId = 4),
        Verse(book = "Nonm", chapter = 34, verseNumber = 2, text = "-Men lòd w'a bay moun Izrayèl yo pou mwen. Lè n'a antre nan peyi Kanaran mwen pral ban nou an, men fwontyè ki pral limite peyi a.", bookId = 4),
        Verse(book = "Nonm", chapter = 34, verseNumber = 3, text = "Sou bò sid la, n'a gen dezè Zin ki toupre Edon an pou limit. Fwontyè a va konmanse bò solèy leve nan pwent sid Lanmè Sale a.", bookId = 4),
        Verse(book = "Nonm", chapter = 34, verseNumber = 4, text = "L'a chankre desann nan direksyon sid bò pas Eskòpyon yo, l'a travèse dezè Zin lan, jouk li rive anba nèt bò Kadès-Banea. L'a pran direksyon nò, l'a moute bò Aza ada, l'a rive Achmon,", bookId = 4),
        Verse(book = "Nonm", chapter = 34, verseNumber = 5, text = "l'a chankre bò ravin ki sèvi fwontyè ak peyi Lejip la, epi l'a bout nan Lanmè Mediterane.", bookId = 4),
        Verse(book = "Nonm", chapter = 34, verseNumber = 6, text = "Sou bò solèy kouche, teritwa a nou an va rive jouk sou rivaj gwo lanmè a. Se Lanmè Mediterane a ki va sèvi nou fwontyè.", bookId = 4),
        Verse(book = "Nonm", chapter = 34, verseNumber = 7, text = "Sou bò nò a, fwontyè a va swiv yon liy dwat ki soti depi gwo lanmè a rive sou mòn Or la.", bookId = 4),
        Verse(book = "Nonm", chapter = 34, verseNumber = 8, text = "Antan nou la, n'a trase yon liy dwat ankò jouk nou rive nan Pas Amat la, ale pi lwen toujou jouk nou rive Zedad.", bookId = 4),
        Verse(book = "Nonm", chapter = 34, verseNumber = 9, text = "N'a pouse pi lwen toujou nan direksyon Zifwon jouk nou rive Aza-Enan. Men fwontyè nou sou bò nò a.", bookId = 4),
        Verse(book = "Nonm", chapter = 34, verseNumber = 10, text = "Fwontyè sou bò solèy leve a va soti Aza-Enan pou rive Chefam.", bookId = 4),
        Verse(book = "Nonm", chapter = 34, verseNumber = 11, text = "L'a desann soti Chefam nan direksyon Ribla, sou kote Ayen bò solèy leve. L'a desann pi ba toujou jouk l'a rive sou rivaj lanmè Galile a, sou bò solèy leve.", bookId = 4),
        Verse(book = "Nonm", chapter = 34, verseNumber = 12, text = "Fwontyè a va swiv larivyè Jouden an pou l' al bout sou lanmè Sale a. Men fwontyè k'ap limite peyi nou an sou kat bò.", bookId = 4),
        Verse(book = "Nonm", chapter = 34, verseNumber = 13, text = "Moyiz bay moun Izrayèl yo lòd sa yo: -Men peyi nou pral separe yonn ak lòt la. Nou pral tire osò pou fè sa. Men peyi Seyè a bay pou nèf branch fanmi ak mwatye yon branch fanmi nan pèp Izrayèl la.", bookId = 4),
        Verse(book = "Nonm", chapter = 34, verseNumber = 14, text = "Branch fanmi Woubenn lan ak branch fanmi Gad la ansanm ak mwatye nan branch fanmi Manase a deja resevwa tè pa yo, chak fanmi apa.", bookId = 4),
        Verse(book = "Nonm", chapter = 34, verseNumber = 15, text = "Yo resevwa pòsyon tè pa yo ki anfas lavil Jeriko, lòt bò larivyè Jouden, sou bò solèy leve.", bookId = 4),
        Verse(book = "Nonm", chapter = 34, verseNumber = 16, text = "Seyè a pale ak Moyiz, li di l' konsa:", bookId = 4),
        Verse(book = "Nonm", chapter = 34, verseNumber = 17, text = "-Men non moun ki pral fè pataj tè a pou nou: se va Eleaza, prèt la, Jozye, pitit gason Noun lan,", bookId = 4),
        Verse(book = "Nonm", chapter = 34, verseNumber = 18, text = "avèk douz chèf n'a chwazi pou fè pataj la, yonn nan chak branch fanmi.", bookId = 4),
        Verse(book = "Nonm", chapter = 34, verseNumber = 19, text = "Men non chèf yo. Pou branch fanmi Jida a, se va Kalèb, pitit gason Jefoune a.", bookId = 4),
        Verse(book = "Nonm", chapter = 34, verseNumber = 20, text = "Pou branch fanmi Simeyon an, se va Chemwèl, pitit gason Amiyoud la.", bookId = 4),
        Verse(book = "Nonm", chapter = 34, verseNumber = 21, text = "Pou branch fanmi Benjamen an, se va Elidad, pitit gason Kislòn lan.", bookId = 4),
        Verse(book = "Nonm", chapter = 34, verseNumber = 22, text = "Pou branch fanmi Dann lan, se va chèf Bouki, pitit gason Jogli a.", bookId = 4),
        Verse(book = "Nonm", chapter = 34, verseNumber = 23, text = "Pou branch fanmi Jozèf la, va gen chèf Aniyèl, pitit gason Efòd la, pou fanmi Manase a,", bookId = 4),
        Verse(book = "Nonm", chapter = 34, verseNumber = 24, text = "ak chèf Kemwèl, pitit gason Chiftan an, pou fanmi Efrayim lan.", bookId = 4),
        Verse(book = "Nonm", chapter = 34, verseNumber = 25, text = "Pou branch fanmi Zabilon an, se va chèf Elichafan, pitit gason Panak la.", bookId = 4),
        Verse(book = "Nonm", chapter = 34, verseNumber = 26, text = "Pou branch fanmi Isaka a, se va chèf Paltiyèl, pitit gason Azan an.", bookId = 4),
        Verse(book = "Nonm", chapter = 34, verseNumber = 27, text = "Pou branch fanmi Asè a, se va chèf Akiyoul, pitit gason Chelomi a.", bookId = 4),
        Verse(book = "Nonm", chapter = 34, verseNumber = 28, text = "Pou branch fanmi Neftali a, se va chèf Pedayèl, pitit gason Amiyoud la.", bookId = 4),
        Verse(book = "Nonm", chapter = 34, verseNumber = 29, text = "Men moun Seyè a te mete reskonsab pou fè pataj tè a pou bay chak moun nan pèp Izrayèl la pòsyon pa yo nan peyi Kanaran.", bookId = 4),
        Verse(book = "Nonm", chapter = 35, verseNumber = 1, text = "Antan yo nan plenn Moab yo, lòt bò larivyè Jouden, sou bò solèy leve anfas lavil Jeriko, Seyè a pale ak Moyiz, li di l' konsa:", bookId = 4),
        Verse(book = "Nonm", chapter = 35, verseNumber = 2, text = "-W'a bay moun pèp Izrayèl yo lòd pou yo pran nan pòsyon tè yo resevwa a kèk lavil pou yo bay moun Levi yo pou yo rete, ansanm ak savann ki toutotou lavil sa yo pou yo ka fè gadinaj.", bookId = 4),
        Verse(book = "Nonm", chapter = 35, verseNumber = 3, text = "Se nan lavil sa yo moun Levi yo va rete. Savann sa yo va rete pou yo, y'a sèvi pou zannimo yo ak pou tout lòt bèt y'a genyen.", bookId = 4),
        Verse(book = "Nonm", chapter = 35, verseNumber = 4, text = "Savann yo va toutotou lavil yo. Y'a mezire mil senksan (1.500) pye depi ranpa lavil la nan chak direksyon.", bookId = 4),
        Verse(book = "Nonm", chapter = 35, verseNumber = 5, text = "Konsa, savann yo va fè yon gwo teren kare kare ki va mezire twamil (3.000) pye sou chak bò: twamil pye sou bò lès, twamil pye sou bò lwès, twamil pye sou bò nò, twamil pye sou bò sid ak lavil la nan mitan l'. Y'a sèvi kote pou bèt moun Levi ki rete nan lavil la jwenn manje.", bookId = 4),
        Verse(book = "Nonm", chapter = 35, verseNumber = 6, text = "Nan lavil n'a bay moun Levi yo, gen sis ladan yo ki va sèvi pou bay moun ki touye moun pwoteksyon. Apa sis lavil sa yo, n'a bay moun Levi yo karannde lòt lavil ankò.", bookId = 4),
        Verse(book = "Nonm", chapter = 35, verseNumber = 7, text = "Antou, se pou nou bay moun Levi yo karantwit lavil ak tout savann pou bèt yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 35, verseNumber = 8, text = "Lè n'ap wete nan pòsyon ki pou pèp Izrayèl la lavil pou moun Levi yo, chak fanmi va bay dapre pòsyon tè li te resevwa. Sa ki gen pi gwo pòsyon an va bay plis. Sa ki gen ti pòsyon an va bay mwens.", bookId = 4),
        Verse(book = "Nonm", chapter = 35, verseNumber = 9, text = "Seyè a pale ak Moyiz, li di l' konsa:", bookId = 4),
        Verse(book = "Nonm", chapter = 35, verseNumber = 10, text = "-Pale ak moun pèp Izrayèl yo, di yo pou mwen. Lè n'a janbe lòt bò larivyè Jouden an pou nou antre nan peyi Kanaran an,", bookId = 4),
        Verse(book = "Nonm", chapter = 35, verseNumber = 11, text = "se pou nou chwazi kèk lavil kote yon moun ki touye yon lòt san li pa fè espre ka kouri chache pwoteksyon.", bookId = 4),
        Verse(book = "Nonm", chapter = 35, verseNumber = 12, text = "Se la y'a pwoteje l' anba fanmi mò a ki ta chache tire revanj mò a. Yo p'ap gen dwa touye l' toutotan yo pa jije l' devan tout moun.", bookId = 4),
        Verse(book = "Nonm", chapter = 35, verseNumber = 13, text = "Nan lavil n'a bay moun Levi yo, sis va sèvi pou bay moun konsa pwoteksyon,", bookId = 4),
        Verse(book = "Nonm", chapter = 35, verseNumber = 14, text = "twa lòt bò larivyè Jouden an sou bò solèy leve, twa bò isit nan peyi Kanaran an.", bookId = 4),
        Verse(book = "Nonm", chapter = 35, verseNumber = 15, text = "Sis lavil sa yo va sèvi ni pou moun peyi a ni pou moun lòt nasyon k'ap viv nan mitan nou osinon ki depasaj. Se la tout moun ki touye yon lòt san fè espre va kouri chache pwoteksyon.", bookId = 4),
        Verse(book = "Nonm", chapter = 35, verseNumber = 16, text = "Si yon moun frape yon lòt ak yon bout fè epi li touye l', se ansasen li ye, se pou yo touye l' tou.", bookId = 4),
        Verse(book = "Nonm", chapter = 35, verseNumber = 17, text = "Si yon moun bay yon lòt yon kout wòch epi li touye l', se ansasen li ye, se pou yo touye l' tou.", bookId = 4),
        Verse(book = "Nonm", chapter = 35, verseNumber = 18, text = "Si yon moun bay yon lòt yon kout bwa epi li touye l', se ansasen li ye, se pou yo touye l' tou.", bookId = 4),
        Verse(book = "Nonm", chapter = 35, verseNumber = 19, text = "Moun ki fanmi pi pre moun yo touye a va reskonsab pou li touye ansasen an, nenpòt kilè li bare avè l'.", bookId = 4),
        Verse(book = "Nonm", chapter = 35, verseNumber = 20, text = "Si yon moun rayi yon lòt epi li ba li yon move bourad pou li touye l', osinon si li voye yon bagay dèyè l' pou touye l',", bookId = 4),
        Verse(book = "Nonm", chapter = 35, verseNumber = 21, text = "oswa ankò, paske li pa vle wè l' li bat li ak koutpwen pou l' touye l', epi li touye l' vre, li gen pou l' mouri tou. Se yon ansasen li ye. Moun ki fanmi pi pre moun li touye a va reskonsab pou touye l' tou, nenpòt lè li bare avè l'.", bookId = 4),
        Verse(book = "Nonm", chapter = 35, verseNumber = 22, text = "Men, sipoze yon moun bay yon lòt yon move bourad san li pa fè espre, san li pa rayi l', osinon li voye yon bagay konsa konsa, epi l' al pran yon moun move kote san li pa t'ap voye l' dèyè l',", bookId = 4),
        Verse(book = "Nonm", chapter = 35, verseNumber = 23, text = "oswa ankò, sipoze li voye yon wòch epi li pa wè sa, wòch la al tonbe sou yon moun, li touye l' frèt, san li pa t' rayi moun lan ni li pa t'ap chache fè moun lan mal,", bookId = 4),
        Verse(book = "Nonm", chapter = 35, verseNumber = 24, text = "nan ka sa yo, men regleman pou moun pèp Izrayèl yo swiv pou yo regle bagay la ant moun ki te touye lòt la ak fanmi pi pre moun mouri a ki reskonsab pou tire revanj la.", bookId = 4),
        Verse(book = "Nonm", chapter = 35, verseNumber = 25, text = "Pèp la va sove moun ki te touye lòt la anba men fanmi pi pre moun li touye a, l'a fè l' tounen nan lavil kote li te al kache kò l' la. Moun ki te touye lòt la va rete la jouk granprèt ki la lè sa a pou fè sèvis Bondye a va mouri.", bookId = 4),
        Verse(book = "Nonm", chapter = 35, verseNumber = 26, text = "Si moun ki touye lòt la ta rive soti andeyò limit lavil kote li kache a,", bookId = 4),
        Verse(book = "Nonm", chapter = 35, verseNumber = 27, text = "si moun ki fanmi pi pre moun li touye a bare avè l', epi li touye l', yo pa gen dwa fè fanmi pre a peye pou sa l' fè a.", bookId = 4),
        Verse(book = "Nonm", chapter = 35, verseNumber = 28, text = "Paske moun ki touye yon lòt san li pa fè espre a fèt pou rete nan lavil kote li te kache a jouk granprèt ki la lè sa a va mouri. Se apre lanmò granprèt la ase l'a ka tounen lakay li.", bookId = 4),
        Verse(book = "Nonm", chapter = 35, verseNumber = 29, text = "Regleman sa yo va sèvi tankou yon lwa pou nou pou tout tan, de pitit an pitit, kote nou pase.", bookId = 4),
        Verse(book = "Nonm", chapter = 35, verseNumber = 30, text = "Lè yon moun touye yon lòt, anvan yo touye l', se pou yo gen depozisyon divès temwen kont li. Depozisyon yon sèl temwen pa kont pou kondannen yon moun.", bookId = 4),
        Verse(book = "Nonm", chapter = 35, verseNumber = 31, text = "Nou pa gen dwa asepte lajan pou sove lavi yon moun yo kondannen pou mouri paske li touye yon lòt. Wè pa wè se pou nonm sa a mouri.", bookId = 4),
        Verse(book = "Nonm", chapter = 35, verseNumber = 32, text = "Ni nou pa gen dwa asepte lajan pou penmèt yon moun ki kite lavil kote l' te kache a pou l' al lakay li anvan granprèt ki la lè sa a mouri.", bookId = 4),
        Verse(book = "Nonm", chapter = 35, verseNumber = 33, text = "Piga nou janm fè bagay ki pou fè Bondye vire do bay peyi kote nou pral viv la. Lè yon moun touye yon lòt moun, se sa k'ap mete peyi a nan kondisyon li derespekte Bondye ak san ki koule a. Lè konsa, pa gen lòt mwayen pou fè Bondye padonnen peyi a pase se touye pou nou touye moun ki touye a.", bookId = 4),
        Verse(book = "Nonm", chapter = 35, verseNumber = 34, text = "Piga nou janm fè bagay ki pou fè Bondye vire do bay peyi kote nou rete a, paske mwen menm Seyè a, se nan mitan moun pèp Izrayèl yo, nan mitan peyi kote yo rete a, mwen rete tou.", bookId = 4),
        Verse(book = "Nonm", chapter = 36, verseNumber = 1, text = "Moun branch fanmi Galarad yo se desandan Maki yo ye. Maki sa a se te pitit Manase, yonn nan de pitit Jozèf yo. Chèf fanmi moun Galarad yo al jwenn Moyiz ak lòt chèf branch fanmi pèp Izrayèl la,", bookId = 4),
        Verse(book = "Nonm", chapter = 36, verseNumber = 2, text = "yo di yo konsa: -Seyè a te ba ou, Moyiz, lòd pou ou te separe peyi a bay chak branch fanmi Izrayèl la pa yo dapre sa ki va soti pou yo lè y'a tire osò. Apre sa, Seyè a ta ba ou lòd pou ou te pran pòsyon ki pou Zelochad, fanmi nou an, pou ou bay pitit fi li yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 36, verseNumber = 3, text = "Men, si medam sa yo marye ak yon nonm ki fè pati yon lòt branch nan fanmi pèp Izrayèl la, pòsyon ki pou yo a pral soti sou tè zansèt pa nou yo. Konsa, pòsyon tè ki pou branch fanmi nonm yo marye a pral vin pi plis, epi pòsyon tè ki te vin pou nou an lè yo te tire osò a pral vin pi piti.", bookId = 4),
        Verse(book = "Nonm", chapter = 36, verseNumber = 4, text = "Lè lanne rejwisans lan va rive pou moun pèp Izrayèl yo, yo pral pran pòsyon tè ki te pou medam sa yo, yo pral wete l' nan pa branch fanmi zansèt nou yo, yo pral mete l' sou pa branch fanmi mari yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 36, verseNumber = 5, text = "Se konsa, dapre lòd Seyè a te ba li, Moyiz bay moun pèp Izrayèl yo regleman sa a pou yo swiv. Li di yo konsa: -Moun branch fanmi Jozèf yo gen rezon.", bookId = 4),
        Verse(book = "Nonm", chapter = 36, verseNumber = 6, text = "Se poutèt sa, men lòd Seyè a bay: Pitit fi Zelochad yo lib marye moun yo vle, depi se yon moun ki nan menm branch fanmi ak yo.", bookId = 4),
        Verse(book = "Nonm", chapter = 36, verseNumber = 7, text = "Pòsyon tè yon branch fanmi pa gen dwa pase pou yon lòt branch fanmi. Konsa, pòsyon tè yon fanmi va toujou rete nan fanmi an.", bookId = 4),
        Verse(book = "Nonm", chapter = 36, verseNumber = 8, text = "Si yon fi vin eritye yon pòsyon nan tè yonn nan branch fanmi pèp Izrayèl la, se pou l' marye ak yon moun ki nan menm branch fanmi avè l'. Konsa, chak moun va kenbe eritaj zansèt yo nan fanmi an.", bookId = 4),
        Verse(book = "Nonm", chapter = 36, verseNumber = 9, text = "Tè yon branch fanmi p'ap ka pase pou yon lòt branch fanmi. Konsa, pòsyon tè ki pou yon fanmi va toujou rete nan fanmi an.", bookId = 4),
        Verse(book = "Nonm", chapter = 36, verseNumber = 10, text = "Se konsa, pitit fi Zelochad yo fè jan Seyè a te bay Moyiz lòd la.", bookId = 4),
        Verse(book = "Nonm", chapter = 36, verseNumber = 11, text = "Mala, Tiza, Ogla, Milka ak Noa marye ak pitit gason tonton yo bò papa.", bookId = 4),
        Verse(book = "Nonm", chapter = 36, verseNumber = 12, text = "Yo marye nan branch fanmi Manase, pitit Jozèf la. Konsa, pòsyon tè papa yo a rete nan menm branch fanmi an.", bookId = 4),
        Verse(book = "Nonm", chapter = 36, verseNumber = 13, text = "Men tout lòd ak regleman Seyè a te bay Moyiz pou moun pèp Izrayèl yo, lè yo te nan plenn Moab yo, lòt bò larivyè Jouden, anfas lavil Jeriko.", bookId = 4)
    )
}
